INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES ('6', '1', 'Информация о доставке', '&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-size: 24px;&quot;&gt;&lt;b&gt;Самовывоз&lt;/b&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;br&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Вы можете забрать нужный вам товар в нашем магазине.&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;&lt;br&gt;После\r\nподтверждения заказа вы можете его забрать в любое удобное для вас время в часы\r\nработы магазина.&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-size: 18px;&quot;&gt;&lt;b&gt;Стоимость -&amp;nbsp;бесплатно.&lt;/b&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;&lt;p&gt;\r\n\r\n\r\n\r\n\r\n\r\n&lt;span style=&quot;font-size: 24px;&quot;&gt;&lt;b&gt;Курьером по Липецку&lt;/b&gt;&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Доставка осуществляется в рабочие дни:&amp;nbsp;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;br&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Пн-пят: 11:00 - 20:00&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;br&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Суб-вс: 11:00 - 19:00&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;br&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Без выходных&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;br&gt;&lt;b&gt;&lt;span style=&quot;font-size: 18px;&quot;&gt;Стоимость - 500₽.&lt;/span&gt;&lt;/b&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;o:p&gt;&amp;nbsp;&lt;/o:p&gt;&lt;/p&gt;', 'Информации о доставке интернет магазина Смарт Точка', '', '');
