INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('1', '1', 'Prostore theme', 'theme_prostore', '899themes.ru', '1.3.1', 'https://899themes.ru/prostore/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n	<name>Prostore theme</name>\r\n	<code>theme_prostore</code>\r\n	<version>1.3.1</version>\r\n	<author>899themes.ru</author>\r\n	<link>https://899themes.ru/prostore/</link>\r\n	<file path=\"admin/controller/catalog/category.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\neditCategory(\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[		\r\n			$this->clearCache(); // prostore added this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function delete\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[		\r\n// prostore start\r\n	  public function clearCache() { //Clear Cache for Menu\r\n		$this->cache->delete(\'category.categoriesdata\');\r\n		$this->cache->delete(\'category.categoriestopcat\');\r\n		$this->cache->delete(\'prostore.category\');\r\n		$this->cache->delete(\'navview\');\r\n		$this->cache->delete(\'navviewmobi\');\r\n	  }\r\n// prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/catalog/review.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->request->post[\'status\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore\r\n		$this->load->language(\'extension/theme/prostore_admin\');\r\n		$data[\'entry_text_plus\'] = $this->language->get(\'entry_text_plus\');\r\n		$data[\'entry_text_minus\'] = $this->language->get(\'entry_text_minus\');\r\n\r\n		$this->load->model(\'extension/theme/prostore\');\r\n		if (isset($this->request->get[\'review_id\']) && ($this->request->server[\'REQUEST_METHOD\'] != \'POST\')) {\r\n			$review_extr_info = $this->model_extension_theme_prostore->getExtrReview($this->request->get[\'review_id\']);\r\n		}\r\n\r\n	    if (isset($this->request->post[\'text_plus\'])) {\r\n	      $data[\'text_plus\'] = $this->request->post[\'text_plus\'];\r\n	    } elseif (!empty($review_extr_info)) {\r\n	      $data[\'text_plus\'] = $review_extr_info[\'text_plus\'];\r\n	    } else {\r\n	      $data[\'text_plus\'] = \'\';\r\n	    }\r\n	    if (isset($this->request->post[\'text_minus\'])) {\r\n	      $data[\'text_minus\'] = $this->request->post[\'text_minus\'];\r\n	    } elseif (!empty($review_extr_info)) {\r\n	      $data[\'text_minus\'] = $review_extr_info[\'text_minus\'];\r\n	    } else {\r\n	      $data[\'text_minus\'] = \'\';\r\n	    }\r\n	    if (isset($this->request->post[\'text_admin_answer\'])) {\r\n			$data[\'text_admin_answer\'] = $this->request->post[\'text_admin_answer\'];\r\n		  } elseif (!empty($review_extr_info)) {\r\n			$data[\'text_admin_answer\'] = $review_extr_info[\'text_admin_answer\'];\r\n		  } else {\r\n			$data[\'text_admin_answer\'] = \'\';\r\n		  }		\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/common/column_left.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$catalog = array();\r\n			]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[\r\n// prostore\r\n						\r\n			$this->load->language(\'extension/theme/prostore_admin\');\r\n			$prostore = array();\r\n			\r\n			if ($this->user->hasPermission(\'access\', \'extension/theme/prostore\')) {\r\n\r\n				$stores = $this->model_setting_store->getStores();\r\n				\r\n				if ($stores) {\r\n					\r\n					$prostore[] = array(\r\n						\'name\'	   => $this->language->get(\'text_theme_prostore\'),\r\n						\'href\'     => $this->url->link(\'extension/theme/prostore\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&store_id=0\', true),\r\n						\'children\' => array()		\r\n					);// fix collapse1 bug\r\n					\r\n					$prostore_store = array();\r\n\r\n					$prostore_store[] = array(\r\n							\'name\'	   => (utf8_strlen($this->config->get(\'config_name\')) > 12 ? utf8_substr($this->config->get(\'config_name\'), 0, 12) . \'..\' : $this->config->get(\'config_name\')),\r\n							\'href\'     => $this->url->link(\'extension/theme/prostore\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&store_id=0\', true),\r\n							\'children\' => array()		\r\n					);\r\n					\r\n					foreach ($stores as $store) {\r\n						$prostore_store[] = array(\r\n							\'name\'     => (utf8_strlen($store[\'name\']) > 12 ? utf8_substr($store[\'name\'], 0, 12) . \'..\' : $store[\'name\']),\r\n							\'href\'     => $this->url->link(\'extension/theme/prostore\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&store_id=\' . $store[\'store_id\'], true),\r\n							\'children\' => array()	\r\n						);\r\n					}\r\n\r\n					if ($prostore_store) {		\r\n						$prostore[] = array(\r\n							\'name\'	   => $this->language->get(\'text_theme_prostore_store\'),\r\n							\'href\'     => \'\',\r\n							\'children\' => $prostore_store		\r\n						);					\r\n					}\r\n					\r\n				} else {\r\n					\r\n					$prostore[] = array(\r\n						\'name\'	   => $this->language->get(\'text_theme_prostore\'),\r\n						\'href\'     => $this->url->link(\'extension/theme/prostore\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&store_id=0\', true),\r\n						\'children\' => array()		\r\n					);// fix collapse1 bug\r\n					\r\n					$prostore[] = array(\r\n						\'name\'	   => $this->language->get(\'text_theme_prostore\'),\r\n						\'href\'     => $this->url->link(\'extension/theme/prostore\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&store_id=0\', true),\r\n						\'children\' => array()		\r\n					);					\r\n				}\r\n			}\r\n\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/callback\')) {\r\n				$this->load->model(\'extension/theme/callback\');\r\n				$callbacks_new = $this->model_extension_theme_callback->getCallbackNew();\r\n\r\n				$callbacks_new = $callbacks_new[\'total\'];				\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_callback\') . ($callbacks_new > 0 ? \' <span class=\"badge\">\' . $callbacks_new . \'</span>\' : \'\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/callback\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/found_cheaper\')) {\r\n				$this->load->model(\'extension/theme/found_cheaper\');\r\n				$callcheapers_new = $this->model_extension_theme_found_cheaper->getCallCheaperNew();	\r\n\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_foundcheaper\') . ($callcheapers_new > 0 ? \' <span class=\"badge\">\' . $callcheapers_new . \'</span>\' : \'\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/found_cheaper\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_faq\')) {\r\n				$this->load->model(\'extension/theme/prostore_faq\');\r\n				$callFaq_new = $this->model_extension_theme_prostore_faq->getTotalNewFaqs();\r\n									\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_faq\') . ($callFaq_new > 0 ? \' <span class=\"badge\">\' . $callFaq_new . \'</span>\' : \'\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_faq\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}	\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore_review_shop\')) {\r\n				$this->load->model(\'extension/theme/prostore_review_shop\');\r\n				$shopReviews_new = $this->model_extension_theme_prostore_review_shop->getTotalNewReviews();					\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_review_shop\') . ($shopReviews_new > 0 ? \' <span class=\"badge\">\' . $shopReviews_new . \'</span>\' : \'\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore_review_shop/show\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}						\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/subscribe\')) {\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_subscribe\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/subscribe\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);	\r\n			}\r\n\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_sets\')) {		\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_sets\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_sets\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);					\r\n			}			\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_news\')) {		\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_news\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_news\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);					\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_tab\')) {		\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_tab\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_tab\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);					\r\n			}\r\n			\r\n			$blog = array();\r\n			\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_blog\')) {\r\n				$this->load->model(\'extension/theme/prostoreblog\');\r\n				$comments_new = $this->model_extension_theme_prostoreblog->getCommentNewCount(); \r\n				$comments_new = $comments_new[\'total\'];\r\n\r\n				$blog[] = array(\r\n					\'name\'     => $this->language->get(\'text_prostore_blog\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_blog\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()	\r\n				);\r\n			}\r\n			\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostorecat_blog\')) {\r\n				$blog[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostorecat_blog\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostorecat_blog\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostore_blog_banner\')) {\r\n				$blog[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_blog_banner\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostore_blog_banner\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);\r\n			}\r\n			if ($this->user->hasPermission(\'access\', \'extension/module/prostore/prostoreblog_review\')) {\r\n				$blog[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostoreblog_review\') . ($comments_new > 0 ? \' <span class=\"badge\">\' . $comments_new . \'</span>\' : \'\'),\r\n					\'href\'     => $this->url->link(\'extension/module/prostore/prostoreblog_review\', \'user_token=\' . $this->session->data[\'user_token\'], true),\r\n					\'children\' => array()		\r\n				);\r\n			}\r\n			\r\n			if ($blog) {		\r\n				$prostore[] = array(\r\n					\'name\'	   => $this->language->get(\'text_prostore_blog_main\') . ($comments_new > 0 ? \' <span class=\"badge\">\' . $comments_new . \'</span>\' : \'\'),\r\n					\'href\'     => \'\',\r\n					\'children\' => $blog		\r\n				);					\r\n			}\r\n			\r\n			if ($prostore) {\r\n				$prostore_alerts = $comments_new+$callbacks_new+$callFaq_new+$callcheapers_new;\r\n				if (isset($shopReviews_new)) {\r\n					$prostore_alerts += $shopReviews_new;\r\n				}\r\n\r\n				$data[\'menus\'][] = array(\r\n					\'id\'       => \'menu-prostore\',\r\n					\'icon\'	   => \'prostore\', \r\n					\'name\'	   => $this->language->get(\'text_prostore\') . ($prostore_alerts > 0 ? \' <span class=\"badge\">\' . $prostore_alerts . \'</span>\' : \'\'),\r\n					\'href\'     => \'\',\r\n					\'children\' => $prostore\r\n				);		\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/common/header.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'title\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[		\r\n		$this->document->addStyle(\'view/stylesheet/prostore/prostore-column-icon.css?2\');// prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/common/filemanager.php\">\r\n		<operation>\r\n			<search><![CDATA[{jpg]]></search>\r\n			<add position=\"replace\"><![CDATA[{jpg,svg,SVG]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\'gif\']]></search>\r\n			<add position=\"after\"><![CDATA[\'svg\',]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\'image/png\']]></search>\r\n			<add position=\"after\"><![CDATA[\'image/svg+xml\',]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/common/developer.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[DIR_IMAGE . \'cache/*\']]></search>\r\n			<add position=\"replace\"><![CDATA[DIR_IMAGE . \'{cache,cachewebp}/*\', GLOB_BRACE]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/controller/extension/module/filter.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'header\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		if (isset($this->request->post[\'module_filter_filter_grouptype\'])) {\r\n			$data[\'module_filter_filter_grouptype\'] = $this->request->post[\'module_filter_filter_grouptype\'];\r\n		} elseif($this->config->get(\'module_filter_filter_grouptype\')) {\r\n			$data[\'module_filter_filter_grouptype\'] = $this->config->get(\'module_filter_filter_grouptype\');\r\n		}else{\r\n			$data[\'module_filter_filter_grouptype\'] = 0;\r\n		}\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/model/catalog/product.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\ncoupon_product WHERE\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[	\r\n		$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"prostore_blog_related_prod WHERE related_id = \'\" . (int)$product_id . \"\'\");// prostore add this\r\n			]]></add>\r\n		</operation>\r\n	</file>	\r\n	<file path=\"admin/model/catalog/review.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\ngetLastId()\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[	\r\n		//prostore\r\n		$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"review_extls SET review_id = \'\" . (int)$review_id . \"\', text_plus  = \'\" . $this->db->escape($data[\'text_plus\']) . \"\', text_minus = \'\" . $this->db->escape($data[\'text_minus\']) . \"\', text_admin_answer = \'\" . $this->db->escape($data[\'text_admin_answer\']) . \"\', answer_date_added = NOW() \");\r\n		// prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->db->query(\"UPDATE \" . DB_PREFIX . \"review SET\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[	\r\n		//prostore\r\n		$sql = \"UPDATE \" . DB_PREFIX . \"review_extls SET review_id = \'\" . (int)$review_id . \"\', text_plus  = \'\" . $this->db->escape($data[\'text_plus\']) . \"\',\";\r\n		$sql .= \" text_minus = \'\" . $this->db->escape($data[\'text_minus\']) . \"\', text_admin_answer = \'\" . $this->db->escape($data[\'text_admin_answer\']) . \"\'\";\r\n		if ($data[\'text_admin_answer\']) {\r\n			$sql .= \", answer_date_added = NOW() \";\r\n		}\r\n		$sql .= \"WHERE review_id = \'\" . (int)$review_id . \"\'\";\r\n		$this->db->query($sql);\r\n		// prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"review\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[	\r\n		//prostore\r\n		$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"review_extls WHERE review_id = \'\" . (int)$review_id . \"\'\");\r\n		// prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[AS product FROM \" . DB_PREFIX . \"review r]]></search>\r\n			<add position=\"replace\"><![CDATA[AS product FROM \" . DB_PREFIX . \"review r LEFT JOIN \" . DB_PREFIX . \"review_extls re ON (r.review_id = re.review_id)]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/model/tool/image.php\">\r\n		<operation>\r\n			<search><![CDATA[PATHINFO_EXTENSION]]></search>\r\n			<add position=\"after\"><![CDATA[\r\nif($extension == \'svg\') {\r\n	if ($this->request->server[\'HTTPS\']) {\r\n		return HTTPS_CATALOG . \'image/\' . $filename;\r\n	} else {\r\n		return HTTP_CATALOG . \'image/\' . $filename;\r\n	}\r\n}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/catalog/review_form.twig\">\r\n		<operation>\r\n			<search><![CDATA[\r\n{{ entry_rating }}\r\n			]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[\r\n<!-- prostore -->\r\n          <div class=\"form-group\">\r\n            <label class=\"col-sm-2 control-label\" for=\"input-text\">{{ entry_text_plus }}</label>\r\n            <div class=\"col-sm-10\">\r\n              <textarea name=\"text_plus\" cols=\"60\" rows=\"8\" placeholder=\"{{ entry_text_plus }}\" class=\"form-control\">{{ text_plus }}</textarea>\r\n              {% if error_text %}\r\n              <div class=\"text-danger\">{{ error_text }}</div>\r\n              {% endif %} </div>\r\n          </div>\r\n          <div class=\"form-group\">\r\n            <label class=\"col-sm-2 control-label\" for=\"input-text\">{{ entry_text_minus }}</label>\r\n            <div class=\"col-sm-10\">\r\n              <textarea name=\"text_minus\" cols=\"60\" rows=\"8\" placeholder=\"{{ entry_text_minus }}\"  class=\"form-control\">{{ text_minus }}</textarea>\r\n              {% if error_text %}\r\n              <div class=\"text-danger\">{{ error_text }}</div>\r\n              {% endif %} </div>\r\n          </div>\r\n          <div class=\"form-group\">\r\n            <label class=\"col-sm-2 control-label\" for=\"input-text\">{{ entry_text_admin_answer }}</label>\r\n            <div class=\"col-sm-10\">\r\n              <textarea name=\"text_admin_answer\" cols=\"60\" rows=\"8\" placeholder=\"{{ entry_text_admin_answer }}\"  class=\"form-control\">{{ text_admin_answer }}</textarea>\r\n              {% if error_text %}\r\n              <div class=\"text-danger\">{{ error_text }}</div>\r\n              {% endif %} </div>\r\n          </div>          \r\n<!-- prostore end -->\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/common/filemanager.twig\">\r\n		<operation>\r\n			<search><![CDATA[.attr(\'src\'));]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		{% if \'icons-nav-row\' in thumb  %}\r\n		var imageType = $(this).find(\'img\').attr(\'src\').split(\'.\').pop().toLowerCase();\r\n		if (imageType != \'svg\') {\r\n			alert(\'Only SVG type permited!\');\r\n			return;\r\n		}\r\n		$(\'#{{ thumb|escape(\'js\') }}\').find(\'i\').attr(\'data-original-title\', \'<img src=\'+$(this).find(\'img\').attr(\'src\')+\'>\' );\r\n		{% endif %}\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[.find(\'input\').val());]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n	{% if \'icons-nav-row\' in thumb  %}\r\n		$(\'#{{ thumb|escape(\'js\') }}\').find(\'i\').attr(\'data-original-title\', \'<img src=\'+$(this).find(\'img\').attr(\'src\')+\'>\' );		\r\n	{% endif %}\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"admin/view/template/extension/module/filter.twig\">\r\n		<operation>\r\n			<search><![CDATA[\r\n<form action=\"{{ action }}\" method=\"post\" enctype=\"multipart/form-data\" id=\"form-module\" class=\"form-horizontal\">\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n<!-- prostore -->		\r\n			<div class=\"form-group\">\r\n			  <label class=\"col-sm-2 control-label\"><span data-toggle=\"tooltip\" title=\"\" data-original-title=\"Тип фильтрации по группам фильтров\">Тип фильтрации по группам фильтров</span></label>\r\n			  <div class=\"col-sm-10\">\r\n				<label class=\"radio-inline\"><input type=\"radio\" name=\"module_filter_filter_grouptype\" value=\"0\" {{ module_filter_filter_grouptype == \'0\' ? \'checked\' : \'\' }}> И </label>\r\n				<label class=\"radio-inline\"><input type=\"radio\" name=\"module_filter_filter_grouptype\" value=\"1\" {{ module_filter_filter_grouptype == \'1\' ? \'checked\' : \'\' }}> ИЛИ </label>\r\n			  </div>  \r\n			</div>  \r\n<!-- prostore end -->\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/{address,edit,return,register}.php|catalog/controller/affiliate/register.php|catalog/controller/checkout/checkout.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment/moment.min.js\');\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"3\"><![CDATA[\r\n			// prostore\r\n			if ($this->config->get(\'theme_prostore_bootstrap_ver\')) { // bootstrap5\r\n				$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/moment.min.js\');\r\n				$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/moment-with-locales.min.js\');\r\n				$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/daterangepicker.js\');\r\n				$this->document->addStyle(\'catalog/view/javascript/prostore/datetimepicker/daterangepicker.css\');\r\n			} else { //bootstrap3\r\n				$this->document->addScript(\"catalog/view/javascript/jquery/datetimepicker/moment/moment.min.js\");\r\n				$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment/moment-with-locales.min.js\');\r\n				$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.js\');\r\n				$this->document->addStyle(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.css\');\r\n			}\r\n			$data[\'datepicker\'] = $this->language->get(\'code\');\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$data[\'date_format\'] = $this->language->get(\'text_prostore_date_format\');\r\n			$data[\'datetime_format\'] = $this->language->get(\'text_prostore_datetime_format\');\r\n			$data[\'time_format\'] = $this->language->get(\'text_prostore_time_format\');\r\n			// prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/account.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nlanguage(\'account/account\')\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore	\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'compare\'] = $this->url->link(\'product/compare\');\r\n		$data[\'cart\'] = $this->url->link(\'checkout/cart\');\r\n\r\n		$this->load->model(\'account/order\');\r\n		$this->load->model(\'catalog/product\');\r\n		$this->load->model(\'tool/image\');\r\n		$orders_history = $this->model_account_order->getOrders(0,1);\r\n\r\n		$data[\'last_orders_info\'] = array();\r\n		$data[\'cart_info\'] = array();\r\n\r\n		if ($orders_history) {\r\n			$products_data = array();\r\n			$order_id = $orders_history[0][\'order_id\'];\r\n			$last_orders_info = $this->model_account_order->getOrder($order_id);\r\n			$product_total = $this->model_account_order->getTotalOrderProductsByOrderId($order_id);\r\n			$products = $this->model_account_order->getOrderProducts($order_id);\r\n			foreach ($products as $product) {\r\n				$product_info = $this->model_catalog_product->getProduct($product[\'product_id\']);\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($product[\'product_id\']);\r\n				if (!empty($product_info) && $product_info[\'image\']) {\r\n					$image = $this->model_tool_image->resize($product_info[\'image\'],  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\',  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				}				\r\n\r\n				$products_data[] = array(\r\n					\'product_id\' => $product[\'product_id\'],\r\n					\'name\'     => $product[\'name\'],\r\n					\'model\'    => $product[\'model\'],\r\n					\'thumb\'     => $image,\r\n					\'href\'     => $this->url->link(\'product/product\', \'product_id=\' . $product[\'product_id\']),\r\n					\'wish_compare_data\' => $wishCompareData,\r\n				);\r\n			}\r\n			$total_correct =  $this->prostore->helper->correctForm(array($product_total,\'product\'));\r\n			$data[\'last_orders_info\'] = array(\r\n				\'order_id\'     => $order_id,\r\n				\'text_total\'     => sprintf($this->language->get(\'text_total\'), $product_total, $total_correct , $this->currency->format($last_orders_info[\'total\'], $this->session->data[\'currency\'])),\r\n				\'products_data\'     => $products_data,\r\n				\'href\'     => $this->url->link(\'account/order/info\', \'order_id=\' . $order_id, true)\r\n			);\r\n\r\n		}\r\n\r\n		$cart_total_product = $this->cart->countProducts();\r\n\r\n		if ($cart_total_product) {\r\n			$cart_products = array();\r\n			$cart_total = $this->prostore->helper->get_cart_total();\r\n\r\n			foreach ($this->cart->getProducts() as $product) {\r\n				$product_info = $this->model_catalog_product->getProduct($product[\'product_id\']);\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($product[\'product_id\']);\r\n				if (!empty($product_info) && $product_info[\'image\']) {\r\n					$image = $this->model_tool_image->resize($product_info[\'image\'],  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\',  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				}			\r\n	\r\n				$cart_products[] = array(\r\n					\'product_id\' => $product[\'product_id\'],\r\n					\'name\'     => $product[\'name\'],\r\n					\'model\'    => $product[\'model\'],\r\n					\'thumb\'     => $image,\r\n					\'href\'     => $this->url->link(\'product/product\', \'product_id=\' . $product[\'product_id\']),\r\n					\'wish_compare_data\' => $wishCompareData,\r\n				);			\r\n			}\r\n			$total_correct =  $this->prostore->helper->correctForm(array($cart_total_product,\'product\'));\r\n			$data[\'cart_info\'] = array(\r\n				\'text_total\'     => sprintf($this->language->get(\'text_total\'), $cart_total_product, $total_correct ,$this->currency->format($cart_total, $this->session->data[\'currency\'])),\r\n				\'cart_products\'     => $cart_products\r\n			);\r\n		}\r\n\r\n//		var_dump($data[\'cart_info\'],$data[\'last_orders_info\']);\r\n		\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n\r\n	</file>\r\n	<file path=\"catalog/controller/account/address.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'addresses\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n$data[\'heading_title\'] = $this->language->get(\'heading_title\');// Prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->error[\'firstname\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n		$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n		$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n	\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($this->config->get(\'config_customer_group_id\'),0);\r\n\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} elseif (!empty($address_info)) {\r\n				$data[$field] = $address_info[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n			\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n		$data[\'entry_email_show\'] = 0;\r\n		$data[\'entry_fax_show\'] = 0;\r\n		$data[\'entry_telephone_show\'] = 0;//не должно быть в адресе\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\nreturn !$this->error;\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->error = $this->model_extension_module_prostore->checkLCustomFields($this->error);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->config->get(\'config_customer_group_id\'),0);\r\n		$ignoredFields[] = \'email\';$ignoredFields[] = \'fax\';$ignoredFields[] = \'telephone\'; //Не нужны в адресах\r\n		if(isset($this->error)){\r\n			foreach($this->error as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($this->error[$key]);\r\n				}\r\n			}\r\n			if(!count($this->error)){\r\n				$this->error = false;\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/order.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][]\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				// prostore start\r\n				if (!empty($product_info) && $product_info[\'image\']) {\r\n					$image = $this->model_tool_image->resize($product_info[\'image\'],  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\',  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				}\r\n				// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][]\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n\'thumb\'     => $image,// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'orders\'][]\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore\r\n			$total_correct =  $this->prostore->helper->correctForm(array(($product_total + $voucher_total),\'product\'));\r\n			$this->load->model(\'catalog/product\');\r\n			$this->load->model(\'tool/image\');\r\n			$products_data = array();\r\n			$products = $this->model_account_order->getOrderProducts($result[\'order_id\']);\r\n			foreach ($products as $product) {\r\n				$product_info = $this->model_catalog_product->getProduct($product[\'product_id\']);\r\n				if (!empty($product_info) && $product_info[\'image\']) {\r\n					$image = $this->model_tool_image->resize($product_info[\'image\'],  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\',  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n				}				\r\n\r\n				$products_data[] = array(\r\n					\'name\'     => $product[\'name\'],\r\n					\'model\'    => $product[\'model\'],\r\n					\'href\'     => $this->url->link(\'product/product\', \'product_id=\' . $product[\'product_id\']),\r\n					\'thumb\'    => $image\r\n				);\r\n			}\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'orders\'][]\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'status_style\'  => $this->getOrderStatusStyle($result[\'status\']),//prostore\r\n				\'text_total\'     => sprintf($this->language->get(\'text_total\'), ($product_total + $voucher_total), $total_correct , $this->currency->format($result[\'total\'], $result[\'currency_code\'], $result[\'currency_value\'])),//prostore\r\n				\'products_data\'   => $products_data,//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'shipping_method\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			// prostore start\r\n			if ($this->config->get(\'theme_prostore_checkout_st3_sa\')) {\r\n				$data[\'payment_address\'] = \'\';\r\n			}\r\n			$this->load->model(\'tool/image\');\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			\r\n			$product_total = $this->model_account_order->getTotalOrderProductsByOrderId($this->request->get[\'order_id\']);\r\n			$voucher_total = $this->model_account_order->getTotalOrderVouchersByOrderId($this->request->get[\'order_id\']);\r\n\r\n			$order_total = ($product_total + $voucher_total);\r\n			\r\n			$data[\'product_num\'] = $order_total .\' \'. $this->prostore->helper->correctForm(array($order_total,\'product\'));\r\n\r\n			$this->load->model(\'checkout/order\');\r\n			$order_data = $this->model_checkout_order->getOrder($this->request->get[\'order_id\']);\r\n			$data[\'sum_total\'] = $this->currency->format($order_data[\'total\'], $order_data[\'currency_code\'], $order_data[\'currency_value\']);\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'histories\'][]\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n\'status_style\'  => $this->getOrderStatusStyle($result[\'status\']),// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function reorder\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore start\r\n	public function getOrderStatusStyle($orderStatus){\r\n		$this->load->model(\'account/order\');\r\n		$this->load->model(\'localisation/order_status\');\r\n\r\n		$statusId =  $this->model_account_order->getOrderStatusId($orderStatus);\r\n		$status_styles = array(\r\n			\'processing\' => \'ui-badge--grey\',\r\n			\'completed\' => \'ui-badge--green\'\r\n		);\r\n\r\n		$status_style = \'\';\r\n		if (in_array($statusId,$this->config->get(\'config_complete_status\'))) {\r\n			$status_style = $status_styles[\'completed\']; \r\n		}elseif (in_array($statusId,$this->config->get(\'config_processing_status\'))) {\r\n			$status_style = $status_styles[\'processing\'];\r\n		}\r\n\r\n		return 	$status_style;	\r\n	}\r\n// prostore start\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/edit.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->error[\'warning\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($this->config->get(\'config_customer_group_id\'),1);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n			\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} elseif (!empty($customer_info)) {\r\n				$data[$field] = $customer_info[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n		$data[\'entry_email_required\'] = 1; // В регистрации всегда требовать email\r\n		$data[\'entry_email_show\'] = 1;\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nfunction validate()\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		if ((utf8_strlen(trim($this->request->post[\'address_1\'])) < 3) || (utf8_strlen(trim($this->request->post[\'address_1\'])) > 128)) {\r\n			$this->error[\'address_1\'] = $this->language->get(\'error_address_1\');\r\n		}\r\n		if ((utf8_strlen(trim($this->request->post[\'city\'])) < 2) || (utf8_strlen(trim($this->request->post[\'city\'])) > 128)) {\r\n			$this->error[\'city\'] = $this->language->get(\'error_city\');\r\n		}\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn !$this->error;\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->error = $this->model_extension_module_prostore->checkLCustomFields($this->error);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->config->get(\'config_customer_group_id\'),1);\r\n		if(isset($this->error)){\r\n			foreach($this->error as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)  && $key != \'email\' ){\r\n					unset($this->error[$key]);\r\n				}\r\n			}\r\n			if(!count($this->error)){\r\n				$this->error = false;\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/register.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'account/customer\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		//prostore\r\n		$this->load->model(\'account/address\');\r\n		$data[\'login\'] = $this->url->link(\'account/login\', \'\', true);\r\n		//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$customer_id = $this->model_account_customer-\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		//prostore\r\n			if ($customer_id) {\r\n				$ad_data = $this->request->post;\r\n				$ad_data[\'default\'] = 1;\r\n				$this->model_account_address->addAddress($customer_id, $ad_data);\r\n			}\r\n		//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->error[\'confirm\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		if (isset($this->error[\'city\'])) {\r\n			$data[\'error_city\'] = $this->error[\'city\'];\r\n		} else {\r\n			$data[\'error_city\