getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n			if(!isset($data[\'error_\'.$field[\'name\']])){\r\n				$data[\'error_\'.$field[\'name\']] = \'\' ;\r\n			}			\r\n		}\r\n		$data[\'entry_email_required\'] = 1; // В регистрации всегда требовать email\r\n		$data[\'entry_email_show\'] = 1;\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'custom_fields\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$this->load->model(\'localisation/country\');\r\n\r\n		$data[\'countries\'] = $this->model_localisation_country->getCountries();\r\n\r\n		if (isset($this->request->post[\'country_id\'])) {\r\n			$data[\'country_id\'] = $this->request->post[\'country_id\'];\r\n		} else {\r\n			$data[\'country_id\'] = $this->config->get(\'config_country_id\');\r\n		}		\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\ngetCustomFields($customer_group_id)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		//prostore start\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($customer_group_id);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			// В регистрации всегда требовать email\r\n			if($field[\'name\'] == \'email\'){\r\n				$field[\'required\'] = 1;\r\n				$field[\'is_show\'] = 1;\r\n			}\r\n\r\n			if($field[\'is_show\']){\r\n				$json[] = array(\r\n					\'custom_field_id\' => \'ls-\'.$field[\'custom_field_id\'],\r\n					\'required\'        => (int)$field[\'required\']\r\n				);				\r\n			}			\r\n		}\r\n		//prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn !$this->error;\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		if ((utf8_strlen(trim($this->request->post[\'city\'])) < 2) || (utf8_strlen(trim($this->request->post[\'city\'])) > 128)) {\r\n			$this->error[\'city\'] = $this->language->get(\'error_city\');\r\n		}\r\n		if ($this->request->post[\'country_id\'] == \'\') {\r\n			$this->error[\'country\'] = $this->language->get(\'error_country\');\r\n		}\r\n		if ($this->request->post[\'address_1\'] == \'\') {\r\n			$this->error[\'address_1\'] = $this->language->get(\'error_address_1\');\r\n		}\r\n		if ($this->request->post[\'postcode\'] == \'\') {\r\n			$this->error[\'postcode\'] = $this->language->get(\'error_postcode\');\r\n		}\r\n		if ($this->request->post[\'zone_id\'] == \'0\') {\r\n			$this->error[\'zone\'] = $this->language->get(\'error_zone\');\r\n		}	\r\n		\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->error = $this->model_extension_module_prostore->checkLCustomFields($this->error);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($customer_group_id);	\r\n		if(isset($this->error)){\r\n			foreach($this->error as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields) && $key != \'email\'){// В регистрации всегда проверять email\r\n					unset($this->error[$key]);\r\n				}\r\n			}\r\n			if(!count($this->error)){\r\n				$this->error = false;\r\n			}\r\n		}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/voucher.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function index()\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		$this->load->language(\'extension/theme/prostore\');// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->error[\'warning\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		if ($this->config->get(\'theme_prostore_voucher_pdata\')) {\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$this->load->model(\'catalog/information\');\r\n\r\n			$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_voucher_pdata\'));\r\n\r\n			if ($information_info) {\r\n				$data[\'text_prostore_pdata_checkbox\'] = sprintf($this->language->get(\'text_prostore_pdata_checkbox\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_voucher_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n			} else {\r\n				$data[\'text_prostore_pdata_checkbox\'] = \'\';\r\n			}\r\n		} else {\r\n			$data[\'text_prostore_pdata_checkbox\'] = \'\';\r\n		}\r\n\r\n		if (isset($this->error[\'error_pdata\