ta[\'products\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$data[\'islogged\'] = $this->customer->isLogged();//prostore\r\n		$data[\'button_compare\'] = $this->language->get(\'button_compare\');//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[getWishlist]]></search>\r\n			<add position=\"replace\"><![CDATA[getWishlistLb]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$image = false;\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_wishlist_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_wishlist_height\'));\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n			if ($this->customer->isLogged()) {\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			if ($this->customer->isLogged() || $this->config->get(\'theme_prostore_wishlist\')) {\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[addWishlist]]></search>\r\n			<add position=\"replace\"><![CDATA[addWishlistLb]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[getTotalWishlist]]></search>\r\n			<add position=\"replace\"><![CDATA[getTotalWishlistLb]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif (!isset($this->session->data[\'wishlist\'])) {\r\n		]]></search>\r\n		<add position=\"replace\" offset=\"7\"><![CDATA[\r\n				$json[\'button_text\'] = \'\';\r\n				$json[\'error\'] = \'1\';\r\n		]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\ngetTotalWishlistLb\r\n		]]></search>\r\n		<add position=\"before\"><![CDATA[\r\n				$totalForThisProduct =  $this->model_account_wishlist->getTotalWishlistByProduct($product_id);\r\n				$json[\'button_text\'] = sprintf($this->language->get(\'text_prostore_in_wishlist2\') , $this->prostore->helper->wishlist_text($totalForThisProduct) );\r\n		]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function add()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n	public function remove() {\r\n		$this->load->language(\'account/wishlist\');\r\n		$this->load->language(\'extension/theme/prostore\'); // prostore\r\n            \r\n		$json = array();\r\n\r\n		if (isset($this->request->post[\'product_id\'])) {\r\n			$product_id = $this->request->post[\'product_id\'];\r\n		} else {\r\n			$product_id = 0;\r\n		}\r\n\r\n		$this->load->model(\'catalog/product\');\r\n		$product_info = $this->model_catalog_product->getProduct($product_id);\r\n\r\n		if ($product_info) {\r\n			if ($this->customer->isLogged() || $this->config->get(\'theme_prostore_wishlist\')) {\r\n            \r\n				// Edit customers cart\r\n				$this->load->model(\'account/wishlist\');\r\n				$total = $this->model_account_wishlist->deleteWishlistLb($product_id);\r\n				$totalForThisProduct =  $this->model_account_wishlist->getTotalWishlistByProduct($product_id);\r\n				$json[\'success\'] = sprintf($this->language->get(\'text_prostore_success_remove_wish\'), $this->url->link(\'product/product\', \'product_id=\' . (int)$this->request->post[\'product_id\']), $product_info[\'name\'], $this->url->link(\'account/wishlist\'));\r\n				$json[\'total\'] = sprintf($this->language->get(\'text_wishlist\'), $total);\r\n				$json[\'button_text\'] = sprintf($this->language->get(\'text_prostore_to_wishlist2\') , $this->prostore->helper->wishlist_text($totalForThisProduct) );\r\n\r\n			} else {\r\n				$json[\'error\'] = \'1\';\r\n				$json[\'success\'] = sprintf($this->language->get(\'text_login\'), $this->url->link(\'account/login\', \'\', true), $this->url->link(\'account/register\', \'\', true), $this->url->link(\'product/product\', \'product_id=\' . (int)$this->request->post[\'product_id\']), $product_info[\'name\'], $this->url->link(\'account/wishlist\'));\r\n				$json[\'total\'] = sprintf($this->language->get(\'text_wishlist\'), (isset($this->session->data[\'wishlist\']) ? count($this->session->data[\'wishlist\']) : 0));\r\n			}\r\n		}\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n		]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/affiliate/register.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->customer->login($this->request->post[\'email\'], $this->request->post[\'password\']);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$customer_id = $this->model_account_customer\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$this->customer->login($this->request->post[\'email\'], $this->request->post[\'password\']);//prostore add this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'text_account_already\'] = sprintf\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$data[\'heading_title\'] = $this->language->get(\'heading_title\');\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n		if (isset($this->request->post[\'firstname\'])) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'login\'] = $this->url->link(\'affiliate/login\', \'\', true);\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n		$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n		$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n	\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($this->config->get(\'config_customer_group_id\'),0);\r\n\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n			\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n		$data[\'entry_email_show\'] = 0;\r\n		$data[\'entry_fax_show\'] = 0;\r\n		$data[\'entry_telephone_show\'] = 0;//не должно быть в адресе\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif (isset($this->request->post[\'company\']))\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//Prostore start\r\n		if (isset($this->request->post[\'city\'])) {\r\n			$data[\'city\'] = $this->request->post[\'city\'];\r\n		} else {\r\n			$data[\'city\'] = \'\';\r\n		}\r\n\r\n		if (isset($this->request->post[\'country_id\'])) {\r\n			$data[\'country_id\'] = (int)$this->request->post[\'country_id\'];\r\n		} else {\r\n			$data[\'country_id\'] = $this->config->get(\'config_country_id\');\r\n		}\r\n\r\n		$this->load->model(\'localisation/country\');\r\n\r\n		$data[\'countries\'] = $this->model_localisation_country->getCountries();\r\n//Prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n		return !$this->error;\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->error = $this->model_extension_module_prostore->checkLCustomFields($this->error);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->config->get(\'config_customer_group_id\'),0);\r\n		$ignoredFields[] = \'email\';$ignoredFields[] = \'fax\';$ignoredFields[] = \'telephone\'; //Не нужны в адресах\r\n		if(isset($this->error)){\r\n			foreach($this->error as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($this->error[$key]);\r\n				}\r\n			}\r\n\r\n			if(!count($this->error)){\r\n				$this->error = false;\r\n			}\r\n		}\r\n		\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/api/customer.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'account/custom_field\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		if(!isset($json[\'error\'])){\r\n			$json[\'error\'] = array();\r\n		}\r\n		$json[\'error\'] = $this->model_extension_module_prostore->checkLCustomFields($json[\'error\']);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($customer_group_id);\r\n\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/api/{payment,shipping}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'account/custom_field\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->config->get(\'config_customer_group_id\'));\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/cart.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->cart->hasProducts()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n			if ($this->config->get($this->config->get(\'theme_prostore_config_captcha_fo\') . \'_status\')) {\r\n				$data[\'captcha_fo\'] = $this->load->controller(\'extension/captcha/\' . $this->config->get(\'theme_prostore_config_captcha_fo\'));\r\n			} else {\r\n			$data[\'captcha_fo\'] = \'\';\r\n			}\r\n		$this->load->language(\'extension/theme/prostore\'); \r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n			$data[\'button_fastorder_sendorder\'] = $this->language->get(\'button_prostore_sendorder\');\r\n			$data[\'text_prostore_fast_order\'] = $this->language->get(\'text_prostore_fast_order\');\r\n			$data[\'text_fastorder_name\'] = $this->language->get(\'text_prostore_name\');\r\n			$data[\'text_fastorder_phone\'] = $this->language->get(\'text_prostore_phone\');\r\n			$data[\'text_fastorder_comment\'] = $this->language->get(\'text_prostore_comment\');\r\n			if ($this->config->get(\'theme_prostore_buy_click_pdata\')) {\r\n				$this->load->language(\'extension/theme/prostore\');\r\n				$this->load->model(\'catalog/information\');\r\n\r\n				$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_buy_click_pdata\'));\r\n\r\n				if ($information_info) {\r\n					$data[\'text_prostore_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_prostore_sendorder\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_buy_click_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n				} else {\r\n					$data[\'text_prostore_pdata\'] = \'\';\r\n				}\r\n			} else {\r\n				$data[\'text_prostore_pdata\'] = \'\';\r\n			}\r\n			\r\n			$data[\'buy_click\'] = array();\r\n			if($this->config->get(\'theme_prostore_buy_click\')){\r\n				$data[\'buy_click\'] = $this->config->get(\'theme_prostore_buy_click\');\r\n				if ($this->customer->isLogged()) {\r\n					$this->load->model(\'account/customer\');\r\n					$data[\'customer_info\'] = $this->model_account_customer->getCustomer($this->customer->getId());\r\n				}\r\n			}\r\n			$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n\r\n			$this->load->language(\'checkout/checkout\');\r\n			$data[\'entry_firstname\'] = $this->language->get(\'entry_firstname\');\r\n			$data[\'entry_lastname\'] = $this->language->get(\'entry_lastname\');\r\n			$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n			$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n			$data[\'entry_comment\'] = $this->language->get(\'entry_comment\');\r\n			$data[\'text_prostore_cart_price\'] = $this->language->get(\'text_prostore_cart_price\');\r\n			$data[\'text_prostore_reward\'] = $this->language->get(\'text_prostore_reward\');\r\n			$data[\'prostore_cart_total\'] = $this->currency->format($this->cart->getTotal(), $this->session->data[\'currency\']);\r\n			$data[\'prostore_cart_count\'] = $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0);\r\n			\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->config->get(\'config_customer_price\') &&\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore start\r\n			if ($this->getTotals() < (int)$this->config->get(\'theme_prostore_checkout_min_order\')) {\r\n				$data[\'error_warning\'] = sprintf($this->language->get(\'error_min_order\'),$this->currency->format($this->config->get(\'theme_prostore_checkout_min_order\'), $this->session->data[\'currency\']));\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nview(\'checkout/cart\', $data)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			$data[\'buyclick_form\'] = $this->load->view(\'product/buyclick_form\', $data);//Prostore added this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$product[\'model\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					\'minimum\'   => $product[\'minimum\'],// prostore add\r\n					\'reward_num\'=> $product[\'reward\'],// prostore add\r\n					\'product_id\'=> $product[\'product_id\'],// prostore add\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n[\'totals\'][]\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n\'value\' => $total[\'value\'],//Prostore added this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->request->post[\'product_id\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\'); \r\n		if (isset($this->request->post[\'prod_id_quantity\']) && !isset($this->request->post[\'quantity\'])) {\r\n			$this->request->post[\'quantity\'] = current($this->request->post[\'prod_id_quantity\']);\r\n		}\r\n		// prostore	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[text_items]]></search>\r\n			<add position=\"replace\"><![CDATA[text_prostore_shopping_cart]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n!empty($this->request->post[\'quantity\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n		$this->load->language(\'extension/theme/prostore\'); \r\n		if (isset($this->request->post[\'prod_id_quantity\'])) {\r\n			$json[\'deleted_items\'] = $this->convert2cartId();\r\n		}\r\n		$cartProducts = $this->prostore->helper->getCartIdsAsKey();\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n!empty($this->request->post[\'quantity\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$deletedItems = [];// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nforeach ($this->request->post[\'quantity\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n				if ($value < $cartProducts[$key][\'minimum\']) {\r\n					$value = 0;\r\n					$deletedItems[] = $cartProducts[$key][\'product_id\'];\r\n				}\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->session->data[\'success\'] = $this->language->get(\'text_remove\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			if ($deletedItems) {\r\n				$json[\'deleted_items\'] = $deletedItems;\r\n			}\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function remove()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n	public function getTotals(){\r\n/**\r\n * Get cart totals include vouchers\r\n */\r\n		$this->load->model(\'setting/extension\');\r\n\r\n		$totals = array();\r\n		$taxes = $this->cart->getTaxes();\r\n		$total = 0;\r\n\r\n		// Because __call can not keep var references so we put them into an array. 			\r\n		$total_data = array(\r\n			\'totals\' => &$totals,\r\n			\'taxes\'  => &$taxes,\r\n			\'total\'  => &$total\r\n		);\r\n\r\n		// Display prices\r\n		if ($this->customer->isLogged() || !$this->config->get(\'config_customer_price\')) {\r\n			$sort_order = array();\r\n\r\n			$results = $this->model_setting_extension->getExtensions(\'total\');\r\n\r\n			foreach ($results as $key => $value) {\r\n				$sort_order[$key] = $this->config->get(\'total_\' . $value[\'code\'] . \'_sort_order\');\r\n			}\r\n\r\n			array_multisort($sort_order, SORT_ASC, $results);\r\n\r\n			foreach ($results as $result) {\r\n				if ($this->config->get(\'total_\' . $result[\'code\'] . \'_status\')) {\r\n					$this->load->model(\'extension/total/\' . $result[\'code\']);\r\n\r\n					// We have to put the totals in an array so that they pass by reference.\r\n					$this->{\'model_extension_total_\' . $result[\'code\']}->getTotal($total_data);\r\n				}\r\n			}\r\n\r\n			$sort_order = array();\r\n\r\n			foreach ($totals as $key => $value) {\r\n				$sort_order[$key] = $value[\'sort_order\'];\r\n			}\r\n\r\n			array_multisort($sort_order, SORT_ASC, $totals);\r\n		}\r\n\r\n		return $total;\r\n	}\r\n\r\n\r\n	public function getProductsIdAsKey(){\r\n		$cartProducts = array();\r\n		foreach ($this->cart->getProducts() as $product) {\r\n			$cartProducts[$product[\'product_id\']] = $product;\r\n		}\r\n		return $cartProducts;\r\n	}\r\n/**\r\n * Преобразование product_id в cart_id если такой продукт есть в корзине.\r\n * Используется для апдейта количества товаров на странице категорий.\r\n */\r\n	public function convert2cartId() {\r\n		$deletedItems = array();\r\n		if (empty($this->request->post[\'prod_id_quantity\'])) {\r\n			return $deletedItems;\r\n		}\r\n		$cartProducts = $this->getProductsIdAsKey();\r\n		foreach ($this->request->post[\'prod_id_quantity\'] as $product_id => $quantity) {\r\n			if (array_key_exists($product_id,$cartProducts)) {\r\n				if ($quantity < $cartProducts[$product_id][\'minimum\']) {\r\n					$quantity = 0;\r\n					$deletedItems[] = $product_id;\r\n				}\r\n				$cart_id = $cartProducts[$product_id][\'cart_id\'];\r\n				$this->request->post[\'quantity\'][$cart_id] = $quantity;\r\n			}\r\n		}\r\n		unset($this->request->post[\'prod_id_quantity\']);\r\n		return $deletedItems;\r\n	}\r\n\r\n	public function clear() {\r\n		$this->load->language(\'checkout/cart\');\r\n		$this->load->language(\'extension/theme/prostore\'); \r\n\r\n		$json = array();\r\n		$cart_products = $this->prostore->helper->getProductsIdAsKey();\r\n		if (!empty($cart_products)) {\r\n			$json[\'deleted_items\'] = array_keys($cart_products);\r\n		}\r\n		$json[\'total\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\'), 0, $this->currency->format(0, $this->session->data[\'currency\']));\r\n		$this->cart->clear();\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n\r\n	public function setadd() {\r\n		$json = array();\r\n		$this->load->language(\'checkout/cart\');\r\n		$this->load->language(\'extension/theme/prostore\'); \r\n\r\n		if (isset($this->request->post[\'setproducts\'])) {\r\n			$product_ids = $this->request->post[\'setproducts\'];\r\n		} else {\r\n			$product_ids = array();\r\n		}	\r\n\r\n		if (isset($this->request->post[\'setid\'])) {\r\n			$setid = $this->request->post[\'setid\'];\r\n		} else {\r\n			$setid = 0;\r\n		}	\r\n\r\n		$this->session->data[\'prostoresetid\'][] = $setid;\r\n\r\n		$option = array();\r\n\r\n\r\n		foreach ($product_ids as $product_id => $quantity) {\r\n			$this->cart->add($product_id, $quantity, $option);\r\n		}\r\n\r\n		$total = $this->getTotals();\r\n\r\n		$json[\'total\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\'), $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0), $this->currency->format($total, $this->session->data[\'currency\']));\r\n		$json[\'success\'] = $this->language->get(\'text_set_success\');\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n	// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->response->redirect($this->url->link(\'checkout/cart\'));\r\n			]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[\r\n// prostore\r\n$total = $this->getTotals();\r\n$json[\'total\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\'), $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0), $this->currency->format($total, $this->session->data[\'currency\']));\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->response->redirect($this->url->link(\'checkout/cart\'));\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->request->post[\'key\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$this->load->language(\'extension/theme/prostore\'); // prostore\r\n		$cart_products = $this->prostore->helper->getCartIdsAsKey(); // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"4\"><![CDATA[\r\n$json[\'total\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\')\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			// prostore\r\n			if (isset($cart_products[$this->request->post[\'key\']])) {\r\n				$json[\'deleted_items\'] = array((int)$cart_products[$this->request->post[\'key\']][\'product_id\']);\r\n			}\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/checkout.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->cart->getProducts\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore start\r\n		if ($this->load->controller(\'checkout/cart/getTotals\') < (int)$this->config->get(\'theme_prostore_checkout_min_order\')) {\r\n			$this->response->redirect($this->url->link(\'checkout/cart\'));\r\n		}\r\n// prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->cart->hasShipping()) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'text_prostore_checkout_s1\'] = $this->language->get(\'text_prostore_checkout_s1\');\r\n		$data[\'text_prostore_checkout_s2\'] = $this->language->get(\'text_prostore_checkout_s2\');\r\n		$data[\'text_prostore_checkout_s3\'] = $this->language->get(\'text_prostore_checkout_s3\');\r\n		$data[\'text_prostore_checkout_s4\'] = $this->language->get(\'text_prostore_checkout_s4\');\r\n\r\n		$data[\'checkout_st3_sa\'] = $this->config->get(\'theme_prostore_checkout_st3_sa\');\r\n\r\n		$this->load->model(\'catalog/information\');\r\n		$information_info = $this->model_catalog_information->getInformation($this->config->get(\'config_checkout_id\'));\r\n		if ($information_info) {\r\n			$data[\'error_agree\'] = sprintf($this->language->get(\'error_agree\'), $information_info[\'title\']);\r\n		} else {\r\n			$data[\'error_agree\'] = \'\';\r\n		}\r\n		\r\n		$data[\'show_checkout_shipping\'] = $this->config->get(\'theme_prostore_checkout_shipping\');\r\n		$data[\'fixed_cart\'] = $this->config->get(\'theme_prostore_checkout_fixed_cart\');\r\n		$data[\'fixed_header\'] = $this->config->get(\'theme_prostore_fixed_header\');\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$custom_fields =\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		//prostore start\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($customer_group_id);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			// В регистрации всегда требовать email\r\n			if($field[\'name\'] == \'email\'){\r\n				$field[\'required\'] = 1;\r\n				$field[\'is_show\'] = 1;\r\n			}\r\n\r\n			if($field[\'is_show\']){\r\n				$json[] = array(\r\n					\'custom_field_id\' => \'ls-\'.$field[\'custom_field_id\'],\r\n					\'required\'        => (int)$field[\'required\']\r\n				);				\r\n			}			\r\n		}\r\n		//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/confirm.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n(!$redirect)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->model(\'catalog/information\');\r\n		$this->load->language(\'checkout/checkout\');\r\n		$information_info = $this->model_catalog_information->getInformation($this->config->get(\'config_checkout_id\'));\r\n		$data[\'error_agree\'] = \'\';\r\n		if ($information_info) {\r\n			$data[\'error_agree\'] = sprintf($this->language->get(\'error_agree\'), $information_info[\'title\']);\r\n		}\r\n		// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->session->data[\'order_id\'] = $this->model_checkout_order->addOrder($order_data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n//Prostore\r\n			if (isset($this->session->data[\'order_id\']) && $this->model_checkout_order->getOrder($this->session->data[\'order_id\'])) {\r\n				$this->model_checkout_order->editOrder($this->session->data[\'order_id\'],$order_data);\r\n			}else{\r\n				$this->session->data[\'order_id\'] = $this->model_checkout_order->addOrder($order_data);\r\n				$this->session->data[\'ls_order_id\'] = $this->session->data[\'order_id\'];\r\n			}\r\n//Prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/guest.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nif (isset($this->session->data[\'guest\'][\'customer_group_id\'])) {\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n		if (isset($this->request->post[\'customer_group_id\'])) {\r\n			$data[\'customer_group_id\'] = $this->request->post[\'customer_group_id\'];\r\n		} elseif(isset($this->session->data[\'guest\'][\'customer_group_id\'])) {\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n[\'guest\'][\'firstname\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'datepicker\'] = $this->language->get(\'code\');// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'date_format\'] = $this->language->get(\'text_prostore_date_format\');// prostore\r\n		$data[\'datetime_format\'] = $this->language->get(\'text_prostore_datetime_format\');// prostore\r\n		$data[\'time_format\'] = $this->language->get(\'text_prostore_time_format\');// prostore\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n		$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n		$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n		$data[\'checkout_st3_sa\'] = $this->config->get(\'theme_prostore_checkout_st3_sa\');\r\n\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($data[\'customer_group_id\']);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n		\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->customer->isLogged()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$customer_group_id = $this->config->get(\'config_customer_group_id\');\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$customer_group_id = $this->request->post[\'customer_group_id\'];\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"2\"><![CDATA[\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif (isset($this->request->post[\'customer_group_id\']) && is_array\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$customer_group_id = $this->request->post[\'customer_group_id\'];\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->session->data[\'account\'] = \'guest\';\r\n			]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		if(!isset($json[\'error\'])){\r\n			$json[\'error\'] = array();\r\n		}\r\n		$json[\'error\'] = $this->model_extension_module_prostore->checkLCustomFields($json[\'error\']);\r\n		$ignoredFields = array();\r\n		if($this->model_extension_module_prostore->getIgnoredFields($customer_group_id)){\r\n			$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($customer_group_id);\r\n		}\r\n\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n//prostore end		\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'city\'] = $this\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n//prostore start				\r\n		} elseif (isset($this->session->data[\'shipping_address\'][\'city\'])) {\r\n			$data[\'city\'] = $this->session->data[\'shipping_address\'][\'city\'];\r\n//prostore end		\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/guest_shipping.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'countries\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n		$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n		$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n		$data[\'entry_fax\'] = $this->language->get(\'entry_fax\');\r\n		\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($this->session->data[\'guest\'][\'customer_group_id\']);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->session->data[\'shipping_address\'][$field])) {\r\n				$data[$field] = $this->session->data[\'shipping_address\'][$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif ((utf8_strlen(trim($this->request->post[\'address_1\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			if ((utf8_strlen(trim($this->request->post[\'telephone\'])) < 1) || (utf8_strlen(trim($this->request->post[\'telephone\'])) > 32)) {\r\n				$json[\'error\'][\'telephone\'] = $this->language->get(\'error_telephone\');\r\n			}	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->request->post[\'firstname\'];\r\n			]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		if(!isset($json[\'error\'])){\r\n			$json[\'error\'] = array();\r\n		}\r\n		$json[\'error\'] = $this->model_extension_module_prostore->checkLCustomFields($json[\'error\']);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->session->data[\'guest\'][\'customer_group_id\']);\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/login.php\">\r\n		<operation>\r\n			<search><![CDATA[\'register\']]></search>\r\n			<add position=\"replace\"><![CDATA[$this->config->get(\'theme_prostore_checkout_account\')]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'forgotten\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n//prostore start\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'text_account_check\'] = $this->language->get(\'text_accoun