$data[\'code\'] = \'\';\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n// prostore\r\n$data[\'code\'] = $this->setDefaultMethod($data[\'shipping_methods\']);\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function save(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n	/**\r\n	 * Set the default shipping method\r\n	 * @return String The default shipping method code\r\n	 */\r\n	protected function setDefaultMethod($shipping_methods) : String {\r\n		if (empty($shipping_methods)) {\r\n			return \'\';\r\n		}\r\n		$default_method = current($shipping_methods)[\'quote\'];\r\n		$default_method = current($default_method);\r\n		$this->session->data[\'shipping_method\'] = $default_method;\r\n		return $default_method[\'code\'];		\r\n	}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/register.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n(isset($this->session->data[\'shipping_address\'][\'zone_id\']))\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'datepicker\'] = $this->language->get(\'code\');// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'date_format\'] = $this->language->get(\'text_prostore_date_format\');// prostore\r\n		$data[\'datetime_format\'] = $this->language->get(\'text_prostore_datetime_format\');// prostore\r\n		$data[\'time_format\'] = $this->language->get(\'text_prostore_time_format\');// prostore\r\n\r\n		if (isset($this->request->post[\'customer_group_id\'])) {\r\n			$data[\'customer_group_id\'] = $this->request->post[\'customer_group_id\'];\r\n		} else {\r\n			$data[\'customer_group_id\'] = $this->config->get(\'config_customer_group_id\');\r\n		}\r\n		\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($data[\'customer_group_id\']);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n		$data[\'checkout_st3_sa\'] = $this->config->get(\'theme_prostore_checkout_st3_sa\');\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n			\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n		$data[\'entry_email_required\'] = 1; // В регистрации всегда требовать email\r\n		$data[\'entry_email_show\'] = 1;\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$customer_id = $this->model_account_customer->addCustomer($this->request->post);\r\n			]]></search>\r\n			<add position=\"before\" offset=\"2\"><![CDATA[\r\n//prostore start				\r\n		$this->load->model(\'extension/module/prostore\');\r\n		if(!isset($json[\'error\'])){\r\n			$json[\'error\'] = array();\r\n		}\r\n		$json[\'error\'] = $this->model_extension_module_prostore->checkLCustomFields($json[\'error\']);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($customer_group_id);\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)  && $key != \'email\' ){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/shipping_address.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'account/address\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n		$data[\'datepicker\'] = $this->language->get(\'code\');// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'date_format\'] = $this->language->get(\'text_prostore_date_format\');// prostore\r\n		$data[\'datetime_format\'] = $this->language->get(\'text_prostore_datetime_format\');// prostore\r\n		$data[\'time_format\'] = $this->language->get(\'text_prostore_time_format\');// prostore\r\n		$data[\'button_back\'] = $this->language->get(\'button_back\');\r\n		$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n		$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n		$data[\'checkout_st3_sa\'] = $this->config->get(\'theme_prostore_checkout_st3_sa\');\r\n		$data[\'entry_fax\'] = $this->language->get(\'entry_fax\');\r\n\r\n		if (isset($this->request->post[\'customer_group_id\'])) {\r\n			$customer_group_id = $this->request->post[\'customer_group_id\'];\r\n		} elseif(isset($this->session->data[\'guest\'][\'customer_group_id\'])) {\r\n			$customer_group_id  = $this->session->data[\'guest\'][\'customer_group_id\'];\r\n		} else {\r\n			$customer_group_id  = $this->config->get(\'config_customer_group_id\');\r\n		}\r\n		\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$activeFields = $this->model_extension_module_prostore->getFields($customer_group_id,0);\r\n		$allFields = $this->model_extension_module_prostore->getAllFields();\r\n\r\n		$data[\'allCustomFields\'] = $allFields;\r\n		foreach($allFields as $field){\r\n			$data[\'entry_\'.$field.\'_required\'] = 0;\r\n			$data[\'entry_\'.$field.\'_show\'] = 0;\r\n\r\n			if (isset($this->request->post[$field])) {\r\n				$data[$field] = $this->request->post[$field];\r\n			} else {\r\n				$data[$field] = \'\';\r\n			}\r\n\r\n			if (isset($this->error[$field])) {\r\n				$data[\'error_\'.$field] = $this->error[$field];\r\n			} else {\r\n				$data[\'error_\'.$field] = \'\';\r\n			}\r\n\r\n		}\r\n\r\n		foreach($activeFields as $field){\r\n			if($field[\'description\']){\r\n				$data[\'entry_\'.$field[\'name\']] = $field[\'description\'];\r\n			}\r\n			$data[\'entry_\'.$field[\'name\'].\'_id\'] = \'ls-\'.$field[\'custom_field_id\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_required\'] = $field[\'required\'];\r\n			$data[\'entry_\'.$field[\'name\'].\'_show\'] = $field[\'is_show\'];\r\n		}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nmodel_localisation_country->getCountry\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				if ((utf8_strlen(trim($this->request->post[\'telephone\'])) < 2) || (utf8_strlen(trim($this->request->post[\'telephone\'])) > 128)) {\r\n					$json[\'error\'][\'telephone\'] = $this->language->get(\'error_telephone\');\r\n				}\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"2\"><![CDATA[\r\nif (!$json)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start	\r\n	if(isset($json[\'error\'])){			\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$json[\'error\'] = $this->model_extension_module_prostore->checkLCustomFields($json[\'error\']);\r\n		$ignoredFields = $this->model_extension_module_prostore->getIgnoredFields($this->config->get(\'config_customer_group_id\'));\r\n		if(isset($json[\'error\'])){\r\n			foreach($json[\'error\'] as $key => $fieldsdata){\r\n				if(in_array($key,$ignoredFields)){\r\n					unset($json[\'error\'][$key]);\r\n				}\r\n			}\r\n			if(!count($json[\'error\'])){\r\n				unset($json[\'error\']);\r\n			}\r\n		}\r\n	}\r\n//prostore end	\r\n			]]></add>\r\n		</operation>		\r\n	</file>\r\n	<file path=\"catalog/controller/checkout/success.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->language(\'checkout/success\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		$data[\'order_id\'] = 0;// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->cart->clear();\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$data[\'order_id\'] = $this->session->data[\'order_id\'];// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n			unset($this->session->data[\'totals\']);\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			unset($this->session->data[\'prostoresetid\']);// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->customer->isLogged()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'text_prostore_con_soc2\'] = $this->language->get(\'text_prostore_con_soc\');\r\n		\r\n		$this->load->model(\'setting/setting\');\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$data[\'social_navs\'] = array();\r\n		$social_links = $this->model_setting_setting->getSetting(\'theme_prostoresoclinks\');\r\n		$data[\'social_links\'] = $social_links[\'theme_prostoresoclinks_array\'];\r\n		$data[\'social_navs\'] = $this->config->get(\'theme_prostore_social_nav\');	\r\n		$data[\'soc_stat\'] = $this->config->get(\'theme_prostore_success_soc_stat\');	\r\n		\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_logo_success\'))) {\r\n			$data[\'logo_success\'] = (isset($this->request->server[\'HTTPS\']) ? HTTPS_SERVER : HTTP_SERVER) . \'image/\' . $this->config->get(\'theme_prostore_logo_success\');\r\n		} else {\r\n			$data[\'logo_success\'] = \'\';\r\n		}\r\n	    // prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/cart.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'tool/image\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore	\r\n		if ($this->config->get(\'theme_prostore_config_captcha_fo\')) {\r\n\r\n			$data[\'captcha_fo\'] = $this->load->controller(\'extension/captcha/\' . $this->config->get(\'theme_prostore_config_captcha_fo\'));\r\n		} else {\r\n			$data[\'captcha_fo\'] = \'\';\r\n		}\r\n\r\n		$this->load->language(\'extension/theme/prostore\');	\r\n		$data[\'text_items\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\'), $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0), $this->currency->format($total, $this->session->data[\'currency\']));\r\n		$data[\'button_fastorder_sendorder\'] = $this->language->get(\'button_prostore_sendorder\');\r\n		$data[\'text_prostore_cart_title\'] = $this->language->get(\'text_prostore_cart_title\');\r\n		$data[\'text_prostore_cart_quantity\'] = $this->language->get(\'text_prostore_cart_quantity\');\r\n		$data[\'text_prostore_fast_order\'] = $this->language->get(\'text_prostore_fast_order\');\r\n		$data[\'text_prostore_edit_cart\'] = $this->language->get(\'text_prostore_edit_cart\');\r\n		$data[\'text_prostore_clear\'] = $this->language->get(\'text_prostore_clear\');\r\n			if ($this->config->get(\'theme_prostore_buy_click_pdata\')) {\r\n				$this->load->language(\'extension/theme/prostore\');\r\n				$this->load->model(\'catalog/information\');\r\n\r\n				$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_buy_click_pdata\'));\r\n\r\n				if ($information_info) {\r\n					$data[\'text_prostore_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_prostore_sendorder\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_buy_click_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n				} else {\r\n					$data[\'text_prostore_pdata\'] = \'\';\r\n				}\r\n			} else {\r\n				$data[\'text_prostore_pdata\'] = \'\';\r\n			}\r\n\r\n		$data[\'buy_click\'] = array();\r\n		if($this->config->get(\'theme_prostore_buy_click\')){\r\n			$data[\'buy_click\'] = $this->config->get(\'theme_prostore_buy_click\');\r\n				if ($this->customer->isLogged()) {\r\n					$this->load->model(\'account/customer\');\r\n					$data[\'customer_info\'] = $this->model_account_customer->getCustomer($this->customer->getId());\r\n				}\r\n		}\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n		$data[\'cart_call\'] = $this->config->get(\'theme_prostore_cart_call\');\r\n			$this->load->language(\'checkout/checkout\');\r\n			$data[\'entry_firstname\'] = $this->language->get(\'entry_firstname\');\r\n			$data[\'entry_lastname\'] = $this->language->get(\'entry_lastname\');\r\n			$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n			$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n			$data[\'entry_comment\'] = $this->language->get(\'entry_comment\');\r\n			\r\n			if ($this->cart->hasProducts() && ($this->cart->getTotal() < (int)$this->config->get(\'theme_prostore_checkout_min_order\'))) {\r\n				$data[\'error_min_warning\'] = sprintf($this->language->get(\'error_min_order\'),$this->currency->format($this->config->get(\'theme_prostore_checkout_min_order\'), $this->session->data[\'currency\']));\r\n			}\r\n\r\n		$cart_total_product = $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0);\r\n		if ($cart_total_product) {\r\n			$data[\'product_num\'] = $cart_total_product .\' \'. $this->prostore->helper->correctForm(array($cart_total_product,\'product\'));\r\n		} else {\r\n			$data[\'product_num\'] = false;\r\n		}\r\n		$data[\'product_sub_total\'] = $this->currency->format($this->cart->getTotal(), $this->session->data[\'currency\']);\r\n		$data[\'product_total\'] = $this->currency->format($total, $this->session->data[\'currency\']);\r\n		$data[\'cart_total_product\'] = $cart_total_product;\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$image = \'\';\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n				$image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_cart_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_cart_height\')); // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $product[\'quantity\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'minimum\'   => $product[\'minimum\'], //prostore add\r\n				\'product_id\'   => $product[\'product_id\'], //prostore add\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'title\' => $total[\'title\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'code\' => $total[\'code\'], //Prostore added this\r\n				\'value\' => $total[\'value\'],//Prostore added this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'common/cart\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n//prostore	\r\n		$data[\'buyclick_form\'] = $this->load->view(\'product/buyclick_form\', $data);	\r\n		$data[\'text_custcart\'] = $this->language->get(\'text_custcart\');  	\r\n		$data[\'text_prostore_cart_quantity\'] = $this->language->get(\'text_prostore_cart_quantity\');  	\r\n		if(isset($this->request->get[\'custcart\'])){\r\n			$this->response->setOutput($this->load->view(\'common/custcart\', $data));\r\n		}else{\r\n			return $this->load->view(\'common/cart\', $data);\r\n		}\r\n//prostore	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/{column_*,content_bottom,content_top}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n\'information/information\'\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n		if ($route == \'extension/module/prostore_blog/getblog\' && isset($this->request->get[\'blog_id\'])) {\r\n			$this->load->model(\'extension/module/prostoreblog\');\r\n\r\n			$layout_id = $this->model_extension_module_prostoreblog->getBlogLayoutId($this->request->get[\'blog_id\']); \r\n		}\r\n		if ($route == \'extension/module/prostore_news/getnews\' && isset($this->request->get[\'news_id\'])) {\r\n			$this->load->model(\'extension/module/prostorenews\');\r\n\r\n			$layout_id = $this->model_extension_module_prostorenews->getNewsLayoutId($this->request->get[\'news_id\']); \r\n		}\r\n		if ($route == \'extension/module/prostorecat_blog/getcat\' && isset($this->request->get[\'lbpath\'])) {\r\n			$this->load->model(\'extension/module/prostorecatblog\');\r\n			$lbpath = explode(\'_\', (string)$this->request->get[\'lbpath\']);\r\n			$layout_id = $this->model_extension_module_prostorecatblog->getBlogCategoryLayoutId(end($lbpath));\r\n		}\r\n\r\n// prostore	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($setting_info &&\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$setting_info[\'layout\'] = $module[\'position\'];//prostore\r\n				$setting_info[\'module_id\'] = $part[1];//prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/currency.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n			$this->response->redirect($this->request->post[\'redirect\']);\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n			if(strpos($this->request->post[\'redirect\'], \'min_price=\')){\r\n				$this->session->data[\'change_currency\'] = 1;\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/footer.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'contact\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n		if (! function_exists(\'array_column\')) {\r\n		    function array_column(array $input, $columnKey, $indexKey = null) {\r\n		        $array = array();\r\n		        foreach ($input as $value) {\r\n		            if ( !array_key_exists($columnKey, $value)) {\r\n		                trigger_error(\"Key \\\"$columnKey\\\" does not exist in array\");\r\n		                return false;\r\n		            }\r\n		            if (is_null($indexKey)) {\r\n		                $array[] = $value[$columnKey];\r\n		            }\r\n		            else {\r\n		                if ( !array_key_exists($indexKey, $value)) {\r\n		                    trigger_error(\"Key \\\"$indexKey\\\" does not exist in array\");\r\n		                    return false;\r\n		                }\r\n		                if ( ! is_scalar($value[$indexKey])) {\r\n		                    trigger_error(\"Key \\\"$indexKey\\\" does not contain scalar value\");\r\n		                    return false;\r\n		                }\r\n		                $array[$value[$indexKey]] = $value[$columnKey];\r\n		            }\r\n		        }\r\n		        return $array;\r\n		    }\r\n		}\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n		$this->load->language(\'common/footer\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		$this->load->model(\'setting/setting\');\r\n		$this->load->model(\'extension/module/prostorenews\');//!!!\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n		$data[\'scripts\'] = $this->document->getScripts(\'footer\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		// prostore\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n		$data[\'buy_click\'] = array();\r\n		if($this->config->get(\'theme_prostore_buy_click\')){\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$this->load->language(\'checkout/checkout\');\r\n			$data[\'entry_firstname\'] = $this->language->get(\'entry_firstname\');\r\n			$data[\'entry_lastname\'] = $this->language->get(\'entry_lastname\');\r\n			$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n			$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n			$data[\'entry_comment\'] = $this->language->get(\'entry_comment\');\r\n			$data[\'text_prostore_buy_click\'] = $this->language->get(\'text_prostore_buy_click\');\r\n			$data[\'button_fastorder_sendorder\'] = $this->language->get(\'button_prostore_sendorder\');\r\n			$data[\'buy_click\'] = $this->config->get(\'theme_prostore_buy_click\');\r\n\r\n			// Captcha\r\n			if ($this->config->get(\'theme_prostore_config_captcha_fo\'))  {\r\n				$data[\'captcha_fo\'] = $this->load->controller(\'extension/captcha/\' . $this->config->get(\'theme_prostore_config_captcha_fo\'));\r\n\r\n			} else {\r\n				$data[\'captcha_fo\'] = \'\';\r\n			}\r\n						\r\n			if ($this->customer->isLogged()) {\r\n				$this->load->model(\'account/customer\');\r\n				$data[\'customer_info\'] = $this->model_account_customer->getCustomer($this->customer->getId());\r\n			}\r\n			$data[\'buyclick_form\'] = $this->load->view(\'product/buyclick_form\', $data);\r\n		}	\r\n\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'js_codes\'] = $this->document->getScripts(\'js_code\'); \r\n		$data[\'styles\'] = $this->document->getStyles();\r\n\r\n		if ($this->request->server[\'HTTPS\']) {\r\n			$server = $this->config->get(\'config_ssl\');\r\n		} else {\r\n			$server = $this->config->get(\'config_url\');\r\n		}\r\n\r\n		$data[\'version\'] = $this->config->get(\'theme_prostore_version\');\r\n\r\n		$data[\'top_links\'] = array();\r\n		if($this->config->get(\'theme_prostorelinks_array\')){\r\n			$data[\'top_links\'] = $this->config->get(\'theme_prostorelinks_array\');\r\n			$data[\'top_links\'] = $data[\'top_links\'][$this->config->get(\'config_language_id\')];\r\n			foreach($data[\'top_links\'] as $key => $link){ \r\n				if(strpos($key,\'e\') === 0 ){ continue;}\r\n				$data[\'top_links\'][$key][key($link)] = $this->url->link(current($link));	\r\n			}\r\n		}\r\n\r\n		$this->load->model(\'extension/module/prostore\');\r\n\r\n					\r\n		$data[\'footer_navs\'] = array();\r\n		$footer_navs = $this->config->get(\'theme_prostore_footer_nav\');\r\n		if(isset($footer_navs)){\r\n			foreach($footer_navs as $footer_nav){\r\n				\r\n				if(isset($footer_nav[\'type\'][0][\'links\'])){\r\n					foreach($footer_nav[\'type\'][0][\'links\'] as $key => $link){\r\n						if (isset($data[\'top_links\'][$key][\'target\'])) {\r\n							$footer_nav[\'target\'][$key] = $data[\'top_links\'][$key][\'target\'];\r\n						}else{\r\n							$footer_nav[\'target\'][$key] = \'\';\r\n						}\r\n						$footer_nav[\'type\'][0][\'names\'][$key] = $this->model_extension_module_prostore->getName4MenuItem($key,$data);\r\n						if(strpos($key,\'e\') === 0 ){ // Extralinks do not change\r\n							if (isset($data[\'top_links\'][$key])) {\r\n								$footer_nav[\'type\'][0][\'links\'][$key] = current($data[\'top_links\'][$key]);\r\n							  }else{\r\n								$footer_nav[\'type\'][0][\'links\'][$key] = \'\';\r\n							  } 							\r\n							continue;\r\n						}\r\n						$footer_nav[\'type\'][0][\'links\'][$key] = $this->url->link($link);\r\n					}					\r\n				}\r\n				if(isset($footer_nav[\'type\'][1][\'links\'][\'html\'])){\r\n					if ($footer_nav[\'type\'][1][\'links\'][\'html\']) {\r\n						$footer_nav[\'type\'][1][\'links\'][\'html\'] = html_entity_decode($footer_nav[\'type\'][1][\'links\'][\'html\'][$data[\'language_id\']]);\r\n					}\r\n				}\r\n\r\n				$data[\'footer_navs\'][$footer_nav[\'sort\']] = $footer_nav;\r\n			}\r\n		}\r\n		ksort($data[\'footer_navs\']);\r\n\r\n		//Социальные сети\r\n		$data[\'social_navs\'] = array();\r\n		$social_links = $this->model_setting_setting->getSetting(\'theme_prostoresoclinks\');\r\n		$data[\'social_links\'] = $social_links[\'theme_prostoresoclinks_array\'];\r\n		$data[\'social_navs\'] = $this->config->get(\'theme_prostore_social_nav\');	\r\n\r\n		$data[\'messenger_navs\'] = array();\r\n		$messenger_links = $this->model_setting_setting->getSetting(\'theme_prostoremeslinks\');\r\n		$data[\'messenger_links\'] = $messenger_links[\'theme_prostoremeslinks_array\'];\r\n		$data[\'messenger_navs\'] = $this->config->get(\'theme_prostore_messenger_nav\');		\r\n		$data[\'messenger_status\'] = $this->config->get(\'theme_prostore_messenger_status\');\r\n		$data[\'messenger_pos\'] = $this->config->get(\'theme_prostore_messenger_pos\');\r\n\r\n		$data[\'payment_icons\'] = array();\r\n		if($this->config->get(\'theme_prostore_vidg_payicons\')){\r\n			$payment_icons = $this->config->get(\'theme_prostore_vidg_payicons\');\r\n			foreach ($payment_icons as $key => $payment_icon) {\r\n				if (!is_file(DIR_IMAGE . $payment_icon[\'image\'])) {\r\n					$payment_icon[\'image\'] = \'no_image.png\';\r\n				}\r\n				if ($this->request->server[\'HTTPS\']) {\r\n					$payment_icons[$key][\'thumb\'] = $this->config->get(\'config_ssl\') . \'image/\' . $payment_icon[\'image\'];\r\n				} else {\r\n					$payment_icons[$key][\'thumb\'] = $this->config->get(\'config_url\') . \'image/\' . $payment_icon[\'image\'];\r\n				}\r\n			}\r\n			$paysort  = array_column($payment_icons, \'sort\');\r\n			array_multisort($paysort, SORT_ASC, $payment_icons);\r\n			$data[\'payment_icons\'] = $payment_icons;\r\n		}\r\n\r\n		$data[\'text_newsletter\'] = $this->language->get(\'text_newsletter\');\r\n		$data[\'text_footer_subscribe_email\'] = $this->language->get(\'text_footer_subscribe_email\');\r\n		$data[\'text_header_callback\'] = $this->language->get(\'text_header_callback\');\r\n		$data[\'text_social_navs\'] = $this->language->get(\'text_social_navs\');\r\n		$data[\'callback_status\'] = $this->config->get(\'theme_prostore_callback_status\');\r\n		$data[\'soc_stat\'] = $this->config->get(\'theme_prostore_footer_soc_stat\');\r\n		$data[\'prostore_phones\'] = array();\r\n		$data[\'prostore_phones_main\'] = array();\r\n		$prostore_phones = $this->config->get(\'theme_prostore_phones\');\r\n\r\n		if ($prostore_phones) {\r\n		  foreach ($prostore_phones as $key => $prostore_phone) {\r\n			$data[\'prostore_phones\'][$prostore_phone[\'sort\']] = $prostore_phone;\r\n		  }\r\n		  ksort($data[\'prostore_phones\']);\r\n		  $data[\'prostore_phones_main\'] = current($data[\'prostore_phones\']);\r\n		}\r\n\r\n		$data[\'theme_color\'] = $this->config->get(\'theme_prostore_color\');\r\n		$data[\'theme_fc_color\'] = $this->config->get(\'theme_prostore_color_2\');\r\n		$data[\'fontawesome\'] = $this->config->get(\'theme_prostore_fontawesome\');\r\n		$data[\'bootstrap_ver\'] = $this->config->get(\'theme_prostore_bootstrap_ver\');\r\n		$data[\'theme_color_1\'] = $this->config->get(\'theme_prostore_custom_color_1\');\r\n		$data[\'theme_color_2\'] = $this->config->get(\'theme_prostore_custom_color_2\');\r\n		$data[\'theme_fc_color_1\'] = $this->config->get(\'theme_prostore_custom_fc_color_1\');\r\n		$data[\'theme_fc_color_2\'] = $this->config->get(\'theme_prostore_custom_fc_color_2\');\r\n		$data[\'footer_type\'] = $this->config->get(\'theme_prostore_footer_type\');\r\n		if (isset($this->request->get[\'route\']) && $this->request->get[\'route\'] == \'checkout/checkout\') {\r\n			$data[\'footer_type\'] = \'checkout\';\r\n		}\r\n		if ($this->config->get(\'config_maintenance\')) {\r\n			$this->user = new Cart\\User($this->registry);\r\n			if (!$this->user->isLogged()) {\r\n				$data[\'footer_type\'] = \'maintenance\';\r\n			}\r\n		}\r\n		$data[\'subscribe_status\'] = $this->config->get(\'theme_prostore_subscribe_status\');\r\n		$data[\'subscribe_title\'] = $this->config->get(\'theme_prostore_subscribe_title\' . $this->config->get(\'config_language_id\'));\r\n		$data[\'subscribe_subtitle\'] = $this->config->get(\'theme_prostore_subscribe_subtitle\' . $this->config->get(\'config_language_id\'));\r\n		$data[\'js_footorhead\'] = $this->config->get(\'theme_prostore_js_footorhead\');\r\n		$data[\'footer_copyright\'] = html_entity_decode($this->config->get(\'theme_prostore_footer_copyright\' . $this->config->get(\'config_language_id\')), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'footer_copyright\'] = str_replace(\'{{year}}\',date(\'Y\'),$data[\'footer_copyright\']);\r\n		$data[\'footer_text\'] = html_entity_decode($this->config->get(\'theme_prostore_footer_text\' . $this->config->get(\'config_language_id\')), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'footer_t_logo\'] = $this->config->get(\'theme_prostore_footer_t_logo\');\r\n		$data[\'text_logo\'] = html_entity_decode($this->config->get(\'theme_prostore_footer_text_logo\'), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'shop_email\'] = $this->config->get(\'config_email\');\r\n		$data[\'config_address\'] = $this->config->get(\'config_address\');\r\n\r\n		$data[\'footer_categories\'] = $this->config->get(\'theme_prostore_footer_categories\');\r\n		$data[\'text_prostore_subscribe_btn\'] = $this->language->get(\'text_prostore_subscribe_btn\');\r\n		$data[\'text_footer_questions\'] = $this->language->get(\'text_footer_questions\');\r\n		$data[\'text_footer_link\'] = $this->language->get(\'text_footer_link\');\r\n		$data[\'text_footer_pay\'] = $this->language->get(\'text_footer_pay\');\r\n		$data[\'text_prostore_maintenance_phone\'] = $this->language->get(\'text_prostore_maintenance_phone\');\r\n		$data[\'text_prostore_maintenance_email\'] = $this->language->get(\'text_prostore_maintenance_email\');\r\n		$data[\'text_prostore_con_soc2\'] = $this->language->get(\'text_prostore_con_soc2\');\r\n		$data[\'lazyload\'] = $this->config->get(\'theme_prostore_lazyload\');\r\n		$data[\'config_open\'] = html_entity_decode($this->config->get(\'config_open\'), ENT_QUOTES, \'UTF-8\');\r\n\r\n		$data[\'geocode\'] = $this->config->get(\'config_geocode\');		\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		$data[\'address_schema\'] = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\", \"\\\"\"),\' \', strip_tags(html_entity_decode($data[\'config_address\'], ENT_QUOTES, \'UTF-8\')));\r\n		$data[\'meta_description\'] = $this->config->get(\'config_meta_description\');\r\n		$data[\'telephone\'] = $this->config->get(\'config_telephone\');\r\n		if ($this->config->get(\'config_country_id\')) {\r\n			$this->load->model(\'localisation/country\');\r\n			$country = $this->model_localisation_country->getCountry($this->config->get(\'config_country_id\'));\r\n			$data[\'country_name\'] = $country[\'name\'];\r\n		}\r\n		if ($this->config->get(\'config_zone_id\')) {\r\n			$this->load->model(\'localisation/zone\');\r\n			$zone = $this->model_localisation_zone->getZone($this->config->get(\'config_zone_id\'));\r\n			$data[\'zone_name\'] = $zone[\'name\'];\r\n		}\r\n		if ($data[\'geocode\']) {\r\n			$tempcode = explode(\',\', $data[\'geocode\']);\r\n			if (isset($tempcode[1])) {\r\n				$data[\'latitude\'] = $tempcode[0]; \r\n				$data[\'longitude\'] = $tempcode[1]; \r\n			}\r\n		}\r\n		$data[\'currency\'] = $this->config->get(\'config_currency\');\r\n\r\n		if ($this->config->get(\'theme_prostore_subscribe_pdata\')) {\r\n			$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_subscribe_pdata\'));\r\n\r\n			if ($information_info) {\r\n				$data[\'text_prostore_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'text_prostore_subscribe_btn\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_subscribe_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n			} else {\r\n				$data[\'text_prostore_pdata\'] = \'\';\r\n			}\r\n		} else {\r\n			$data[\'text_prostore_pdata\'] = \'\';\r\n		}\r\n		if ($this->config->get(\'theme_prostore_buy_click_pdata\')) {\r\n			$click_pdata = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_buy_click_pdata\'));\r\n			if ($click_pdata) {\r\n				$data[\'text_click_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_prostore_sendorder\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_buy_click_pdata\'), true), $click_pdata[\'title\'], $click_pdata[\'title\']);\r\n			} else {\r\n				$data[\'text_click_pdata\'] = \'\';\r\n			}\r\n		} else {\r\n			$data[\'text_click_pdata\'] = \'\';\r\n		}\r\n\r\n		$checkout_info = $this->model_catalog_information->getInformation($this->config->get(\'config_checkout_id\'));\r\n		if ($checkout_info) {\r\n			$data[\'checkout_info_title\'] = $checkout_info[\'title\'];\r\n			$data[\'checkout_info_link\'] = $this->url->link(\'information/information\', \'information_id=\' . $this->config->get(\'config_checkout_id\'), true);\r\n		} else {\r\n			$data[\'checkout_info_title\'] = \'\';\r\n		}\r\n		\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_footer_logo\'))) {\r\n			$data[\'footer_logo\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_footer_logo\');\r\n		} else {\r\n			$data[\'footer_logo\'] = \'\';\r\n		}\r\n\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_subscribe_email_logo\'))) {\r\n			$data[\'subscribe_email_logo\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_subscribe_email_logo\');\r\n		} else {\r\n			$data[\'subscribe_email_logo\'] = \'\';\r\n		}\r\n\r\n		$data[\'custom_css\'] = $this->config->get(\'theme_prostore_css\');\r\n		$data[\'custom_js\'] = html_entity_decode($this->config->get(\'theme_prostore_js\'), ENT_QUOTES, \'UTF-8\');\r\n		$host = isset($this->request->server[\'HTTPS\']) && (($this->request->server[\'HTTPS\'] == \'on\') || ($this->request->server[\'HTTPS\'] == \'1\')) ? HTTPS_SERVER : HTTP_SERVER;\r\n\r\n		if ($this->request->server[\'REQUEST_URI\'] == \'/\') {\r\n		  $data[\'og_url\'] = $this->url->link(\'common/home\');\r\n		} else {\r\n		  $data[\'og_url\'] = $host . substr($this->request->server[\'REQUEST_URI\'], 1, (strlen($this->request->server[\'REQUEST_URI\'])-1));\r\n		}\r\n\r\n		$data[\'name\'] = $this->config->get(\'config_name\');\r\n		$data[\'callback\'] = $this->load->controller(\'extension/module/callback\');\r\n		$data[\'islogged\'] = $this->customer->isLogged();\r\n		$data[\'cookieagry\'] = 0;\r\n\r\n		if (isset($_COOKIE[\"cookieagry\"])){\r\n			$data[\'cookieagry\'] = 1;\r\n		}\r\n		\r\n		if ($this->config->get(\'theme_prostore_cookies_pdata\')) {\r\n			$information_cookies = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_cookies_pdata\'));\r\n			if ($information_cookies) {\r\n				$data[\'text_prostore_cookieagry\'] = sprintf($this->language->get(\'text_prostore_cookie_required\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_cookies_pdata\'), true), $information_cookies[\'title\'], $information_cookies[\'title\'], ENT_QUOTES, \'UTF-8\');\r\n			} else {\r\n				$data[\'text_prostore_cookieagry\'] = \'\';\r\n			}\r\n		} else {\r\n			$data[\'text_prostore_cookieagry\'] = \'\';\r\n		}\r\n		$data[\'home\'] = $this->url->link(\'common/home\');\r\n		// prostore end\r\n		]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/header.php\">\r\n		<operation>\r\n			<search><![CDATA[public function index()]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n  public function getwish() {\r\n    if ($this->customer->isLogged() || $this->config->get(\'theme_prostore_wishlist\')) {\r\n		$this->load->model(\'account/wishlist\');\r\n		$data[\'wishlist_count\'] = $this->model_account_wishlist->getTotalWishlistLb();\r\n    } else {\r\n		$data[\'wishlist_count\'] = isset($this->session->data[\'wishlist\']) ? count($this->session->data[\'wishlist\']) : 0;\r\n	}\r\n    $this->response->setOutput($this->load->view(\'common/header_wishlist\', $data));\r\n  }\r\n  \r\n  public function getcompare() {\r\n    $this->load->language(\'extension/theme/prostore\');\r\n    $data[\'compare_count\'] = isset($this->session->data[\'compare\']) ? count($this->session->data[\'compare\']) : 0;\r\n    $this->response->setOutput($this->load->view(\'common/header_compare\', $data));\r\n  }\r\n\r\n  public function createNavMobiView($data,$type = \'\') {\r\n    $view = array();\r\n    $view = $this->cache->get(\'navviewmobi\'.$type.\'.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\')) ?: [];\r\n	if (!$this->config->get(\'developer_theme\')) {\r\n		$view = [];\r\n	}\r\n    if (!$view) {\r\n        $orientTypes = array(\r\n              \'main_navs_v\' => \'header_mobi\',  // FOR VERTICAL MENU\r\n              \'main_navs\' => \'header_mobi\',     // FOR HORISONTAL MENU\r\n              \'header_navs\' => \'header_mobi\'     // FOR HORISONTAL MENU\r\n        );\r\n        \r\n        $data[\'nav_icons\'] = $this->prepareSvgIcon(); \r\n        $data[\'header_nav_icons\'] = $this->prepareHeaderSvgIcon();\r\n\r\n		if ($this->config->get(\'theme_prostore_footer_mobile_menu\') && $this->config->get(\'theme_prostore_footer_mobile_menu_array\')[\'catalog\']) {\r\n			$mobile_menu = true;\r\n		} else {\r\n			$mobile_menu = false;\r\n		}\r\n\r\n        if (!$this->config->get(\'theme_prostore_mobmenu_h_status\')) {\r\n            unset($orientTypes[\'main_navs\']);\r\n        }\r\n        if (!$this->config->get(\'theme_prostore_mobmenu_v_status\') || $mobile_menu) {\r\n            unset($orientTypes[\'main_navs_v\']);\r\n        }\r\n\r\n        if ($type == \'_fix_menu\') {\r\n          $orientTypes = array(\r\n                \'main_navs_v\' => \'header_mobi\'  // FOR VERTICAL MENU\r\n          );     \r\n        }        \r\n\r\n        $data[\'orientTypes\'] = $orientTypes;\r\n        foreach ($orientTypes as $index => $typeName) { \r\n\r\n            foreach($data[$index] as $key => $main_nav){\r\n                  if(!isset($main_nav[\'type\'][0][\'links\'])){\r\n                    $data[$index][$key][\'type\'][0][\'links\'] = $data[\'topcat\'];\r\n                  }\r\n\r\n                  if ($main_nav[\'settype\'] == 1 || $main_nav[\'settype\'] == 2) { \r\n                    if (isset($main_nav[\'type\'][$main_nav[\'settype\']])) {\r\n                        $data[$index][$key][\'type\'][$main_nav[\'settype\']] = $this->prepCustLinks($data,$main_nav[\'type\'][$main_nav[\'settype\']],$key);\r\n                    }else{\r\n                        $data[$index][$key][\'type\'][$main_nav[\'settype\']] = array();\r\n                    }\r\n                  }\r\n            }        \r\n        }\r\n\r\n        $view = $this->load->view(\'common/header_mobi\', $data);\r\n        $this->cache->set(\'navviewmobi\'.$type.\'.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\'), $view);       \r\n    }\r\n\r\n\r\n    return $view;\r\n  }\r\n\r\n  public function prepareSvgIcon(){\r\n    $outData = array();\r\n    if ($this->config->get(\'theme_prostore_nav_icons\') && is_array($this->config->get(\'theme_prostore_nav_icons\'))) {\r\n      foreach ($this->config->get(\'theme_prostore_nav_icons\') as $id => $entityIcons) {\r\n        foreach ($entityIcons[\'image\'] as $type => $icons) {\r\n          foreach ($icons as $key => $icon) {\r\n            if (is_file(DIR_IMAGE . $icon)) {\r\n              $outData[$id][\'image\'][$type][$key] = html_entity_decode(file_get_contents(DIR_IMAGE . $icon));\r\n            }else{\r\n              $outData[$id][\'image\'][$type][$key] = \'\';\r\n            }\r\n          }\r\n        }\r\n      }\r\n    } \r\n    return $outData;     \r\n  }\r\n\r\n\r\n  public function prepareHeaderSvgIcon(){\r\n    $outData = array();\r\n    if ($this->config->get(\'theme_prostore_header_nav_icons\') && is_array($this->config->get(\'theme_prostore_header_nav_icons\'))) {\r\n      foreach ($this->config->get(\'theme_prostore_header_nav_icons\') as $id => $entityIcons) {\r\n        foreach ($entityIcons[\'image\'] as $key => $icon) {\r\n            if (is_file(DIR_IMAGE . $icon)) {\r\n              $outData[$id][\'image\'][\'h\'][$key] = html_entity_decode(file_get_contents(DIR_IMAGE . $icon));\r\n            }else{\r\n              $outData[$id][\'image\'][][$key] = \'\';\r\n            }\r\n        }\r\n      } \r\n    }\r\n    return $outData;     \r\n  }\r\n\r\n\r\n  public function createNavView($data) {\r\n\r\n    $view = $this->cache->get(\'navview.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\')) ?: []; \r\n	if (!$this->config->get(\'developer_theme\')) {\r\n		  $view = [];\r\n	}     \r\n    if (!$view) { \r\n        $view[\'main_navs\'] = array();\r\n        $view[\'main_navs_v\'] = array();\r\n        $view[\'header_navs\'] = array();\r\n\r\n        $orientTypes = array(\r\n              \'main_navs\' => \'header_nav_\',     // FOR HORISONTAL MENU\r\n              \'main_navs_v\' => \'header_nav_v_\',  // FOR VERTICAL MENU\r\n              \'header_navs\' => \'header_top_\'     // FOR HEADER MENU\r\n        );\r\n   \r\n        $data[\'nav_icons\'] = $this->prepareSvgIcon();\r\n        $data[\'header_nav_icons\'] = $this->prepareHeaderSvgIcon();\r\n\r\n        foreach ($orientTypes as $index => $type) {\r\n\r\n            foreach($data[$index] as $key => $main_nav){  \r\n                  if(!isset($main_nav[\'type\'][0][\'links\'])){\r\n                    $data[$index][$key][\'type\'][0][\'links\'] = $data[\'topcat\'];\r\n                  }\r\n                  $data[\'number\'] = $key;\r\n				  $data[\'naw_row_id\'] = $main_nav[\'id\'];\r\n\r\n                switch ($main_nav[\'settype\']) {\r\n                  case \'0\': // Category (Mega menu)\r\n\r\n                    \r\n\r\n                    $data[$index][$key][\'type\'][0][\'cattoview\'] = $this->doColumns($data,$main_nav,$key); \r\n                    if (isset($main_nav[\'addelem\'][\'settype\'])) {\r\n                      $adElSetType = $main_nav[\'addelem\'][\'settype\']; \r\n                      if ($adElSetType == 2) {\r\n                          $adElSetType = 0;\r\n                      }\r\n                      if (isset($main_nav[\'addelem\'][\'type\'][$adElSetType]) && !empty($main_nav[\'addelem\'][\'type\'][$adElSetType])) {\r\n\r\n                        $data[$index][$key][\'addelem\'][\'content\'] = $this->righElemPrepare($main_nav[\'addelem\']);\r\n\r\n                      }\r\n                    }\r\n\r\n\r\n                    $view[$index][$key][\'view\'] = $this->load->view(\'common/\' .  $type . \'mega\', $data); \r\n                    if ($type == \'header_nav_v_\') { \r\n//                      $data[$index][$key][\'type\'][0][\'toplinks\'] = $this->prepCustLinks($data,$main_nav[\'type\'][0][\'toplinks\'],$key);\r\n//                      var_dump($this->model_extension_module_prostore->getName4MenuItem(\'o4\',$data));\r\n                      $view[$index][$key][\'view_content\'] = $this->load->view(\'common/\' .  $type . \'mega_content\', $data); \r\n                    }         \r\n                    break;\r\n\r\n                  case \'1\': // DropDown. Custom list\r\n\r\n                    $data[$index][$key][\'type\'][1] = $this->prepCustLinks($data,$main_nav[\'type\'][1],$key);\r\n\r\n                    $view[$index][$key][\'view\'] = $this->load->view(\'common/\' .  $type . \'cust_drop\', $data);\r\n\r\n                    break;\r\n\r\n                  case \'2\': // Simple custom list\r\n                    if (isset($main_nav[\'type\'][2])) {\r\n                        $data[$index][$key][\'type\'][2] = $this->prepCustLinks($data,$main_nav[\'type\'][2],$key);\r\n                    }else{\r\n                        $data[$index][$key][\'type\'][2] = array();\r\n                    }\r\n\r\n                    $view[$index][$key][\'view\'] = $this->load->view(\'common/\' .  $type . \'cust\', $data);\r\n\r\n                    break;\r\n\r\n                  case \'3\': // Category. DropDown.\r\n                            \r\n                    $view[$index][$key][\'view\'] = $this->load->view(\'common/\' .  $type . \'drop\', $data);\r\n\r\n                    break;\r\n\r\n                }\r\n\r\n            }\r\n            if ($index == \'main_navs_v\' && !empty($view[\'main_navs_v\'])) {\r\n              $n = $this->config->get(\'theme_prostore_main_nav_v_header\');\r\n              $view[\'main_navs_v\'][\'header\'] = $n[$this->config->get(\'config_language_id\')];\r\n            }\r\n\r\n        }\r\n\r\n        $this->cache->set(\'navview.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\'), $view);\r\n    }\r\n \r\n    return $view;\r\n  }\r\n\r\n  private function prepCustLinks($data,$main_nav,$key) {\r\n\r\n          if(!isset($main_nav[\'links\'])) { \r\n            $main_nav[\'links\'] = array();\r\n          }\r\n         \r\n          if (isset($main_nav[\'language\']) && !$main_nav[\'language\'][$data[\'language_id\']][\'href\']) {\r\n            $main_nav[\'language\'][$data[\'language_id\']][\'href\'] = \'#\';\r\n          }\r\n          foreach ($main_nav[\'links\'] as $id => $link) {\r\n            if (isset($data[\'top_links\'][$id][\'target\'])) {\r\n              $main_nav[\'target\'][$id] = $data[\'top_links\'][$id][\'target\'];\r\n            }else{\r\n              $main_nav[\'target\'][$id] = \'\';\r\n            }\r\n            $main_nav[\'name\'][$id] = $this->model_extension_module_prostore->getName4MenuItem($id,$data);\r\n          }\r\n\r\n          return $main_nav; \r\n  }\r\n\r\n  private function doColumns($data,$main_nav,$key) {\r\n          if(!isset($main_nav[\'type\'][0][\'links\'])){\r\n            $main_nav[\'type\'][0][\'links\'] = array();\r\n            if ($data[\'topcat\']) {\r\n              $main_nav[\'type\'][0][\'links\'] = $data[\'topcat\'];\r\n            }\r\n          }\r\n         \r\n          $catToView = array();\r\n          foreach ($main_nav[\'type\'][0][\'links\'] as $cat => $link) {\r\n            $cat_id = substr($cat, 1); \r\n            if(!isset($data[\'categories\'][\'categoriesls\'][$cat_id])){continue;}\r\n            $subCatsInfo = $data[\'categories\'][\'categoriesls\'][$cat_id];\r\n             \r\n            if (isset($subCatsInfo[\'column\']) && $subCatsInfo[\'column\']) {\r\n              $columnNumb = $subCatsInfo[\'column\']; \r\n            }else{\r\n              $tempColNum = $this->model_catalog_category->getCategory($cat_id);\r\n              if ($tempColNum [\'column\']) {\r\n                  $columnNumb = $tempColNum [\'column\'];\r\n              }else{\r\n                  $columnNumb = 1;  //Default columnNumb\r\n              }\r\n            }\r\n\r\n            $subCatNumb = $subCatsInfo[\'childrencount\']; \r\n            $subCatInColumnNumb = round($subCatNumb/$columnNumb); \r\n            $i = 0;\r\n            $k = 0;\r\n\r\n            foreach ($subCatsInfo[\'children\'] as $subCat) {\r\n              $catToView[$cat_id][\'columns\'][$k][$i] = $subCat;\r\n              $i++;\r\n              if ($i == $subCatInColumnNumb && $k != $columnNumb-1) { \r\n                $i = 0;\r\n                $k++;\r\n              }              \r\n            }\r\n\r\n            $catToView[$cat_id][\'width\'] = 100/$columnNumb;\r\n          }\r\n\r\n          if (isset($main_nav[\'type\'][0][\'toplinks\'])) {\r\n            $catToView[\'main_toplinks\'] = array();\r\n            foreach ($main_nav[\'type\'][0][\'toplinks\'] as $id => $toplink) {\r\n              if (strpos($id,\'e\') === 0) {\r\n                $fullLink = $toplink;\r\n              }else{\r\n                $fullLink = $this->url->link($toplink);\r\n              }\r\n \r\n              if (isset($data[\'top_links\'][$id][\'target\'])) {\r\n                $target = $data[\'top_links\'][$id][\'target\'];\r\n                $catToView[\'main_toplinks\'][] = array(\r\n                  \'name\'  => $this->model_extension_module_prostore->getName4MenuItem($id,$data),\r\n                  \'link\'  => $fullLink,\r\n                  \'target\'  => $target\r\n                );\r\n              }else{\r\n                $catToView[\'main_toplinks\'][] = array(\r\n                  \'name\'  => $this->model_extension_module_prostore->getName4MenuItem($id,$data),\r\n                  \'link\'  => $fullLink\r\n                );\r\n              }\r\n            }\r\n          }\r\n\r\n\r\n      return $catToView;\r\n  }\r\n\r\n  private function righElemPrepare($elemData){ \r\n\r\n    $this->load->model(\'catalog/product\');\r\n    $this->load->model(\'catalog/category\');\r\n    $this->load->model(\'catalog/manufacturer\');\r\n    $this->load->model(\'tool/image\');   \r\n    $data[\'main_recs\'] = array();\r\n    $data[\'main_prods\'] = array();\r\n    $data[\'main_manf\'] = array();\r\n    $data[\'main_banners\'] = array();\r\n\r\n    if (!empty($elemData[\'type\'][0][\'banners\'])) {\r\n      $this->load->model(\'design/banner\');\r\n      foreach ($elemData[\'type\'][0][\'banners\'] as $banner_id => $banner) {\r\n        $bannerData = $this->model_design_banner->getBanner($banner_id);\r\n        if (!$bannerData) {\r\n          continue;\r\n        }\r\n        $images = array();\r\n        foreach ($bannerData as $imageData) {\r\n          $images[] = array(\r\n            \'title\' => html_entity_decode($imageData[\'title\'], ENT_QUOTES, \'UTF-8\'),\r\n            \'link\'  => $imageData[\'link\'] ? $imageData[\'link\'] : \'#\',\r\n            \'image\' => $this->model_tool_image->resize($imageData[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_header_banner_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_header_banner_height\'))\r\n          );\r\n        }\r\n        $data[\'main_banners\'][][\'images\'] = $images;\r\n      }\r\n    }\r\n\r\n            if(!$elemData[\'settype\']){\r\n\r\n                $this->load->model(\'extension/module/prostore\');\r\n\r\n                $data[\'labelsinfo\'] = $this->prostore->labels->getProductLabelsConfig();\r\n                $data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n				$data[\'cart_link\'] = $this->url->link(\'checkout/cart\');\r\n\r\n                if (!isset($elemData[\'type\'][0][\'links\'])) {\r\n                    $elemData[\'type\'][0][\'links\'] = array();\r\n                }\r\n                \r\n                foreach($elemData[\'type\'][0][\'links\'] as $prodId => $product){ \r\n                  $product_info = $this->model_catalog_product->getProduct($prodId);\r\n\r\n                  if(empty($product_info)){ continue; }                 \r\n\r\n                  if ($product_info[\'image\']) { \r\n                    $thumb = $this->model_tool_image->resize($product_info[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_main_rec_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_main_rec_height\')); \r\n                  } else {\r\n                    $thumb = \'\';\r\n                  }\r\n                  if ($this->customer->isLogged() || !$this->config->get(\'config_customer_price\')) {\r\n                    $price = $this->currency->format($this->tax->calculate($product_info[\'price\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']);\r\n                  } else {\r\n                    $price = false;\r\n                  }\r\n                  if ((float)$product_info[\'special\']) {\r\n                    $special = $this->currency->format($this->tax->calculate($product_info[\'special\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']);\r\n                  } else {\r\n                    $special = false;\r\n                  }\r\n\r\n				if ($this->config->get(\'config_review_status\')) {\r\n					$rating = $product_info[\'rating\'] > 0 ? number_format($product_info[\'rating\'], 1) : 0;\r\n				} else {\r\n					$rating = false;\r\n				}\r\n\r\n				$extraImages = array();			\r\n				if ($this->config->get(\'theme_prostore_images_status\')) {\r\n					$images = array_slice($this->model_catalog_product->getProductImages($product_info[\'product_id\']), 0, (int)$this->config->get(\'theme_prostore_images_array\'));\r\n						foreach($images as $imageX){\r\n						$extraImages[] = $this->model_tool_image->resize($imageX[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'));\r\n					}\r\n				}\r\n\r\n        $productLabels = $this->prostore->labels->getLabels4Product($product_info);\r\n        \r\n        extract($productLabels);\r\n\r\n				$cartProductInfo = $this->prostore->helper->getCartInfo4Product($product_info);\r\n\r\n				if ($product_info[\'quantity\'] <= 0) {\r\n					$stock = $product_info[\'stock_status\'];\r\n				} elseif ($this->config->get(\'config_stock_display\')) {\r\n					$stock = $this->language->get(\'text_instock\') . \': \' . $product_info[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\');\r\n				} else {\r\n					$stock = $this->language->get(\'text_instock\');\r\n				}	\r\n				\r\n				if ($product_info[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n					$buy_btn = $product_info[\'stock_status\'];\r\n				} else {\r\n					$buy_btn = \'\';\r\n				}\r\n				\r\n				if ($this->config->get(\'theme_prostore_manufacturer\') == 1) {\r\n					$manufacturer = $this->language->get(\'text_prostore_model\') . \' \' . $product_info[\'model\'];\r\n				} elseif ($this->config->get(\'theme_prostore_manufacturer\') == 2) {\r\n					$manufacturer =  $this->language->get(\'text_prostore_manufacturer\') . \' \' . $product_info[\'manufacturer\'];\r\n				} else {\r\n					$manufacturer = false;\r\n				}\r\n				\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($product_info[\'product_id\']);\r\n\r\n\r\n                  $prodCatInfo = array();\r\n                  $prodCat = array();\r\n                  $prodCats = $this->model_catalog_product->getCategories($prodId); \r\n                  if ($prodCats) {\r\n                    $prodCatid = array_pop($prodCats); \r\n                    $prodCatid = $prodCatid[\'category_id\']; \r\n                    $prodCat = $this->model_catalog_category->getCategory($prodCatid); \r\n                    if ($prodCat) {\r\n                        $prodCatInfo[\'name\'] = $prodCat[\'name\'];\r\n                        $prodCatInfo[\'href\'] = $this->url->link(\'product/category\', \'category_id=\' . $prodCatid);\r\n                    }\r\n                  }\r\n                  $data[\'main_prods\'][] = array(\r\n                                \'thumb\'       => $thumb,\r\n                                \'name\'        => $product_info[\'name\'], \r\n                                \'category\'        => $prodCat, \r\n                                \'price\'       => $price,\r\n                                \'special\'     => $special,\r\n\r\n								\'product_id\'  => $product_info[\'product_id\'],\r\n								\'manufacturer\'  => $manufacturer,\r\n								\'quantity\'        => $product_info[\'quantity\'],\r\n								\'stock\'        => $stock,\r\n								\'images\'       => $extraImages,	\r\n								\'isnewest\'       => $isnewest,\r\n								\'sales\'       => $sales,\r\n								\'discount\'       => $discount,\r\n								\'catch\'       => $catch,\r\n								\'nocatch\'       => $nocatch,\r\n								\'popular\'	  => $popular,\r\n								\'hit\'	 	  => $hit,\r\n								\'isincart\'	  => $cartProductInfo[\'isincart\'],\r\n								\'to_cart_quantity\'	  => $cartProductInfo[\'to_cart_quantity\'],\r\n								\'buy_btn\'	  => $buy_btn,\r\n								\'reward\'      => $product_info[\'reward\'],\r\n								\'special_date_end\'      => $special_date_end,\r\n								\'wish_compare_data\' => $wishCompareData,	\r\n								\'image_product_width\' => $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'),\r\n								\'image_product_height\' => $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'),\r\n\r\n                                \'minimum\'     => $product_info[\'minimum\'] > 0 ? $product_info[\'minimum\'] : 1,\r\n								\'rating\'      => $rating,\r\n								\'href\'        => $this->url->link(\'product/product\', \'product_id=\' . $product_info[\'product_id\'])             \r\n                  );\r\n                }\r\n            }elseif($elemData[\'settype\'] == 2){\r\n                if(isset($elemData[\'type\'][0][\'manf\'])){\r\n                    foreach($elemData[\'type\'][0][\'manf\'] as $manfId => $product){\r\n                      $manufacturer_info = $this->model_catalog_manufacturer->getManufacturer($manfId);\r\n					  \r\n					  if(empty($manufacturer_info)){ continue; }\r\n\r\n                            if ($manufacturer_info[\'image\']) {\r\n                                $image = $this->model_tool_image->resize($manufacturer_info[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_height\'));\r\n                            } else {\r\n                                $image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_height\'));\r\n                            }\r\n\r\n                      $data[\'main_manf\'][] = array(\r\n                                    \'name\'        => $manufacturer_info[\'name\'],\r\n                                    \'href\'        => $this->url->link(\'product/manufacturer/info\', \'manufacturer_id=\' . $manufacturer_info[\'manufacturer_id\']),\r\n                                    \'image\'        => $image              \r\n                      );\r\n                    }             \r\n                }             \r\n            }else{\r\n                $data[\'main_html\'] = html_entity_decode($elemData[\'type\'][1][\'html\'][$this->config->get(\'config_language_id\')], ENT_QUOTES, \'UTF-8\');\r\n            }   \r\n      return $data;\r\n  }\r\n\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'telephone\'] = $this->config->get(\'config_telephone\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n // prostore\r\n    $data[\'yandex_metrika_counter\'] = false;\r\n    if ($this->config->get(\'analytics_yandex_metrika_counter\') && $this->config->get(\'analytics_yandex_metrika_status\')) {\r\n      $data[\'yandex_metrika_counter\'] = $this->config->get(\'analytics_yandex_metrika_counter\');\r\n    }\r\n    $data[\'dataLayer_isneed\'] = 1;\r\n    if($this->config->get(\'analytics_google_status\')){\r\n      // If Google Analytics is enabled - we don\'t need new dataLayer (already contained in Google Analytics)\r\n      $data[\'dataLayer_isneed\'] = 0;\r\n    }\r\n	$data[\'analytics_ya_status\'] = $this->config->get(\'theme_prostore_analytics_ya_status\');\r\n    $this->load->language(\'extension/theme/prostore\');\r\n    $data[\'text_manufacturers\'] = $this->language->get(\'text_manufacturers\');\r\n    $data[\'text_loader\'] = $this->language->get(\'text_loader\');\r\n    $data[\'text_ls_logged\'] = sprintf($this->language->get(\'text_ls_logged\'), $this->customer->getFirstName());\r\n    $data[\'text_register_account\'] = $this->language->get(\'text_register_account\');\r\n    $data[\'text_prostore_account\'] = $this->language->get(\'text_prostore_account\');\r\n    $data[\'text_prostore_email\'] = $this->language->get(\'text_prostore_email\');\r\n    $data[\'outdated_browser\'] = $this->language->get(\'outdated_browser\');\r\n    $data[\'text_search\'] = $this->language->get(\'text_search\');\r\n    $data[\'text_forgotten\'] = $this->language->get(\'text_forgotten\');\r\n    $data[\'text_prostore_maintenance_phone\'] = $this->language->get(\'text_prostore_maintenance_phone\');\r\n    $data[\'text_prostore_maintenance_email\'] = $this->language->get(\'text_prostore_maintenance_email\');\r\n	$data[\'product_detail\'] = $this->config->get(\'theme_prostore_product_detail\');\r\n	$data[\'image_main_rec_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_main_rec_width\');\r\n	$data[\'image_main_rec_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_main_rec_height\');\r\n	$data[\'image_manufacturer_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_width\');\r\n	$data[\'image_manufacturer_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_height\');\r\n	$data[\'image_header_banner_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_header_banner_width\');\r\n	$data[\'image_header_banner_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_header_banner_height\');\r\n	$data[\'config_open\'] = html_entity_decode($this->config->get(\'config_open\'), ENT_QUOTES, \'UTF-8\');\r\n	$this->load->model(\'setting/setting\');\r\n	$data[\'messenger_navs\'] = array();\r\n	$messenger_links = $this->model_setting_setting->getSetting(\'theme_prostoremeslinks\');\r\n	$data[\'messenger_links\'] = $messenger_links[\'theme_prostoremeslinks_array\'];\r\n	$data[\'messenger_navs\'] = $this->config->get(\'theme_prostore_messenger_nav\');	\r\n	$data[\'messenger_status\'] = $this->config->get(\'theme_prostore_messenger_status\');\r\n	$data[\'messenger_pos\'] = $this->config->get(\'theme_prostore_messenger_pos\');\r\n    $data[\'forgotten\'] = $this->url->link(\'account/forgotten\', \'\', true);\r\n    $data[\'header_type\'] = $this->config->get(\'theme_prostore_header_type\');\r\n    $data[\'footer_type\'] = $this->config->get(\'theme_prostore_footer_type\');\r\n    $data[\'js_footorhead\'] = $this->config->get(\'theme_prostore_js_footorhead\');\r\n    $data[\'open_graph\'] = $this->config->get(\'theme_prostore_og\');\r\n    $data[\'preloader\'] = $this->config->get(\'theme_prostore_preloader\');\r\n    $data[\'google_site_verification\'] = $this->config->get(\'theme_prostore_google_site_verification\');\r\n    $data[\'yandex_verification\'] = $this->config->get(\'theme_prostore_yandex_verification\');\r\n	$data[\'shop_email\'] = $this->config->get(\'config_email\');\r\n    $data[\'text_search_placeholder\'] = $this->config->get(\'text_search_placeholder\');\r\n    $data[\'prostore_phones\'] = array();\r\n    $data[\'prostore_phones_main\'] = array();\r\n    $prostore_phones = $this->config->get(\'theme_prostore_phones\');\r\n\r\n    $languages = $this->model_localisation_language->getLanguages();\r\n    if ($prostore_phones) {\r\n      foreach ($prostore_phones as $key => $prostore_phone) { \r\n        foreach ($languages as $language) {\r\n            $prostore_phone[$language[\'language_id\']] = html_entity_decode($prostore_phone[$language[\'language_id\']], ENT_QUOTES, \'UTF-8\');\r\n        }\r\n        $data[\'prostore_phones\'][$prostore_phone[\'sort\']] = $prostore_phone;\r\n      }\r\n      ksort($data[\'prostore_phones\']);\r\n      $data[\'prostore_phones_main\'] = current($data[\'prostore_phones\']);\r\n    }\r\n\r\n	$data[\'scroll_to_top\'] = $this->config->get(\'theme_prostore_scrolltt_status\');\r\n	$data[\'scroll_to_top_pos\'] = $this->config->get(\'theme_prostore_scrolltt_pos\');\r\n    $data[\'bootstrap\'] = $this->config->get(\'theme_prostore_bootstrap\');\r\n    $data[\'custom_css\'] = html_entity_decode($this->config->get(\'theme_prostore_css\'), ENT_QUOTES, \'UTF-8\');\r\n	\r\n	$data[\'theme_color\'] = $this->config->get(\'theme_prostore_color\');\r\n	$data[\'fixed_header\'] = $this->config->get(\'theme_prostore_fixed_header\');\r\n	$data[\'fonts\'] = $this->config->get(\'theme_prostore_fonts\');\r\n	$data[\'container_width\'] = $this->config->get(\'theme_prostore_container_width\');\r\n	$data[\'mobile_buttons\'] = $this->config->get(\'theme_prostore_mobile_buttons\');\r\n	$data[\'mobile_menu\'] = $this->config->get(\'theme_prostore_footer_mobile_menu\');\r\n	$data[\'mobile_menu_array\'] = $this->config->get(\'theme_prostore_footer_mobile_menu_array\');\r\n\r\n	if ($data[\'theme_color\']) {\r\n		if ($data[\'theme_color\'] == \'custom\') {\r\n			$data[\'theme_color_1\'] = $this->config->get(\'theme_prostore_custom_color_1\');\r\n			$data[\'theme_color_2\'] = $this->config->get(\'theme_prostore_custom_color_2\');\r\n		}else{\r\n			$colors = explode(\' \', $data[\'theme_color\']);\r\n			$data[\'theme_color_1\'] = $colors[0];\r\n			$data[\'theme_color_2\'] = $colors[1];\r\n		}\r\n	}\r\n	$data[\'theme_fc_color\'] = $this->config->get(\'theme_prostore_color_2\');\r\n    $data[\'theme_fc_color_1\'] = $this->config->get(\'theme_prostore_custom_fc_color_1\');\r\n    $data[\'theme_fc_color_2\'] = $this->config->get(\'theme_prostore_custom_fc_color_2\');\r\n\r\n    $data[\'custom_js\'] = html_entity_decode($this->config->get(\'theme_prostore_js\'), ENT_QUOTES, \'UTF-8\');\r\n    $data[\'fontawesome\'] = $this->config->get(\'theme_prostore_fontawesome\');\r\n    $data[\'bootstrap_ver\'] = $this->config->get(\'theme_prostore_bootstrap_ver\');\r\n    $data[\'type3_logo\'] = $this->config->get(\'theme_prostore_header_type3_logo\');\r\n    $data[\'type3_menu\'] = $this->config->get(\'theme_prostore_header_type3_menu\');\r\n    $data[\'header_text_logo\'] = html_entity_decode($this->config->get(\'theme_prostore_header_text_logo\'), ENT_QUOTES, \'UTF-8\');\r\n	$total = $this->cart->getTotal();\r\n	$data[\'text_items\'] = sprintf($this->language->get(\'text_prostore_shopping_cart\'), $this->cart->countProducts() + (isset($this->session->data[\'vouchers\']) ? count($this->session->data[\'vouchers\']) : 0), $this->currency->format($total, $this->session->data[\'currency\']));\r\n    $data[\'text_islogged\'] = sprintf($this->language->get(\'text_islogged\'), $this->url->link(\'account/login\', \'\', true), $this->url->link(\'account/register\', \'\', true), $this->url->link(\'account/wishlist\'));\r\n    $data[\'text_empty_wish\'] = $this->language->get(\'text_empty_wish\');\r\n    $data[\'text_prostore_wish_head\'] = $this->language->get(\'text_prostore_wish_head\');\r\n    $data[\'text_prostore_comp_head\'] = $this->language->get(\'text_prostore_comp_head\');\r\n    $data[\'text_empty_compare\'] = $this->language->get(\'text_empty_compare\');\r\n    $data[\'text_compare_href\'] = $this->url->link(\'product/compare\');\r\n    $data[\'text_wish_href\'] = $this->url->link(\'account/wishlist\');\r\n    $data[\'text_prostore_show_all\'] = $this->language->get(\'text_prostore_show_all\');\r\n    $data[\'text_header_category\'] = $this->language->get(\'text_header_category\');\r\n    $data[\'text_prostore_information\'] = $this->language->get(\'text_prostore_information\');\r\n    $data[\'text_prostore_menu\'] = $this->language->get(\'text_prostore_menu\');\r\n    $data[\'text_show_more\'] = $this->language->get(\'text_show_more\');\r\n    $data[\'text_prostore_back\'] = $this->language->get(\'text_prostore_back\');\r\n    $data[\'text_nav_more\'] = $this->language->get(\'text_nav_more\');\r\n    $data[\'text_account_title\'] = $this->language->get(\'text_account_title\');\r\n    $data[\'text_account_login\'] = $this->language->get(\'text_account_login\');\r\n    $data[\'text_account_register\'] = $this->language->get(\'text_account_register\');\r\n    $data[\'text_account_check\'] = $this->language->get(\'text_account_check\');\r\n    $data[\'text_account_submit\'] = $this->language->get(\'text_account_submit\');\r\n    $data[\'text_account_password\'] = $this->language->get(\'text_account_password\');\r\n    $data[\'text_header_callback\'] = $this->language->get(\'text_header_callback\');\r\n    $data[\'address\'] = nl2br($this->config->get(\'config_address\'));\r\n    $data[\'version\'] = $this->config->get(\'theme_prostore_version\');\r\n    $data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n\r\n    $data[\'top_links\'] = array();\r\n    if($this->config->get(\'theme_prostorelinks_array\')){\r\n      $data[\'top_links\'] = $this->config->get(\'theme_prostorelinks_array\');\r\n      $data[\'top_links\'] = $data[\'top_links\'][$this->config->get(\'config_language_id\')];\r\n    }\r\n   \r\n    $this->load->model(\'extension/module/prostore\');\r\n//    $catLinks = $this->model_extension_module_prostore->createCatLinks($this->config->get(\'config_language_id\'));\r\n//    $data[\'top_links\'] = array_merge ($data[\'top_links\'],$catLinks);\r\n\r\n    foreach($data[\'top_links\'] as $key => $link){\r\n      if(strpos($key,\'e\') === 0 ){ continue;}\r\n      $data[\'top_links\'][$key][key($link)] = $this->url->link(current($link));  \r\n    } \r\n\r\n    $data[\'header_navs\'] = array();\r\n    $header_navs = $this->config->get(\'theme_prostore_header_nav\');\r\n\r\n    //Основное меню\r\n    $data[\'main_navs\'] = array();\r\n    $main_navs = $this->config->get(\'theme_prostore_main_nav\');\r\n    $data[\'main_navs_v\'] = array();\r\n    $main_navs_v = $this->config->get(\'theme_prostore_main_nav_v\');\r\n\r\n        if (! function_exists(\'array_column\')) {  // To compatibility with PHP < 5.5 \r\n            function array_column(array $input, $columnKey, $indexKey = null) {\r\n                $array = array();\r\n                foreach ($input as $value) {\r\n                    if ( !array_key_exists($columnKey, $value)) {\r\n                        trigger_error(\"Key \\\"$columnKey\\\" does not exist in array\");\r\n                        return false;\r\n                    }\r\n                    if (is_null($indexKey)) {\r\n                        $array[] = $value[$columnKey];\r\n                    }\r\n                    else {\r\n                        if ( !array_key_exists($indexKey, $value)) {\r\n                            trigger_error(\"Key \\\"$indexKey\\\" does not exist in array\");\r\n                            return false;\r\n                        }\r\n                        if ( ! is_scalar($value[$indexKey])) {\r\n                            trigger_error(\"Key \\\"$indexKey\\\" does not contain scalar value\");\r\n                            return false;\r\n                        }\r\n                        $array[$value[$indexKey]] = $value[$columnKey];\r\n                    }\r\n                }\r\n                return $array;\r\n            }\r\n        }\r\n\r\n        $data[\'outdated_browser\'] = $this->language->get(\'outdated_browser\');\r\n        $data[\'text_search\'] = $this->language->get(\'text_search\');\r\n        $data[\'text_forgotten\'] = $this->language->get(\'text_forgotten\');\r\n        $data[\'forgotten\'] = $this->url->link(\'account/forgotten\', \'\', true);\r\n        $data[\'js_footorhead\'] = $this->config->get(\'theme_prostore_js_footorhead\');\r\n        $data[\'open_graph\'] = $this->config->get(\'theme_prostore_og\');\r\n\r\n    $navTypes = array(\r\n          \'0\' => \'main_navs\',     // FOR HORISONTAL MENU\r\n          \'1\' => \'main_navs_v\',  // FOR VERTICAL MENU\r\n          \'2\' => \'header_navs\'     // FOR HEADER MENU\r\n    );\r\n\r\n\r\n    foreach ($navTypes as $navType) {\r\n            if(isset($$navType)){\r\n                $data[$navType] = $this->cache->get(\'navview.navtypes.\'.$navType.\'.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\'));\r\n                if (!$this->config->get(\'developer_theme\')) {\r\n                  $data[$navType] = false;                     \r\n                }\r\n                if (!$data[$navType]) {\r\n                    $navsort  = array_column($$navType, \'sort\');\r\n                    array_multisort($navsort, SORT_ASC, $$navType);\r\n                    $data[$navType] = $$navType;\r\n\r\n                    foreach($data[$navType] as $key => $main_nav){  \r\n\r\n                            foreach($main_nav[\'type\'] as $key1 => $typeLink){  \r\n                                if (isset($main_nav[\'type\'][$key1][\'links\'])){\r\n                                    foreach($main_nav[\'type\'][$key1][\'links\'] as $key2 => $link){ \r\n                                        if(strpos($key2,\'e\') === 0 ){ // Extralinks do not change\r\n                                          if (isset($data[\'top_links\'][$key2])) {\r\n                                            $data[$navType][$key][\'type\'][$key1][\'links\'][$key2] = current($data[\'top_links\'][$key2]);\r\n                                          }else{\r\n                                            $data[$navType][$key][\'type\'][$key1][\'links\'][$key2] = \'\';\r\n                                          } \r\n                                          continue;\r\n                                        }\r\n                                        $data[$navType][$key][\'type\'][$key1][\'links\'][$key2] = $this->url->link($link); \r\n                                    }                       \r\n                                }\r\n                            }\r\n                    } \r\n                    $this->cache->set(\'navview.navtypes.\'.$navType.\'.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\'), $data[$navType]);\r\n\r\n                }      \r\n            }\r\n    }\r\n\r\n    //ПРАВЫЙ ЭЛЕМЕНТ ПОДМЕНЮ КАТЕГОРИИ\r\n\r\n    $data[\'manufacturerlinks\'] = $this->url->link(\'product/manufacturer\');\r\n\r\n    $this->load->language(\'product/compare\');\r\n    $data[\'compare_count\'] = isset($this->session->data[\'compare\']) ? count($this->session->data[\'compare\']) : 0;\r\n\r\n    if ($this->customer->isLogged() || $this->config->get(\'theme_prostore_wishlist\')) {\r\n		$this->load->model(\'account/wishlist\');\r\n		$data[\'wishlist_count\'] = $this->model_account_wishlist->getTotalWishlistLb();\r\n    } else {\r\n		$data[\'wishlist_count\'] = isset($this->session->data[\'wishlist\']) ? count($this->session->data[\'wishlist\']) : 0;\r\n	}\r\n	\r\n    if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_header_logo\'))) {\r\n      $data[\'header_logo\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_header_logo\');\r\n    } else {\r\n      $data[\'header_logo\'] = \'\';\r\n    }\r\n    if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_fav_16\'))) {\r\n      $data[\'fav_16\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_fav_16\');\r\n    } else {\r\n      $data[\'fav_16\'] = \'\';\r\n    }\r\n    if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_fav_32\'))) {\r\n      $data[\'fav_32\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_fav_32\');\r\n    } else {\r\n      $data[\'fav_32\'] = \'\';\r\n    }\r\n    if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_fav_180\'))) {\r\n      $data[\'fav_180\'] = $server . \'image/\' . $this->config->get(\'theme_prostore_fav_180\');\r\n    } else {\r\n      $data[\'fav_180\'] = \'\';\r\n    }\r\n    $data[\'callback_status\'] = $this->config->get(\'theme_prostore_callback_status\');\r\n    $data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n    \r\n    $data[\'max_subcat\'] = $this->config->get(\'theme_prostore_max_subcat\');\r\n    $data[\'max_subcat_v\'] = 4;\r\n    if ($this->config->get(\'theme_prostore_max_subcat_v\')) {\r\n        $data[\'max_subcat_v\'] = $this->config->get(\'theme_prostore_max_subcat_v\');\r\n    }\r\n\r\n    // Menu\r\n    $this->load->model(\'catalog/category\');\r\n\r\n    $this->load->model(\'catalog/product\');\r\n\r\n    $data[\'topcat\'] = array();\r\n\r\n    $data[\'categories\'] = array();\r\n\r\n    if ($this->config->get(\'developer_theme\')) {\r\n      $data[\'categories\'] = $this->cache->get(\'category.categoriesdata.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.0\') ?: [];\r\n	    $data[\'topcat\'] = $this->cache->get(\'category.categoriestopcat.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.0\') ?: [];\r\n    }\r\n\r\n  if (!$data[\'categories\']) {\r\n    $categoriesLs = array();\r\n    $categories = $this->model_catalog_category->getCategories(0);\r\n      \r\n  \r\n\r\n    foreach ($categories as $category) {//Level 1\r\n      if ($category[\'top\']) {\r\n        // Level 2\r\n        $children_data = array();\r\n\r\n        $children = $this->model_catalog_category->getCategories($category[\'category_id\']);\r\n        $L3_chid = false;// <--prostore add this\r\n        foreach ($children as $child) {  // Level 2       \r\n          $children2_data = array();\r\n          $children2 = $this->model_catalog_category->getCategories($child[\'category_id\']);\r\n          foreach ($children2 as $child2) {    // Level 3 \r\n//Level 4 start\r\n            $children3_data = array();\r\n            $children3 = $this->model_catalog_category->getCategories($child2[\'category_id\']);               \r\n              foreach ($children3 as $child3) { \r\n                $filter_data = array(\r\n                  \'filter_category_id\'  => $child3[\'category_id\'],\r\n                  \'filter_sub_category\' => true\r\n                );\r\n\r\n                $children3_data[$child3[\'category_id\']] = array(\r\n                  \'name\'  => $child3[\'name\'] . ($this->config->get(\'config_product_count\') ? \' (\' . $this->model_catalog_product->getTotalProducts($filter_data) . \')\' : \'\'),\r\n                  \'href\'  => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'] . \'_\' . $child2[\'category_id\'] . \'_\' . $child3[\'category_id\'])\r\n                );\r\n                $categoriesLs[$child3[\'category_id\']] = $children3_data[$child3[\'category_id\']];\r\n                $categoriesLs[$child3[\'category_id\']][\'childrencount\'] = 0;\r\n//                $categoriesLs[$child[\'category_id\']][\'have_L3\'] = false;\r\n              }\r\n//Level 4 end\r\n            $filter_data = array(\r\n              \'filter_category_id\'  => $child2[\'category_id\'],\r\n              \'filter_sub_category\' => true\r\n            );\r\n            // Level 3\r\n            $children2_data[$child2[\'category_id\']] = array(\r\n              \'name\'  => $child2[\'name\'] . ($this->config->get(\'config_product_count\') ? \' (\' . $this->model_catalog_product->getTotalProducts($filter_data) . \')\' : \'\'),\r\n              \'href\'  => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'] . \'_\' . $child2[\'category_id\']),\r\n              \'children\' => $children3_data\r\n            );\r\n            $categoriesLs[$child2[\'category_id\']] = $children2_data[$child2[\'category_id\']];\r\n            $categoriesLs[$child2[\'category_id\']][\'childrencount\'] = count($children3_data);\r\n            $categoriesLs[$child[\'category_id\']][\'have_L3\'] = false;\r\n          }         \r\n                  \r\n          $filter_data = array(\r\n            \'filter_category_id\'  => $child[\'category_id\'],\r\n            \'filter_sub_category\' => true\r\n          );\r\n          // Level 2\r\n          if($children2_data){$L3_chid = true;}// <--prostore add this\r\n          \r\n          $children_data[$child[\'category_id\']] = array(// <--prostore change this\r\n            \'name\'  => $child[\'name\'] . ($this->config->get(\'config_product_count\') ? \' (\' . $this->model_catalog_product->getTotalProducts($filter_data) . \')\' : \'\'),\r\n            \'href\'  => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\']),\r\n            \'children\' => $children2_data // <--prostore add this\r\n          );\r\n\r\n          $categoriesLs[$child[\'category_id\']] = $children_data[$child[\'category_id\']];\r\n          $categoriesLs[$child[\'category_id\']][\'childrencount\'] = count($children2_data);\r\n          $categoriesLs[$child[\'category_id\']][\'have_L3\'] = false;          \r\n        }\r\n\r\n        // Level 1\r\n        $data[\'categories\'][$category[\'category_id\']] = array(// <--prostore change this\r\n          \'name\'     => $category[\'name\'],\r\n          \'column\'     => $category[\'column\'],\r\n          \'children\' => $children_data,\r\n          \'have_L3\' => $L3_chid,// <--prostore add this\r\n          \'column\'   => $category[\'column\'] ? $category[\'column\'] : 1,\r\n          \'href\'     => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'])\r\n        );\r\n        $tid = \'c\'.$category[\'category_id\'];\r\n        $data[\'topcat\'][$tid] = $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\']);// <--prostore change this\r\n        $categoriesLs[$category[\'category_id\']] = $data[\'categories\'][$category[\'category_id\']];\r\n        $categoriesLs[$category[\'category_id\']][\'childrencount\'] = count($children_data);\r\n      }\r\n    }\r\n\r\n    $data[\'categories\'][\'categoriesls\'] = $categoriesLs;\r\n\r\n  $this->cache->set(\'category.categoriesdata.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.0\', $data[\'categories\']);\r\n  $this->cache->set(\'category.categoriestopcat.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.0\', $data[\'topcat\']);\r\n    }\r\n\r\n\r\n\r\n    $data[\'wish_head\'] = $this->load->view(\'common/header_wishlist\', $data);\r\n    $data[\'compare_head\'] = $this->load->view(\'common/header_compare\', $data); \r\n\r\n    if (isset($this->request->get[\'mobiheader\'])){\r\n/**\r\n * $this->request->get[\'mobiheader\'] = \'\' - вывод стандартного мобильного меню\r\n * $this->request->get[\'mobiheader\'] = \'_fix_menu\' - вывод только вертикального меню для фиксированного меню\r\n */\r\n\r\n      $data[\'mobiview\'] = $this->createNavMobiView($data,$this->request->get[\'mobiheader\']);\r\n    }else{\r\n     \r\n      $viewNav = $this->createNavView($data);\r\n\r\n      $data[\'main_navs\'] = $viewNav[\'main_navs\'];\r\n  \r\n      $data[\'main_navs_v\'] = $viewNav[\'main_navs_v\'];\r\n  \r\n      $data[\'header_navs\'] = $viewNav[\'header_navs\'];\r\n    }\r\n\r\n	$data[\'adult_banner\'] = \'\';\r\n	if ($this->config->get(\'theme_prostore_18_status\') && !isset($_COOKIE[\'899_is_adult\'])) { \r\n		$data[\'text_prostore_adult_warn\'] = $this->config->get(\'theme_prostore_text_18\'.$this->config->get(\'config_language_id\'));\r\n		$data[\'text_prostore_adult_yes\'] = $this->config->get(\'theme_prostore_btn2_18\'.$this->config->get(\'config_language_id\'));\r\n		$data[\'text_prostore_adult_no\'] = $this->config->get(\'theme_prostore_btn1_18\'.$this->config->get(\'config_language_id\'));\r\n		$data[\'text_prostore_adult_title\'] = $this->config->get(\'theme_prostore_title_18\'.$this->config->get(\'config_language_id\'));\r\n		$data[\'adult_banner\'] = $this->load->view(\'common/header_adult_banner\', $data);\r\n	}\r\n\r\n//prostore end  \r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'common/header\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n// prostore\r\n    $data[\'callback\'] = $this->load->controller(\'extension/module/callback\');  \r\n	\r\n	$data[\'header_checkout\'] = false;\r\n	if (isset($this->request->get[\'route\']) && $this->request->get[\'route\'] == \'checkout/checkout\') {\r\n		$data[\'header_view\'] = $this->load->view(\'common/header_checkout\', $data);\r\n		$data[\'header_checkout\'] = true;\r\n	} else {\r\n		$data[\'header_view\'] = $this->load->view(\'common/header_\' . $data[\'header_type\'], $data);\r\n	}\r\n	\r\n	$data[\'maintenance\'] = false;\r\n	if ($this->config->get(\'config_maintenance\')) {\r\n		$this->user = new Cart\\User($this->registry);\r\n		if (!$this->user->isLogged()) {\r\n			$data[\'header_view\'] = $this->load->view(\'common/header_maintenance\', $data);\r\n			$data[\'maintenance\'] = true;\r\n		}\r\n	}\r\n    if (isset($this->request->get[\'mobiheader\'])){\r\n      $this->response->setOutput($data[\'mobiview\']);\r\n    }else{\r\n      return $this->load->view(\'common/header\', $data);\r\n    }\r\n// prostore end \r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$host = isset($this->request->server[\'HTTPS\']) && (($this->request->server[\'HTTPS\'] == \'on\') || ($this->request->server[\'HTTPS\'] == \'1\')) ? HTTPS_SERVER : HTTP_SERVER;\r\n			]]></search>\r\n		<add position=\"replace\" offset=\"7\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->language(\'common/header\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// add Open Graph by ocStore\r\n$host = isset($this->request->server[\'HTTPS\']) && (($this->request->server[\'HTTPS\'] == \'on\') || ($this->request->server[\'HTTPS\'] == \'1\')) ? HTTPS_SERVER : HTTP_SERVER;\r\nif ($this->request->server[\'REQUEST_URI\'] == \'/\') {\r\n	$data[\'og_url\'] = $this->url->link(\'common/home\');\r\n} else {\r\n	$data[\'og_url\'] = $host . substr($this->request->server[\'REQUEST_URI\'], 1, (strlen($this->request->server[\'REQUEST_URI\'])-1));\r\n}\r\n$data[\'og_image\'] = $this->document->getOgImage();\r\n// add Open Graph by ocStore\r\n				]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/common/maintenance.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'message\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'text_prostore_maintenance_message1\'] = $this->language->get(\'text_prostore_maintenance_message1\');\r\n		$data[\'text_prostore_maintenance_message2\'] = $this->language->get(\'text_prostore_maintenance_message2\');\r\n		$data[\'text_prostore_con_soc2\'] = $this->language->get(\'text_prostore_con_soc2\');\r\n		\r\n		$this->load->model(\'setting/setting\');\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$data[\'social_navs\'] = array();\r\n		$social_links = $this->model_setting_setting->getSetting(\'theme_prostoresoclinks\');\r\n		$data[\'social_links\'] = $social_links[\'theme_prostoresoclinks_array\'];\r\n		$data[\'social_navs\'] = $this->config->get(\'theme_prostore_social_nav\');	\r\n	    // prostore end																									\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/{account,checkout,error,information}/{recurring,return,cart,not_found,information}.php|catalog/controller/product/*.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n		$this->response->setOutput($this->load->view(\'error/not_found\', $data));\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_logo_404\'))) {\r\n			$data[\'logo_404\'] = (isset($this->request->server[\'HTTPS\']) ? HTTPS_SERVER : HTTP_SERVER) . \'image/\' . $this->config->get(\'theme_prostore_logo_404\');\r\n		} else {\r\n			$data[\'logo_404\'] = \'\';\r\n		}\r\n		$data[\'text_404\'] = sprintf($this->language->get(\'text_404\'), $this->url->link(\'information/contact\', \'\', true), $this->url->link(\'product/search\', \'\', true), $this->url->link(\'common/home\', \'\', true));\r\n		$this->response->setOutput($this->load->view(\'error/404\', $data));\r\n// prostore end																										\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/captcha/{google,basic}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'route\'] = $this->request->get[\'route\']; \r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n//prostore\r\n		$data[\'route\'] = \'\';\r\n		if (isset($this->request->get[\'route\'])) {\r\n			$data[\'route\'] = $this->request->get[\'route\'];\r\n		}\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/feed/google_sitemap.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n			$output .= \'</urlset>\';\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			$this->load->model(\'extension/module/prostorenews\');\r\n			if($this->model_extension_module_prostorenews->isModuleSet()){\r\n					$filter_data = array(\r\n						\'start\'			  => 0,\r\n						\'limit\'			  => 100000\r\n					);\r\n\r\n				foreach ($this->model_extension_module_prostorenews->getNewss($filter_data) as $result) {\r\n					$output .= \'<url>\';\r\n					$output .= \'<loc>\' . $this->url->link(\'extension/module/prostore_news/getnews\', \'news_id=\' . $result[\'news_id\']) . \'</loc>\';\r\n					$output .= \'<changefreq>weekly</changefreq>\';\r\n					$output .= \'<priority>0.5</priority>\';\r\n					$output .= \'</url>\';\r\n				}\r\n			}\r\n\r\n		$this->load->model(\'extension/module/prostoreblog\');\r\n		$this->load->model(\'extension/module/prostorecatblog\');\r\n			if($this->model_extension_module_prostorecatblog->isModuleSet()){\r\n					$filter_data = array(\r\n						\'start\'			  => 0,\r\n						\'limit\'			  => 100000\r\n					);\r\n\r\n				foreach ($this->model_extension_module_prostoreblog->getBlogs($filter_data) as $result) {\r\n					$output .= \'<url>\';\r\n					$output .= \'<loc>\' . $this->url->link(\'extension/module/prostore_blog/getblog\', \'blog_id=\' . $result[\'blog_id\']) . \'</loc>\';\r\n					$output .= \'<changefreq>weekly</changefreq>\';\r\n					$output .= \'<priority>0.5</priority>\';\r\n					$output .= \'</url>\';\r\n				}\r\n			}\r\n			\r\n			$output .= $this->getCategoriesLb(0);\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function index()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n	protected function getCategoriesLb($parent_id, $current_path = \'\') {\r\n		$output = \'\';\r\n\r\n		$results = $this->model_extension_module_prostorecatblog->getBlogCategories($parent_id);\r\n\r\n		foreach ($results as $result) {\r\n			if (!$current_path) {\r\n				$new_path = $result[\'category_id\'];\r\n			} else {\r\n				$new_path = $current_path . \'_\' . $result[\'category_id\'];\r\n			}\r\n\r\n			$output .= \'<url>\';\r\n			$output .= \'<loc>\' . $this->url->link(\'extension/module/prostorecat_blog/getcat\', \'lbpath=\' . $new_path) . \'</loc>\';\r\n			$output .= \'<changefreq>weekly</changefreq>\';\r\n			$output .= \'<priority>0.7</priority>\';\r\n			$output .= \'</url>\';\r\n			\r\n					$filter_data = array(\r\n						\'filter_category_id\' => $result[\'category_id\'],\r\n						\'start\'			  => 0,\r\n						\'limit\'			  => 100000\r\n					);\r\n			$blogs = $this->model_extension_module_prostoreblog->getBlogs($filter_data);\r\n\r\n			foreach ($blogs as $blog) {\r\n				$output .= \'<url>\';\r\n				$output .= \'<loc>\' . $this->url->link(\'extension/module/prostore_blog/getblog\', \'blog_id=\' . $blog[\'blog_id\']) . \'</loc>\';\r\n				$output .= \'<changefreq>weekly</changefreq>\';\r\n				$output .= \'<priority>1.0</priority>\';\r\n				$output .= \'</url>\';\r\n			}\r\n\r\n			$output .= $this->getCategoriesLb($result[\'category_id\'], $new_path);\r\n		}\r\n\r\n		return $output;\r\n	}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/filter.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'catalog/category\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		$this->load->model(\'extension/module/prostore\');	// prostore			\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->language(\'extension/module/filter\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$data[\'text_prostore_filter\'] = $this->language->get(\'text_prostore_filter\');\r\n			$data[\'text_prostore_from\'] = $this->language->get(\'text_prostore_from\');\r\n			$data[\'text_prostore_to\'] = $this->language->get(\'text_prostore_to\');\r\n			$data[\'text_prostore_show\'] = $this->language->get(\'text_prostore_show\');\r\n			$data[\'text_prostore_reset\'] = $this->language->get(\'text_prostore_reset\');\r\n			$data[\'text_prostore_filter_price\'] = $this->language->get(\'text_prostore_filter_price\');\r\n			$dataFilter[\'category_id\'] = $category_id;\r\n			$data[\'priceLimits\'] = $this->model_extension_module_prostore->getPriceLimits($dataFilter);\r\n\r\n			if (isset($this->request->get[\'min_price\'])) {\r\n				$data[\'min_price\'] = (int)$this->request->get[\'min_price\'];\r\n			}else{\r\n				$data[\'min_price\'] = (int)$data[\'priceLimits\'][\'min_price\'];\r\n			}\r\n\r\n			if (isset($this->request->get[\'max_price\'])) {\r\n				$data[\'max_price\'] = round($this->request->get[\'max_price\'],2);\r\n			}else{\r\n				$data[\'max_price\'] = round($data[\'priceLimits\'][\'max_price\'],2); \r\n			}\r\n\r\n			$data[\'min_price_format\'] = $this->currency->format($data[\'min_price\'], $this->session->data[\'currency\'],1);\r\n			$data[\'max_price_format\'] = $this->currency->format($data[\'max_price\'], $this->session->data[\'currency\'],1);\r\n			$data[\'currencySymbol\'] = $this->currency->getSymbolRight($this->session->data[\'currency\']);\r\n			if ($this->currency->getSymbolLeft($this->session->data[\'currency\'])) {\r\n				$data[\'currencySymbol\'] = $this->currency->getSymbolLeft($this->session->data[\'currency\']);\r\n			}\r\n			$data[\'category_id\'] = $category_id;\r\n			$this->document->addScript(\'catalog/view/javascript/prostore/plugins/ion.rangeSlider.js\');\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'action\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n$url .= \'&filter=\'; // prostore add\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$childen_data[] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n						// prostore\r\n						$isactive = true;\r\n						$count = \'\';\r\n						if (isset($this->request->get[\'filter\']) && !empty($this->request->get[\'filter\'])) {\r\n							if (in_array($filter[\'filter_id\'], $data[\'filter_category\'])) {\r\n								$filter_data[\'filter_filter\'] = $this->request->get[\'filter\'];\r\n							}else {\r\n								$filter_data[\'filter_filter\'] .= \',\' . $this->request->get[\'filter\'];\r\n							}\r\n						}\r\n						\r\n						// Delete all other filter_ids which are in the same filter_group as $filter[\'filter_id\']\r\n						// For correct total count of products\r\n						$this->prostore->helper->correctFiltersForGroup($filter[\'filter_id\'], $filter_data[\'filter_filter\']);\r\n						$filter_data[\'min_price\'] = $data[\'min_price\'];\r\n						$filter_data[\'max_price\'] = $data[\'max_price\'];\r\n						$filter_data[\'filter_sub_category\'] = $this->config->get(\'theme_prostore_subcategory\');\r\n						$count = $this->model_catalog_product->getTotalProducts($filter_data);\r\n\r\n						if (!$count) {\r\n							$isactive = false;\r\n						}\r\n						// prostore end			\r\n	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$this->model_catalog_product->getTotalProducts($filter_data) . \')\' : \'\')]]></search>\r\n			<add position=\"replace\"><![CDATA[$count . \')\' : \'\'),\'isactive\'	=> $isactive // prostore]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/{latest,bestseller,special,featured,featured_product}.php|catalog/controller/account/wishlist.php\">\r\n		<operation error=\"skip\">\r\n			<search index=\"0\"><![CDATA[\r\n$data[\'products\'] = array();\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'lazyload\'] = $this->config->get(\'theme_prostore_lazyload\');\r\n		$data[\'mobile_view\'] = $this->config->get(\'theme_prostore_mobile_view\');\r\n		$data[\'cart_link\'] = $this->url->link(\'checkout/cart\');\r\n		$data[\'category_time\'] = $this->config->get(\'theme_prostore_category_time\');\r\n		$data[\'time_text_1\'] = $this->language->get(\'text_time_text_1\');\r\n		$data[\'time_text_2\'] = $this->language->get(\'text_time_text_2\');\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n		// labels\r\n			$this->load->model(\'extension/module/prostore\');\r\n\r\n			$data[\'labelsinfo\'] = $this->prostore->labels->getProductLabelsConfig();\r\n		// labels	\r\n		// prostore end												\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$data[\'products\'][] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n					// prostore\r\n					$cartProductInfo = $this->prostore->helper->getCartInfo4Product($product_info);\r\n					\r\n					$wishCompareData = $this->prostore->helper->getDataWishCompare($product_info[\'product_id\']);\r\n					\r\n					$extraImages = array();\r\n					if ($this->config->get(\'theme_prostore_images_status\')) {\r\n						$images = array_slice($this->model_catalog_product->getProductImages($product_info[\'product_id\']), 0, (int)$this->config->get(\'theme_prostore_images_array\'));\r\n						foreach($images as $imageX){\r\n							\r\n						$extraImages[] = $this->model_tool_image->resize($imageX[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'));\r\n            \r\n						}\r\n					}\r\n\r\n					$productLabels = $this->prostore->labels->getLabels4Product($product_info);\r\n\r\n					extract($productLabels);									\r\n					\r\n					if ($this->config->get(\'theme_prostore_manufacturer\') == 1) {\r\n						$manufacturer = $this->language->get(\'text_prostore_model\') . \' \' . $product_info[\'model\'];\r\n					} elseif ($this->config->get(\'theme_prostore_manufacturer\') == 2) {\r\n						$manufacturer =  $this->language->get(\'text_prostore_manufacturer\') . \' \' . $product_info[\'manufacturer\'];\r\n					} else {\r\n						$manufacturer = false;\r\n					}\r\n					\r\n					if ($product_info[\'quantity\'] <= 0) {\r\n						$stock = $product_info[\'stock_status\'];\r\n					} elseif ($this->config->get(\'config_stock_display\')) {\r\n						$stock = $this->language->get(\'text_instock\') . \': \' . $product_info[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\');\r\n					} else {\r\n						$stock = $this->language->get(\'text_instock\');\r\n					}	\r\n					\r\n					if ($product_info[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n						$buy_btn = $product_info[\'stock_status\'];\r\n					} else {\r\n						$buy_btn = \'\';\r\n					}\r\n				\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $special,\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n					// prostore\r\n					\'manufacturer\'     => $manufacturer,\r\n					\'quantity\'         => $product_info[\'quantity\'],\r\n					\'minimum\'          => $product_info[\'minimum\'] > 0 ? $product_info[\'minimum\'] : 1,\r\n					\'stock\'            => $stock,\r\n					\'images\'           => $extraImages,	\r\n					\'isnewest\'         => $isnewest,\r\n					\'sales\'       	   => $sales,\r\n					\'discount\'         => $discount,\r\n					\'catch\'       	   => $catch,\r\n					\'nocatch\'          => $nocatch,\r\n					\'popular\'	       => $popular,\r\n					\'hit\'	 	       => $hit,\r\n					\'isincart\'	       => $cartProductInfo[\'isincart\'],\r\n					\'to_cart_quantity\' => $cartProductInfo[\'to_cart_quantity\'],\r\n					\'buy_btn\'	       => $buy_btn,\r\n					\'reward\'           => $product_info[\'reward\'],\r\n					\'special_date_end\' => $special_date_end,\r\n					\'wish_compare_data\' => $wishCompareData,				\r\n					// prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/{latest,bestseller,special,featured,featured_product}.php|catalog/controller/account/wishlist.php|catalog/controller/product/{category,manufacturer,search,special,product}.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[(int)$result[\'rating\']]]></search>\r\n			<add position=\"replace\"><![CDATA[$result[\'rating\'] > 0 ? number_format($result[\'rating\'] , 1) : 0]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[round($result[\'rating\'], 1)]]></search>\r\n			<add position=\"replace\"><![CDATA[$result[\'rating\'] > 0 ? number_format($result[\'rating\'] , 1) : 0]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[(int)$product_info[\'rating\']]]></search>\r\n			<add position=\"replace\"><![CDATA[$product_info[\'rating\'] > 0 ? number_format($product_info[\'rating\'] , 1) : 0]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[round($product_info[\'rating\'], 1)]]></search>\r\n			<add position=\"replace\"><![CDATA[$product_info[\'rating\'] > 0 ? number_format($product_info[\'rating\'] , 1) : 0]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/bestseller.php\">\r\n		<operation>\r\n			<search><![CDATA[product_info]]></search>\r\n			<add position=\"replace\"><![CDATA[result]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/bestseller\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/bestseller_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/bestseller\', $data);\r\n			}\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/special.php\">\r\n		<operation>\r\n			<search><![CDATA[product_info]]></search>\r\n			<add position=\"replace\"><![CDATA[result]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/special\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/special_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/special\', $data);\r\n			}\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/latest.php\">\r\n		<operation>\r\n			<search><![CDATA[product_info]]></search>\r\n			<add position=\"replace\"><![CDATA[result]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/latest\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/latest_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/latest\', $data);\r\n			}\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/account.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nload->view\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore	\r\n		$this->load->language(\'account/account\');\r\n		\r\n		$this->load->language(\'extension/theme/prostore\');\r\n\r\n		$data[\'account_name\'] = $this->customer->getFirstName() . \' \' . $this->customer->getLastName();\r\n		\r\n		if ($this->config->get(\'total_reward_status\')) {\r\n			$data[\'reward\'] = $this->url->link(\'account/reward\', \'\', true);\r\n		} else {\r\n			$data[\'reward\'] = \'\';\r\n		}\r\n		$data[\'total_reward\'] = (int)$this->customer->getRewardPoints();\r\n\r\n		$data[\'credit_cards\'] = array();\r\n		\r\n		$files = glob(DIR_APPLICATION . \'controller/extension/credit_card/*.php\');\r\n		\r\n		foreach ($files as $file) {\r\n			$code = basename($file, \'.php\');\r\n			\r\n			if ($this->config->get(\'payment_\' . $code . \'_status\') && $this->config->get(\'payment_\' . $code . \'_card\')) {\r\n				$this->load->language(\'extension/credit_card/\' . $code, \'extension\');\r\n\r\n				$data[\'credit_cards\'][] = array(\r\n					\'name\' => $this->language->get(\'extension\')->get(\'heading_title\'),\r\n					\'href\' => $this->url->link(\'extension/credit_card/\' . $code, \'\', true)\r\n				);\r\n			}\r\n		}\r\n		\r\n		$this->load->model(\'account/customer\');\r\n		\r\n		$affiliate_info = $this->model_account_customer->getAffiliate($this->customer->getId());\r\n		\r\n		if (!$affiliate_info) {	\r\n			$data[\'affiliate\'] = $this->url->link(\'account/affiliate/add\', \'\', true);\r\n		} else {\r\n			$data[\'affiliate\'] = $this->url->link(\'account/affiliate/edit\', \'\', true);\r\n		}\r\n		\r\n		if ($affiliate_info) {		\r\n			$data[\'tracking\'] = $this->url->link(\'account/tracking\', \'\', true);\r\n		} else {\r\n			$data[\'tracking\'] = \'\';\r\n		}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/{banner,carousel,slideshow}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->document->addStyle(\'catalog/view/javascript/jquery/swiper/css/swiper.min.css\');\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"3\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'width\'] = $setting[\'width\'];\r\n		$data[\'height\'] = $setting[\'height\'];\r\n		// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$result[\'title\']]]></search>\r\n			<add position=\"replace\"><![CDATA[html_entity_decode($result[\'title\'], ENT_QUOTES, \'UTF-8\')]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/category.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->language(\'extension/module/category\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/account/wishlist.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][]\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n				if ($this->config->get(\'config_review_status\')) {\r\n					$rating = $product_info[\'rating\'] > 0 ? number_format($product_info[\'rating\'], 1) : 0;\r\n				} else {\r\n					$rating = false;\r\n				}\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$special,\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n\'rating\'      => $rating,// prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/featured.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/featured\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/featured_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/featured\', $data);\r\n			}\r\n					// prostore end\r\n\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/featured_product.php\">\r\n		<operation>\r\n			<search><![CDATA[product_info]]></search>\r\n			<add position=\"replace\"><![CDATA[product]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/featured_product\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/featured_product_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/featured_product\', $data);\r\n			}\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/blog_featured.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/blog_featured\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/blog_featured_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/blog_featured\', $data);\r\n			}\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/blog_latest.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/blog_latest\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/blog_latest_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/blog_latest\', $data);\r\n			}\r\n					// prostore end\r\n\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/module/featured_article.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nreturn $this->load->view(\'extension/module/featured_article\', $data);\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n					// prostore\r\n			if(isset($setting[\'layout\']) && strpos($setting[\'layout\'],\'column_\') !== false){\r\n				return $this->load->view(\'extension/module/featured_article_column\', $data);\r\n			}else{\r\n				return $this->load->view(\'extension/module/featured_article\', $data);\r\n			}\r\n					// prostore end\r\n\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/total/{coupon,shipping,voucher}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			$this->load->language(\'extension/theme/prostore\');\r\n// prostore end		\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/total/reward.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$data[\'text_prostore_reward\'] = $this->language->get(\'text_prostore_reward\');\r\n			$data[\'points_total\'] = sprintf($this->language->get(\'text_prostore_reward_total\'), $points - (int)$data[\'reward\']);\r\n// prostore end	\r\n	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/total/shipping.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nreturn $this->load->view\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			if (isset($this->session->data[\'shipping_address\'][\'city\'])) {\r\n				$data[\'city\'] = $this->session->data[\'shipping_address\'][\'city\'];\r\n			} else {\r\n				$data[\'city\'] = \'\';\r\n			}	\r\n// prostore end		\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npost[\'zone_id\'],\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n\'city\'           => $this->request->post[\'city\'],// Prostore added this	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/information/contact.php\">\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$this->document->setTitle($this->language->get(\'heading_title\'));\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n		// prostore\r\n		\r\n		if ($this->config->get(\'theme_prostore_contact_meta_title\' . $this->config->get(\'config_language_id\'))) {\r\n			$this->document->setTitle($this->config->get(\'theme_prostore_contact_meta_title\' . $this->config->get(\'config_language_id\')));\r\n		} else {\r\n			$this->document->setTitle($this->language->get(\'heading_title\'));\r\n		}\r\n		\r\n		if ($this->config->get(\'theme_prostore_contact_meta_description\' . $this->config->get(\'config_language_id\'))) {\r\n			$this->document->setDescription($this->config->get(\'theme_prostore_contact_meta_description\' . $this->config->get(\'config_language_id\')));\r\n		}\r\n		\r\n		if ($this->config->get(\'theme_prostore_contact_meta_keyword\' . $this->config->get(\'config_language_id\'))) {\r\n			$this->document->setKeywords($this->config->get(\'theme_prostore_contact_meta_keyword\' . $this->config->get(\'config_language_id\')));\r\n		}\r\n		\r\n		// prostore end\r\n\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nisset($this->error[\'name\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		$data[\'shop_email\'] = $this->config->get(\'config_email\');\r\n		$data[\'text_prostore_support\'] = $this->language->get(\'text_prostore_support\');\r\n		$data[\'text_prostore_con_soc\'] = $this->language->get(\'text_prostore_con_soc\');\r\n		$data[\'prostore_phones\'] = array();\r\n		$data[\'prostore_phones_main\'] = array();\r\n		$prostore_phones = $this->config->get(\'theme_prostore_phones\');\r\n		if ($prostore_phones) {\r\n			foreach ($prostore_phones as $key => $prostore_phone) {\r\n				$data[\'prostore_phones\'][$prostore_phone[\'sort\']] = $prostore_phone;\r\n			}\r\n			ksort($data[\'prostore_phones\']);\r\n			$data[\'prostore_phones_main\'] = current($data[\'prostore_phones\']);\r\n		}\r\n\r\n		$data[\'our_details\'] = array();\r\n		$our_details = $this->config->get(\'theme_prostore_our_details\');\r\n		if ($our_details) {\r\n			$detailSort  = array_column($our_details, \'sort\');\r\n			array_multisort($detailSort, SORT_ASC, $our_details);\r\n			$data[\'our_details\'] = $our_details;\r\n		}\r\n\r\n		$this->load->model(\'setting/setting\');\r\n		$data[\'social_navs\'] = array();\r\n		$social_links = $this->model_setting_setting->getSetting(\'theme_prostoresoclinks\');\r\n		$data[\'social_links\'] = $social_links[\'theme_prostoresoclinks_array\'];\r\n		$data[\'social_navs\'] = $this->config->get(\'theme_prostore_social_nav\');	\r\n		$data[\'zoom\'] = $this->config->get(\'theme_prostore_contact_zoom\');\r\n		$data[\'zoom_control\'] = $this->config->get(\'theme_prostore_contact_zoom_control\');\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_contact_map_icon\'))) {\r\n			$data[\'contact_map_icon\'] = (isset($this->request->server[\'HTTPS\']) ? HTTPS_SERVER : HTTP_SERVER) . \'image/\' . $this->config->get(\'theme_prostore_contact_map_icon\');\r\n		} else {\r\n			$data[\'contact_map_icon\'] = \'\';\r\n		}\r\n		$data[\'api_key\'] = $this->config->get(\'theme_prostore_contact_api_key\');\r\n		$data[\'contact_map\'] = $this->config->get(\'theme_prostore_contact_map\');\r\n		if ($this->config->get(\'theme_prostore_contact_pdata\')) {\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$this->load->model(\'catalog/information\');\r\n\r\n			$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_contact_pdata\'));\r\n\r\n			if ($information_info) {\r\n				$data[\'text_prostore_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_prostore_sendbutton\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_contact_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n			} else {\r\n				$data[\'text_prostore_pdata\'] = \'\';\r\n			}\r\n		} else {\r\n			$data[\'text_prostore_pdata\'] = \'\';\r\n		}\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n		$data[\'address_schema\'] = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\", \"\\\"\"),\' \', strip_tags(html_entity_decode($this->config->get(\'config_address\'), ENT_QUOTES, \'UTF-8\')));\r\n		$data[\'open_html\'] = html_entity_decode($this->config->get(\'config_open\'), ENT_QUOTES, \'UTF-8\');\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'locations\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$data[\'geocodeY\']  = $data[\'geocode\'];\r\n		if ($data[\'contact_map\'] == \'yandex_map\' && $data[\'geocode\']) {\r\n			$tempcode = explode(\',\', $data[\'geocode\']);\r\n			if (isset($tempcode[1])) {\r\n				$data[\'geocodeY\'] = $tempcode[1] . \',\' . $tempcode[0]; \r\n			}\r\n		}\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'locations\'][]\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n					if ($data[\'contact_map\'] == \'yandex_map\' && $location_info[\'geocode\']) {\r\n						$tempcode = explode(\',\', $location_info[\'geocode\']);\r\n						if (isset($tempcode[1])) {\r\n							$location_info[\'geocode\'] = $tempcode[1] . \',\' . $tempcode[0]; \r\n						}\r\n					}\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$location_info[\'comment\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n\'open_html\'        => html_entity_decode($location_info[\'open\']), // prostore add\r\n\'address_schema\'     => str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\", \"\\\"\"),\' \', strip_tags(html_entity_decode($location_info[\'address\'], ENT_QUOTES, \'UTF-8\'))), // prostore add\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/information/information.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'breadcrumbs\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/information/sitemap.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'categories\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		$data[\'text_prostore_news\'] = $this->language->get(\'text_prostore_news\');\r\n		$data[\'text_prostore_blogs\'] = $this->language->get(\'text_prostore_blogs\');\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'column_left\'] = $this->load->controller(\'common/column_left\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->model(\'extension/module/prostorenews\');\r\n		$data[\'newss\'] = array();\r\n		if($this->model_extension_module_prostorenews->isModuleSet()){\r\n				$filter_data = array(\r\n					\'start\'			  => 0,\r\n					\'limit\'			  => 100000\r\n				);\r\n\r\n			foreach ($this->model_extension_module_prostorenews->getNewss($filter_data) as $result) {\r\n				$data[\'newss\'][] = array(\r\n					\'title\' => $result[\'title\'],\r\n					\'href\'  => $this->url->link(\'extension/module/prostore_news/getnews\', \'news_id=\' . $result[\'news_id\'])\r\n				);\r\n			}\r\n		}\r\n\r\n		$this->load->model(\'extension/module/prostoreblog\');\r\n		$this->load->model(\'extension/module/prostorecatblog\');\r\n		if($this->model_extension_module_prostorecatblog->isModuleSet()){\r\n			$data[\'blogcategories\'] = array();\r\n			$data[\'blogcategories\'] = $this->getCategoriesLb(0);\r\n		}			\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function index\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n	protected function getCategoriesLb($parent_id, $current_path = \'\') {\r\n		$info = array();\r\n\r\n		$results = $this->model_extension_module_prostorecatblog->getBlogCategories($parent_id);\r\n\r\n		foreach ($results as $result) {\r\n			if (!$current_path) {\r\n				$new_path = $result[\'category_id\'];\r\n			} else {\r\n				$new_path = $current_path . \'_\' . $result[\'category_id\'];\r\n			}\r\n\r\n					$SubBlogs = array();\r\n					$filter_data = array(\r\n						\'filter_category_id\' => $result[\'category_id\'],\r\n						\'start\'			  => 0,\r\n						\'limit\'			  => 100000\r\n					);\r\n			$blogs = $this->model_extension_module_prostoreblog->getBlogs($filter_data);\r\n\r\n			foreach ($blogs as $blog) {\r\n				$SubBlogs[] = array(\r\n					\'title\' => $blog[\'title\'],\r\n					\'href\'  => $this->url->link(\'extension/module/prostore_blog/getblog\', \'blog_id=\' . $blog[\'blog_id\'])\r\n				);\r\n			}\r\n\r\n\r\n				$info[] = array(\r\n					\'name\' => $result[\'name\'],\r\n					\'href\'  => $this->url->link(\'extension/module/prostorecat_blog/getcat\', \'lbpath=\' . $new_path),\r\n					\'subblogs\' => $SubBlogs\r\n				);\r\n			\r\n\r\n			$this->getCategoriesLb($result[\'category_id\'], $new_path);\r\n		}\r\n\r\n		return $info;\r\n	}\r\n		// prostore end	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/mail/order.php\">\r\n		<operation error=\"skip\">\r\n		<search index=\"2\"><![CDATA[$mail = new Mail]]></search>\r\n			<add position=\"replace\"><![CDATA[$mail  = new Mail]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/mail/{affiliate,forgotten,order,register,transaction}.php|catalog/controller/extension/total/voucher.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$mail = new Mail\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		//prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		if ($this->config->get(\'config_store_id\')) {\r\n			$store_url = $this->config->get(\'config_url\');\r\n		} else {\r\n			if ($this->request->server[\'HTTPS\']) {\r\n				$store_url = HTTPS_SERVER;\r\n			} else {\r\n				$store_url = HTTP_SERVER;\r\n			}\r\n		}\r\n		$data[\'text_prostore_mail\'] = $language->get(\'text_prostore_mail\');\r\n		$data[\'text_prostore_mail_title\'] = $language->get(\'text_prostore_mail_title\');\r\n		$data[\'text_prostore_mail_customer\'] = $language->get(\'text_prostore_mail_customer\');\r\n		$data[\'text_prostore_mail_footer\'] = $language->get(\'text_prostore_mail_footer\');\r\n		$data[\'text_prostore_support\'] = $language->get(\'text_prostore_support\');\r\n		if (is_file(DIR_IMAGE . $this->config->get(\'theme_prostore_mail_logo\'))) {\r\n			$data[\'logo\'] = $store_url . \'image/\' . $this->config->get(\'theme_prostore_mail_logo\');\r\n		} else {\r\n			$data[\'logo\'] = \'\';\r\n		}\r\n		$data[\'header_text_logo\'] = html_entity_decode($this->config->get(\'theme_prostore_header_text_logo\'), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'prostore_mail_text\'] = html_entity_decode($this->config->get(\'theme_prostore_mail_text\' . $this->config->get(\'config_language_id\')), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'prostore_mail_about\'] = html_entity_decode($this->config->get(\'theme_prostore_mail_about\' . $this->config->get(\'config_language_id\')), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'theme_color\'] = $this->config->get(\'theme_prostore_color\');\r\n		if ($this->config->get(\'theme_prostore_color\')) {\r\n			if ($this->config->get(\'theme_prostore_color\') == \'custom\') {\r\n				$data[\'theme_color\'] = $this->config->get(\'theme_prostore_custom_color_1\');\r\n				//$data[\'theme_color_2\'] = $this->config->get(\'theme_prostore_custom_color_2\');\r\n				//$data[\'theme_color_3\'] = $this->config->get(\'theme_prostore_custom_color_3\');\r\n			}else{\r\n				$colors = explode(\' \', $this->config->get(\'theme_prostore_color\'));\r\n				$data[\'theme_color\'] = $colors[0];\r\n				//$data[\'theme_color_2\'] = $colors[1];\r\n				//$data[\'theme_color_3\'] = $colors[2];\r\n			}\r\n		}\r\n\r\n		$data[\'theme_prostore_checkout_st3\'] = $this->config->get(\'theme_prostore_checkout_st3_sa\');\r\n		\r\n		$data[\'prostore_phones\'] = array();\r\n		$data[\'prostore_phones_main\'] = array();\r\n		$prostore_phones = $this->config->get(\'theme_prostore_phones\');\r\n\r\n		if ($prostore_phones) {\r\n		  foreach ($prostore_phones as $key => $prostore_phone) {\r\n			$data[\'prostore_phones\'][$prostore_phone[\'sort\']] = $prostore_phone;\r\n		  }\r\n		  ksort($data[\'prostore_phones\']);\r\n		  $data[\'prostore_phones_main\'] = current($data[\'prostore_phones\']);\r\n		}\r\n		\r\n		$data[\'config_email\'] =  $this->config->get(\'config_email\');\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n		$data[\'store_name\'] = $this->config->get(\'config_name\');\r\n		$data[\'store_url\'] = $store_url;\r\n		//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[setText($this->load->view(\'mail/affiliate\']]></search>\r\n			<add position=\"replace\"><![CDATA[setHtml($this->load->view(\'mail/affiliate\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[setText($this->load->view(\'mail/forgotten\']]></search>\r\n			<add position=\"replace\"><![CDATA[setHtml($this->load->view(\'mail/forgotten\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[setText($this->load->view(\'mail/register\']]></search>\r\n			<add position=\"replace\"><![CDATA[setHtml($this->load->view(\'mail/register\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[setText($this->load->view(\'mail/transaction\']]></search>\r\n			<add position=\"replace\"><![CDATA[setHtml($this->load->view(\'mail/transaction\']]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[setText($this->load->view(\'mail/order_edit\']]></search>\r\n			<add position=\"replace\"><![CDATA[setHtml($this->load->view(\'mail/order_edit\']]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/mail/{affiliate,forgotten,register,transaction}.php\">\r\n		<operation>\r\n			<search><![CDATA[$language->get]]></search>\r\n			<add position=\"replace\"><![CDATA[$this->language->get]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/extension/total/voucher.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->config->get(\'config_store_id\')) {\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"8\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$store_url]]></search>\r\n			<add position=\"replace\"><![CDATA[$order_info[\'store_url\']]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$data[\'store_name\'] = $this->config->get(\'config_name\');]]></search>\r\n			<add position=\"replace\"><![CDATA[$data[\'store_name\'] = $order_info[\'store_name\'];]]></add>\r\n		</operation>\r\n		<operation>\r\n		<search index=\"1\"><![CDATA[$this->load->language(\'extension/theme/prostore\');]]></search>\r\n			<add position=\"replace\"><![CDATA[$language->load(\'extension/theme/prostore\');]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/mail/order.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nif ($this->config->get(\'config_store_id\')) {\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"8\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$data[\'text_footer\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n$data[\'text_comment\'] = $language->get(\'text_comment\');\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nif ($order_info[\'payment_address_format\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n		if ($order_info[\'comment\']) {\r\n			$data[\'customer_comment\'] = strip_tags($order_info[\'comment\']);\r\n		}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$store_url]]></search>\r\n			<add position=\"replace\"><![CDATA[$order_info[\'store_url\']]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$data[\'store_name\'] = $this->config->get(\'config_name\');]]></search>\r\n			<add position=\"replace\"><![CDATA[$data[\'store_name\'] = $order_info[\'store_name\'];]]></add>\r\n		</operation>\r\n		<operation>\r\n		<search index=\"0,1\"><![CDATA[$this->load->language(\'extension/theme/prostore\');]]></search>\r\n			<add position=\"replace\"><![CDATA[$language->load(\'extension/theme/prostore\');]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$option_data = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n					$query_product_info = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"product WHERE product_id = \'\" . (int)$order_product[\'product_id\'] . \"\'\");	\r\n					$product_info = $query_product_info->row;\r\n\r\n					if ($product_info[\'image\']) {\r\n						$image = $this->model_tool_image->resize($product_info[\'image\'],  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n					} else {\r\n						$image = $this->model_tool_image->resize(\'placeholder.png\',  $this->config->get(\'theme_prostore_image_cart_width\'), $this->config->get(\'theme_prostore_image_cart_height\'));\r\n					}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			$this->load->model(\'tool/image\');\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $option_data,\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'image\'	=> $image,// prostore\r\n				\'href\'	 => $this->url->link(\'product/product\', \'product_id=\' . $order_product[\'product_id\']),// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$mail->setTo($order_info[\'email\']);\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				//prostore start\r\n				if(!$order_info[\'email\']){\r\n					$mail->setTo(\'nomailprostores@nomail.ru\');\r\n				}\r\n				//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n($order_info[\'customer_id\'])\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				//prostore start\r\n$data[\'status_icon\'] = \'img-mail-status.png\';\r\nif (\r\n	!in_array($order_status_id, $this->config->get(\'config_processing_status\')) &&\r\n	!in_array($order_status_id, $this->config->get(\'config_complete_status\'))  \r\n) {\r\n	$data[\'status_icon\'] = \'img-page-not-found.png\';\r\n}\r\n				//prostore stop\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/category.php\">\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$this->load->model(\'tool/image\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n//prostore start\r\n		$this->load->model(\'setting/setting\');\r\n		$this->load->language(\'extension/theme/prostore\');\r\n\r\n		if (isset($this->session->data[\'change_currency\'])) {\r\n			unset($this->session->data[\'change_currency\']);\r\n			unset($this->request->get[\'min_price\']);\r\n			unset($this->request->get[\'max_price\']);\r\n		}\r\n\r\n		if (isset($this->request->get[\'min_price\'])) {\r\n			$min_price = $this->request->get[\'min_price\'];\r\n		} else {\r\n			$min_price = \'\';\r\n		}\r\n\r\n		if (isset($this->request->get[\'max_price\'])) {\r\n			$max_price = $this->request->get[\'max_price\'];\r\n		} else {\r\n			$max_price = \'\';\r\n		}\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$path = \'\';\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n			if (isset($this->request->get[\'min_price\'])) {\r\n				$url .= \'&min_price=\' . $this->request->get[\'min_price\'];\r\n			} \r\n\r\n			if (isset($this->request->get[\'max_price\'])) {\r\n				$url .= \'&max_price=\' . $this->request->get[\'max_price\'];\r\n			} \r\n			$cat_url = \'\';\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1,3\"><![CDATA[\r\n$url .= \'&limit=\' . $this->request->get[\'limit\'];\r\n			]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[\r\n//prostore start\r\n			if (isset($this->request->get[\'min_price\'])) {\r\n				$url .= \'&min_price=\' . $this->request->get[\'min_price\'];\r\n			} \r\n\r\n			if (isset($this->request->get[\'max_price\'])) {\r\n				$url .= \'&max_price=\' . $this->request->get[\'max_price\'];\r\n			} \r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nnew Pagination\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n			if ($product_total) {\r\n				$data[\'product_num\'] = $product_total .\' \'. $this->prostore->helper->correctForm(array($product_total,\'product\'));\r\n			} else {\r\n				$data[\'product_num\'] = false;\r\n			}\r\n\r\n			$data[\'nextPageUrl\'] = \'\';\r\n			$num_pages = ceil($product_total / $limit);\r\n			if ($page < $num_pages) {\r\n				$data[\'nextPageUrl\'] = $this->url->link(\'product/category\', \'path=\' . $this->request->get[\'path\'] . $url . \'&page=\'.($page+1) );\r\n			}\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$category_id = (int)array_pop($parts);\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n$id = 0;//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n\'text\' => $category_info[\'name\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n						\'breadList\' => $this->breadList($id),// prostore\r\n						\'cat_id\' => $id,// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n\'href\' => $this->url->link(\'product/category\', \'path=\' . $path . $url)\r\n			]]></search>\r\n			<add position=\"after\" offset=\"2\"><![CDATA[\r\n$id = $path_id;// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'href\' => $this->url->link(\'product/category\', \'path=\' . $path . $url)\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n\'href\' => $this->url->link(\'product/category\', \'path=\' . $path ) // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search ><![CDATA[\r\n$category_id = 0;\r\n			]]></search>\r\n			<add position=\"before\" offset=\"1\"><![CDATA[\r\n//prostore start\r\n			$cat_url = $this->url->link(\'product/category\', \'path=\' . $path . \'_\' . $category_id);\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'categories\'][] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n				if(!$this->config->get(\'theme_prostore_subcategory\')){\r\n					unset($filter_data[\'filter_sub_category\']);\r\n				}\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'description\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n$data[\'schema_description\'] = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\", \"\\\"\"),\' \', strip_tags(html_entity_decode($category_info[\'description\'], ENT_QUOTES, \'UTF-8\'))); \r\n$data[\'image_category_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_category_width\');\r\n$data[\'image_category_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_category_height\');\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'name\' => $result[\'name\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					// prostore\r\n					\'thumb\' => $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_category_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_category_height\')),\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search index=\"0\"><![CDATA[\'_\' . $result[\'category_id\'] . $url]]></search>\r\n			<add position=\"replace\"><![CDATA[\'_\' . $result[\'category_id\']]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'filter_category_id\' => $category_id,\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'min_price\'			 => $min_price,//prostore\r\n				\'max_price\'			 => $max_price,//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $limit\r\n			]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[\r\n//prostore start\r\n			$this->load->model(\'extension/module/prostore\');\r\n\r\n			if($this->config->get(\'theme_prostore_subcategory\')){\r\n				$filter_data[\'filter_sub_category\'] = true;\r\n			}\r\n				if (count($results) == 1) {\r\n					$colmd = 8; \r\n				}elseif ($this->config->get(\'theme_prostore_category_categories\') == 4) {\r\n					$colmd = 4;\r\n				}else{\r\n					$colmd = 6;\r\n				}\r\n				$data[\'colmd\'] = $colmd;\r\n\r\n			if ($this->config->get(\'config_tax\')) {\r\n				$tax_data = $this->model_extension_module_prostore->gettax_class_id($filter_data);\r\n				if (isset($tax_data[\'tax_class_id\'])) {\r\n					$filter_data[\'filter_tax_class_id\'] = $tax_data[\'tax_class_id\'];\r\n				}\r\n			}\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$results = $this->model_catalog_product->getProducts($filter_data);\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			// prostore\r\n			$currR = $this->currency->getSymbolRight($this->session->data[\'currency\']);\r\n			$currL = $this->currency->getSymbolLeft($this->session->data[\'currency\']);\r\n\r\n			if($currR){\r\n				$data[\'currencydata\'] = \"R_\" . $currR ;\r\n			}else{\r\n				$data[\'currencydata\'] = \"L_\" . $currL ;\r\n			}\r\n		\r\n			$data[\'url\'] = $url;\r\n			if (isset($this->request->get[\'page\'])) {\r\n				$data[\'url\'] .= \'&page=\' . $this->request->get[\'page\'];\r\n			}\r\n			$data[\'path\'] = $this->request->get[\'path\'];\r\n			$data[\'category_id\'] = $category_id;\r\n			$data[\'cat_url\'] = $cat_url;\r\n			$data[\'product_total\'] = $product_total;\r\n			$data[\'currency\'] = $this->session->data[\'currency\'];\r\n			// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function index()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n	public function breadList($category_id) {\r\n		$this->load->model(\'catalog/category\');\r\n		$data = array();\r\n		$categories = $this->model_catalog_category->getCategories($category_id);\r\n		foreach($categories as $category){\r\n			$data[] = array(\r\n				\'name\'		=> $category[\'name\'],\r\n				\'href\'       => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'])\r\n			);\r\n		}\r\n		return $data;\r\n	}\r\n\r\n	public function doOptionColumns($options){\r\n		$optionColumns = array();\r\n		$column = $this->config->get(\'theme_prostore_product_opt_select\');\r\n		if (!$column) {\r\n			$column = 2;\r\n		}\r\n\r\n		$qtyPerColumn = (int)(count($options)/$column);\r\n        $i = 0;\r\n        $k = 0;\r\n \r\n		foreach ($options as $key => $option) {\r\n			$optionColumns[$k][$i] = $option;\r\n	        $i++;\r\n	        if ($i == $column) {  \r\n	            $i = 0;\r\n	            $k++;\r\n	        }    				\r\n		}\r\n\r\n		return $optionColumns;\r\n	}\r\n\r\n	public function totalproducts() {\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->load->model(\'catalog/product\');\r\n		$json = array();\r\n\r\n\r\n		if (isset($this->request->get[\'filter\'])) {\r\n			$filter = $this->request->get[\'filter\'];\r\n		} else {\r\n			$filter = \'\';\r\n		}\r\n\r\n		if (isset($this->request->get[\'min_price\'])) {\r\n			$min_price = $this->request->get[\'min_price\'];\r\n		} else {\r\n			$min_price = \'\';\r\n		}\r\n\r\n		if (isset($this->request->get[\'max_price\'])) {\r\n			$max_price = $this->request->get[\'max_price\'];\r\n		} else {\r\n			$max_price = \'\';\r\n		}\r\n\r\n		if (isset($this->request->get[\'filter_category_id\'])) {\r\n			$category_id = (int)$this->request->get[\'filter_category_id\'];\r\n		} else {\r\n			$category_id = 0;\r\n		}\r\n\r\n			$filter_data = array(\r\n				\'filter_category_id\' => $category_id,\r\n				\'filter_sub_category\' => $this->config->get(\'theme_prostore_subcategory\'),//prostore\r\n				\'min_price\'    		 => $min_price,\r\n				\'max_price\'    		 => $max_price,\r\n				\'filter_filter\'      => $filter,\r\n				\'limit\'     		 => \'10000\'\r\n			);\r\n			\r\n			if($this->config->get(\'theme_prostore_subcategory\')){\r\n				$filter_data[\'filter_sub_category\'] = true;\r\n			}\r\n			\r\n	        if ($this->config->get(\'config_tax\')) {\r\n	            $tax_data = $this->model_extension_module_prostore->gettax_class_id($filter_data);\r\n		        if (isset($tax_data[\'tax_class_id\'])) {\r\n		        	$filter_data[\'filter_tax_class_id\'] = $tax_data[\'tax_class_id\'];\r\n		        }       \r\n			}\r\n\r\n		$json[\'total\'] = $this->model_catalog_product->getTotalProducts($filter_data);\r\n		$json[\'text_show\'] = $this->language->get(\'text_prostore_show\');\r\n		$json[\'text_products\'] = $this->language->get(\'text_prostore_products\');\r\n		$json[\'id\'] = rand();\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n        <operation error=\"skip\">\r\n            <search><![CDATA[\r\n$data[\'products\'][] = array(\r\n            ]]></search>\r\n            <add position=\"before\"><![CDATA[\r\n                $productPath = $this->request->get[\'path\'];\r\n                if($this->config->get(\'theme_prostore_subcategory\') && !$this->config->get(\'config_seo_pro\')){\r\n                    $pathInfo = $this->model_extension_module_prostore->getProductPath($result[\'product_id\'],$this->request->get[\'path\']);\r\n                    if($pathInfo){\r\n                        $productPath = $pathInfo;\r\n                    }\r\n                }   \r\n            ]]></add>\r\n        </operation>\r\n        <operation error=\"skip\">\r\n            <search><![CDATA[\'path=\' . $this->request->get[\'path\'] . \'&product_id=\']]></search>\r\n            <add position=\"replace\"><![CDATA[\'path=\' . $productPath . \'&product_id=\']]></add>\r\n        </operation>   \r\n	</file>\r\n	<file path=\"catalog/controller/product/compare.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'review_status\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		// prostore\r\n		$compare_total = count($this->session->data[\'compare\']);\r\n		$data[\'compare_total\'] = $compare_total;\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		if ($compare_total) {\r\n			$data[\'model_num\'] = $compare_total .\' \'. $this->prostore->helper->correctForm(array($compare_total,\'compare\'));\r\n		} else {\r\n			$data[\'model_num\'] = false;\r\n		}\r\n		$this->document->addScript(\'catalog/view/javascript/prostore/plugins/jquery.matchHeight.min.js\');\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][$product_id]\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				// prostore\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($product_info[\'product_id\']);\r\n\r\n				if ($product_info[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n					$buy_btn = $product_info[\'stock_status\'];\r\n				} else {\r\n					$buy_btn = \'\';\r\n				}\r\n				$productLabels = $this->prostore->labels->getLabels4Product($product_info);\r\n\r\n				extract($productLabels);\r\n				// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$availability,\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					// prostore\r\n					\'buy_btn\'	   => $buy_btn,\r\n					\'discount\'       => $discount,\r\n					\'wish_compare_data\' => $wishCompareData,\r\n					// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'continue\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n$data[\'diff_keys\'] = $this->getDiff4Products($data); //prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function add()\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n$this->load->language(\'extension/theme/prostore\'); //prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function add()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n	public function getDiff4Products($data) {\r\n		$diffKeys = array();\r\n		if (isset($data[\'products\']) && count($data[\'products\']) > 1) {\r\n			$diffKeys = $this->getDiff($data[\'products\']);\r\n\r\n			$tempAttr = array();\r\n			foreach ($data[\'products\'] as $productId => $productData) {\r\n				$tempAttr[$productId] = $productData[\'attribute\'];\r\n			}\r\n			$diffKeys[\'attribute\'] = $this->getDiff($tempAttr);\r\n	\r\n			$diffKeys[\'dimensions\'] = 0;\r\n			if ($diffKeys[\'length\'] || $diffKeys[\'width\'] || $diffKeys[\'height\']) {\r\n				$diffKeys[\'dimensions\'] = 1;\r\n			}\r\n		}\r\n\r\n		return $diffKeys;\r\n	}\r\n\r\n/**\r\n * Формируем массив ключей содержащих количество уникальных значений этого ключа у товаров.\r\n * 0 - нет отличий. 1 - есть отличия.\r\n */\r\n\r\n	public function getDiff($data) {\r\n		$rowsMassive = array();\r\n		$productCounts = count($data);\r\n		foreach ($data as $productId => $productData) {\r\n			foreach ($productData as $key => $value) {\r\n				if ( is_array($value) ) {\r\n					continue;\r\n				}\r\n				$rowsMassive[$key][] = $value;\r\n			}\r\n		}\r\n		foreach ($rowsMassive as $key => $value) {\r\n			$isDiff = 0;\r\n			if ( $productCounts != count($value) || count(array_unique($value)) > 1) {\r\n				$isDiff = 1;\r\n			}\r\n			$rowsMassive[$key] = $isDiff;\r\n		}\r\n\r\n		return $rowsMassive;\r\n	}\r\n\r\n	public function remove() {\r\n		$this->load->language(\'product/compare\');\r\n		$this->load->language(\'extension/theme/prostore\');\r\n\r\n		$json = array();\r\n\r\n		if (!isset($this->session->data[\'compare\'])) {\r\n			$this->session->data[\'compare\'] = array();\r\n		}\r\n\r\n		if (isset($this->request->post[\'product_id\'])) {\r\n			$product_id = $this->request->post[\'product_id\'];\r\n		} else {\r\n			$product_id = 0;\r\n		}\r\n\r\n		$this->load->model(\'catalog/product\');\r\n\r\n		$product_info = $this->model_catalog_product->getProduct($product_id);\r\n\r\n		if ($product_info) {\r\n			if (in_array($product_id, $this->session->data[\'compare\'])) {\r\n\r\n				$key = array_search($product_id, $this->session->data[\'compare\']); \r\n				unset($this->session->data[\'compare\'][$key]);\r\n				\r\n			}\r\n\r\n			$json[\'success\'] = sprintf($this->language->get(\'text_prostore_success_remove_comp\'), $this->url->link(\'product/product\', \'product_id=\' . $this->request->post[\'product_id\']), $product_info[\'name\'], $this->url->link(\'product/compare\'));\r\n			$json[\'button_text\'] = sprintf($this->language->get(\'text_prostore_to_comp_full\') , $this->prostore->helper->compare_text((isset($this->session->data[\'compare\']) ? count($this->session->data[\'compare\']) : 0)));\r\n\r\n			$json[\'total\'] = sprintf($this->language->get(\'text_compare\'), (isset($this->session->data[\'compare\']) ? count($this->session->data[\'compare\']) : 0));\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n		\r\n		\r\n//prostore stop\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search index=\"0\"><![CDATA[>= 4]]></search>\r\n			<add position=\"replace\"><![CDATA[>= 20]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[(int)$product_info[\'rating\']]]></search>\r\n			<add position=\"replace\"><![CDATA[round($product_info[\'rating\'], 1)]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\n$json[\'total\']\r\n		]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n$json[\'button_text\'] = sprintf($this->language->get(\'text_prostore_in_comp_full\') , $this->prostore->helper->compare_text((isset($this->session->data[\'compare\']) ? count($this->session->data[\'compare\']) : 0)));\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/product.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->load->model(\'catalog/category\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		$data[\'text_prostore_points\'] = $this->language->get(\'text_prostore_points\');\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		$data[\'soc_share_code\'] = html_entity_decode($this->config->get(\'theme_prostore_soc_share_code\'), ENT_QUOTES, \'UTF-8\');\r\n		$data[\'soc_share_prod\'] = $this->config->get(\'theme_prostore_soc_share_prod\');\r\n		$data[\'optMode\'] = $this->config->get(\'theme_prostore_product_opt_select\');\r\n		$data[\'opt_price\'] = $this->config->get(\'theme_prostore_product_opt_price\');\r\n		$data[\'sku_compact\'] = $this->config->get(\'theme_prostore_product_opt_type\');\r\n		$data[\'category_time\'] = $this->config->get(\'theme_prostore_category_time\');\r\n		$data[\'time_text_1\'] = $this->language->get(\'text_time_text_1\');\r\n		$data[\'time_text_2\'] = $this->language->get(\'text_time_text_2\');\r\n		$data[\'text_review\'] = $this->language->get(\'text_review\');\r\n		$data[\'text_review_num_1\'] = $this->language->get(\'text_review_num_1\');\r\n		$data[\'text_review_num_2\'] = $this->language->get(\'text_review_num_2\');\r\n		$data[\'text_review_num_3\'] = $this->language->get(\'text_review_num_3\');	\r\n		$data[\'text_show_more\'] = $this->language->get(\'text_show_more\');\r\n		$data[\'text_review_plus\'] = $this->language->get(\'text_review_plus\');\r\n		$data[\'text_review_minus\'] = $this->language->get(\'text_review_minus\');\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->load->model(\'extension/module/prostore_faq\');\r\n		$data[\'lazyload\'] = $this->config->get(\'theme_prostore_lazyload\');\r\n		$data[\'mobile_view\'] = $this->config->get(\'theme_prostore_mobile_view\');\r\n		$data[\'product_in_tab\'] = $this->config->get(\'theme_prostore_product_in_tab\');\r\n		$data[\'product_thumbs\'] = $this->config->get(\'theme_prostore_product_thumbs\');\r\n		$isDateTime = false;\r\n		$isRequired = false;\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n			$category_id = (int)array_pop($parts);\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			$id = 0;\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'text\' => $category_info[\'name\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					\'breadList\' => $this->breadList($id),// prostore\r\n					\'cat_id\' => $id,// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'href\' => $this->url->link(\'product/category\', \'path=\' . $path)\r\n			]]></search>\r\n			<add position=\"after\" offset=\"2\"><![CDATA[\r\n				$id = $path_id;\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->document->addScript(\'catalog/view/javascript/jquery/magnific/jquery.magnific-popup.min.js\');\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"5\"><![CDATA[\r\n			// prostore\r\n			$data[\'has_shipping\'] = $product_info[\'shipping\'];\r\n			$data[\'shipping_forecast\'] = $this->config->get(\'theme_prostore_product_ship_forecast\');\r\n			$data[\'faq_status\'] = $this->config->get(\'theme_prostore_product_faq\')[\'status\'];\r\n			$data[\'shipping_address_form\'] = $this->load->controller(\'extension/module/prostore/prostore_theme/shipping_form\',$product_id);\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$data[\'model\'] = $product_info[\'model\'];\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			// prostore\r\n			$data[\'prostore_mpn\'] = $product_info[\'mpn\'];\r\n			$data[\'schema_description\'] = str_replace(array(\"\\r\\n\", \"\\r\", \"\\n\", \"\\\"\"),\' \', strip_tags(html_entity_decode($product_info[\'description\'], ENT_QUOTES, \'UTF-8\')));\r\n			// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'stock\'] = $product_info[\'quantity\'];\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n				$data[\'stock\'] = $this->language->get(\'text_instock\') . \': \' . $product_info[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\'); // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n			$this->load->model(\'tool/image\');\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n			$data[\'currency\'] = \'RUB\';\r\n			if (isset($this->session->data[\'currency\'])) {\r\n				$data[\'currency\'] = $this->session->data[\'currency\'];\r\n			}\r\n			$this->load->language(\'checkout/checkout\');\r\n			$data[\'entry_firstname\'] = $this->language->get(\'entry_firstname\');\r\n			$data[\'entry_lastname\'] = $this->language->get(\'entry_lastname\');\r\n			$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n			$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n			$data[\'entry_comment\'] = $this->language->get(\'entry_comment\');\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$this->load->model(\'catalog/information\');\r\n			if ($this->config->get(\'theme_prostore_review_pdata\')) {	\r\n				$review_pdata = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_review_pdata\'));\r\n				if ($review_pdata) {\r\n					$data[\'text_review_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_continue\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_review_pdata\'), true), $review_pdata[\'title\'], $review_pdata[\'title\']);\r\n				} else {\r\n					$data[\'text_review_pdata\'] = \'\';\r\n				}\r\n			} else {\r\n				$data[\'text_review_pdata\'] = \'\';\r\n			}\r\n\r\n			$data[\'button_fastorder_sendorder\'] = $this->language->get(\'button_prostore_sendorder\');\r\n\r\n			$data[\'text_prostore_products_text_more\'] = $this->language->get(\'text_prostore_products_text_more\');\r\n			$data[\'text_prostore_short_descr\'] = $this->language->get(\'text_prostore_short_descr\');\r\n			$data[\'text_prostore_products_review\'] = $this->language->get(\'text_prostore_products_review\');\r\n			\r\n			$tempDesc = $this->descriptionExtra($data[\'description\']);\r\n			$data[\'description\'] = $tempDesc[\'fulldesc\'];	\r\n			if (!$this->config->get(\'theme_prostore_product_short_descr\')) {\r\n				$data[\'description\'] = html_entity_decode($product_info[\'description\'], ENT_QUOTES, \'UTF-8\');\r\n			}\r\n			$data[\'short_descr\'] = $this->config->get(\'theme_prostore_product_short_descr\');\r\n			if ($this->config->get(\'theme_prostore_product_zoom_ezplus\')) {\r\n				$this->document->addScript(\'catalog/view/javascript/prostore/plugins/jquery.ez-plus.min.js\');\r\n			}\r\n			$data[\'zoom_ezplus\'] = $this->config->get(\'theme_prostore_product_zoom_ezplus\');\r\n			$data[\'zoom_fancybox\'] = $this->config->get(\'theme_prostore_product_zoom_fancybox\');\r\n			$data[\'p_related_view\'] = $this->config->get(\'theme_prostore_p_related_view\');\r\n			$data[\'shortdescription\'] = $tempDesc[\'shortdesc\'];			\r\n			$data[\'typeOptAtt\'] = $this->config->get(\'theme_prostore_product_att_select\');\r\n			$data[\'typeOptSelect\'] = $this->config->get(\'theme_prostore_product_opt_select\');\r\n			$data[\'typeOptCheckImg\'] = $this->config->get(\'theme_prostore_product_opt_checkbox_img\');\r\n			$data[\'typeOptRadioImg\'] = $this->config->get(\'theme_prostore_product_opt_radio_img\');\r\n			$data[\'att_right\'] = $this->config->get(\'theme_prostore_product_att_right\');\r\n			$data[\'store\'] = $this->config->get(\'config_name\');\r\n			$data[\'image_thumb_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_width\');\r\n			$data[\'image_thumb_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_height\');\r\n			$data[\'image_additional_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_width\');\r\n			$data[\'image_additional_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_height\');\r\n			$data[\'image_related_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_width\');\r\n			$data[\'image_related_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_height\');\r\n			$faq_total = $this->model_extension_module_prostore_faq->getTotalFaqsByProductId($product_id);\r\n			$data[\'faq_total\'] = $faq_total;\r\n			if ($product_info[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n				$data[\'buy_btn\'] = $product_info[\'stock_status\'];\r\n			} else {\r\n				$data[\'buy_btn\'] = \'\';\r\n			}\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$data[\'popup\'] = \'\';\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			$data[\'popup\'] = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_popup_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_popup_height\'));\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'thumb\'] = $this->model_tool_image->resize\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				if ($this->config->get(\'theme_prostore_og\')) { //Prostore added this\r\n					$this->document->setOgImage($data[\'thumb\']);\r\n				} //Prostore added this\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'thumb\'] = \'\';\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n				$data[\'thumb\'] = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_height\'));\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'images\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			if ($product_info[\'image\']) {\r\n				$data[\'additional\'] = $this->model_tool_image->resize($product_info[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_height\'));\r\n			} else {\r\n				$data[\'additional\'] = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_height\'));\r\n			}		\r\n				\r\n			$tab_video = array();\r\n			$data[\'count_videos\'] = 0;\r\n			$data[\'customTabs\'] = $this->model_extension_module_prostore->getFields4Product($this->request->get[\'product_id\']);\r\n			if (isset($data[\'customTabs\'][\'video\'])) {\r\n				$tab_video = $data[\'customTabs\'][\'video\'];\r\n				$data[\'count_videos\'] = count($tab_video);\r\n			}\r\n\r\n			$data[\'video\'] = $tab_video;\r\n			\r\n			$data[\'images\'] = false;\r\n\r\n			$wishCompareData = $this->prostore->helper->getDataWishCompare($product_id);\r\n			$data[\'compare_data\'] = $wishCompareData[\'compare_data\'];\r\n			$data[\'wish_data\'] = $wishCompareData[\'wish_data\'];\r\n\r\n			if($data[\'compare_data\'][\'is_in_compare\']){\r\n				$data[\'text_prostore_to_comp\'] = $this->language->get(\'text_prostore_in_comp\');\r\n			}\r\n		\r\n			if($data[\'wish_data\'][\'is_in_wish\']){\r\n				$data[\'text_prostore_to_wishlist\'] = $this->language->get(\'text_prostore_in_wishlist\');\r\n			}			\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'thumb\' => $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_height\'))\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			\'thumb\' => $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_thumb_height\')),\r\n			\'additional\' => $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_additional_height\'))\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'price\'] = $this->currency->format\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$data[\'price_schema\'] = number_format($this->tax->calculate($product_info[\'price\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), 0, \'\', \'\');// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'price\'] = false;\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$data[\'price_schema\'] = false;// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'special\'] = $this->currency->format\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$data[\'special_schema\'] = number_format($this->tax->calculate($product_info[\'special\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), 0, \'\', \'\');// prostore\r\n				$data[\'economy\'] = $this->currency->format($this->tax->calculate(($product_info[\'price\'] - $product_info[\'special\']), $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']);// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'special\'] = false;\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$data[\'special_schema\'] = false;// prostore\r\n				$data[\'economy\'] = false;// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'quantity\' => $discount[\'quantity\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					\'date_end\' => $discount[\'date_end\'],// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$product_option_value_data = array();\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				$isImage = false; //prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$product_option_value_data[] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore\r\n						if ($option_value[\'image\']) {\r\n							$isImage = true;\r\n						}\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'options\'][] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore\r\n				if ($option[\'type\'] == \'date\' || $option[\'type\'] == \'datetime\' || $option[\'type\'] == \'time\') {\r\n					$isDateTime = true;\r\n				}\r\n				if ($option[\'required\']) {\r\n					$isRequired = true;\r\n				}\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $option[\'required\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n					\'isimage\'			  => $isImage,  //prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'review_status\'] = $this->config->get(\'config_review_status\');\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			// prostore\r\n\r\n			if (!is_null($product_info[\'special\']) && (float)$product_info[\'special\'] >= 0) {\r\n				$data[\'item_price\'] = $this->currency->format((float)$product_info[\'special\'],$this->session->data[\'currency\'],\'\',false);\r\n			} else {\r\n				$data[\'item_price\'] = $this->currency->format((float)$product_info[\'price\'],$this->session->data[\'currency\'],\'\',false);\r\n			}\r\n\r\n			$cartProductInfo = $this->prostore->helper->getCartInfo4Product($product_info);\r\n\r\n			$data[\'isincart\'] = $cartProductInfo[\'isincart\'];\r\n\r\n			$data[\'to_cart_quantity\'] = $cartProductInfo[\'to_cart_quantity\'];\r\n\r\n			$data[\'cart_link\'] = $this->url->link(\'checkout/cart\');		\r\n\r\n			$data[\'isRequired\'] = $isRequired;\r\n\r\n			if ($isDateTime) {\r\n				if ($this->config->get(\'theme_prostore_bootstrap_ver\')) { //bootstrap5\r\n					$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/moment.min.js\');\r\n					$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/moment-with-locales.min.js\');\r\n					$this->document->addScript(\'catalog/view/javascript/prostore/datetimepicker/daterangepicker.js\');\r\n					$this->document->addStyle(\'catalog/view/javascript/prostore/datetimepicker/daterangepicker.css\');\r\n				} else { //bootstrap3\r\n					$this->document->addScript(\"catalog/view/javascript/jquery/datetimepicker/moment/moment.min.js\");\r\n					$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/moment/moment-with-locales.min.js\');\r\n					$this->document->addScript(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.js\');\r\n					$this->document->addStyle(\'catalog/view/javascript/jquery/datetimepicker/bootstrap-datetimepicker.min.css\');\r\n				}\r\n				$data[\'datepicker\'] = $this->language->get(\'code\');// prostore\r\n				$data[\'date_format\'] = $this->language->get(\'text_prostore_date_format\');// prostore\r\n				$data[\'datetime_format\'] = $this->language->get(\'text_prostore_datetime_format\');// prostore\r\n				$data[\'time_format\'] = $this->language->get(\'text_prostore_time_format\');// prostore\r\n			}\r\n			\r\n\r\n			$data[\'images_for_schema\'] = \'\';\r\n\r\n			if ($data[\'schema\']) {\r\n				$s_images = array();\r\n				if ($data[\'thumb\']) {\r\n					$s_images[] = $data[\'popup\'];\r\n				}				\r\n				foreach ($data[\'images\'] as  $s_image) { \r\n					if (!isset($s_image[\'isvideo\']) || (isset($s_image[\'isvideo\']) && !$s_image[\'isvideo\'])) {\r\n						$s_images[] = $s_image[\'popup\'];\r\n					}\r\n				}\r\n				$data[\'images_for_schema\'] = \'\"\' . implode(\'\",\"\', $s_images) . \'\"\';\r\n			}\r\n\r\n			$data[\'prep_options\'] = $this->doOptionColumns($data[\'options\']);\r\n\r\n			$data[\'quantity\'] = $product_info[\'quantity\'];\r\n			$data[\'special_date_end\'] = $data[\'discount_date_end\'] = 0;\r\n\r\n			if ($product_info[\'discount_date_end\'] && $product_info[\'discount_date_end\'] != \'0000-00-00\' ) {\r\n				$data[\'discount_date_end\'] = $product_info[\'discount_date_end\'];\r\n			}\r\n\r\n			$data[\'reviews_num\'] = (int)$product_info[\'reviews\'];\r\n\r\n			$review_total = $this->model_catalog_review->getTotalReviewsByProductId($this->request->get[\'product_id\']);\r\n			\r\n			$review_num_1 = $this->language->get(\'text_review_num_1\');\r\n			$review_num_2 = $this->language->get(\'text_review_num_2\');\r\n			$review_num_3 = $this->language->get(\'text_review_num_3\');\r\n			$review_num = array($review_num_1, $review_num_2, $review_num_3);\r\n			if ($review_total) {\r\n				$data[\'review_num\'] = $review_total .\' \'. $this->correctForm($review_total, $review_num);\r\n			} else {\r\n				$data[\'review_num\'] = false;\r\n			}\r\n\r\n			\r\n			$resultsLs = $this->model_catalog_review->getReviewsStatsByProductId($this->request->get[\'product_id\']);\r\n			for ($x=1; $x<6; $x++){\r\n				$data[\'reviewsStats\'][$x] = array(\r\n					\'rating\'     => $x,\r\n					\'count\'     => 0,\r\n					\'percent\'     => 0,\r\n					\'text\'     => $this->language->get(\'text_review_num_2\'),\r\n					\'link\'     => \'product_id=\' . $this->request->get[\'product_id\'] . \'&rating=\' . $x\r\n				);\r\n			}\r\n\r\n			foreach ($resultsLs as  $ratingCount) {\r\n				if ($review_total) {\r\n					$percent = round(($ratingCount[\'totall\']*100)/$review_total);\r\n				}else{\r\n					$percent = 0;\r\n				}\r\n\r\n				if ($ratingCount[\'totall\'] < 5) {\r\n					$text = $this->language->get(\'text_review_num_2\'); \r\n				}else{\r\n					$text = $this->language->get(\'text_review_num_2\');\r\n				}\r\n\r\n				$data[\'reviewsStats\'][$ratingCount[\'rating\']] = array(\r\n					\'rating\'     => $ratingCount[\'rating\'],\r\n					\'count\'     => $ratingCount[\'totall\'],\r\n					\'percent\'     => $percent,\r\n					\'text\'     => $text,\r\n					\'link\'     => \'product_id=\' . $this->request->get[\'product_id\'] . \'&rating=\' . $ratingCount[\'rating\']\r\n				);\r\n			}\r\n			krsort($data[\'reviewsStats\']);\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			// prostore\r\n			\r\n			$attributes = array();\r\n			$i = 0;\r\n			foreach ($data[\'attribute_groups\'] as $attribute_group) {\r\n				foreach ($attribute_group[\'attribute\'] as $key => $attribute) {\r\n					if ($i > 8) { break; }\r\n					$attributes[] = $attribute;\r\n					$i++;\r\n				}\r\n			}\r\n			$data[\'attributes\'] = array_chunk($attributes,3);\r\n\r\n			if ($this->config->get($this->config->get(\'theme_prostore_config_captcha_fo\') . \'_status\')) {\r\n				$data[\'captcha_fo\'] = $this->load->controller(\'extension/captcha/\' . $this->config->get(\'theme_prostore_config_captcha_fo\'));\r\n			} else {\r\n				$data[\'captcha_fo\'] = \'\';\r\n			}\r\n			$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n			\r\n			$data[\'labelsinfo\'] = $this->prostore->labels->getProductLabelsConfig();\r\n\r\n			/**\r\n			 * Получаем стикеры для продукта\r\n			 * getLabels4Product($product_info) возвращает массив стикеров для продукта\r\n			 * @param bool $isnewest\r\n			 * @param str $discount\r\n			 * @param str $special_date_end\r\n	 		 * @param bool $sales\r\n			 * @param bool $catch\r\n			 * @param bool $nocatch\r\n			 * @param str $popular\r\n			 * @param str $hit\r\n			 */			\r\n			$productLabels = $this->prostore->labels->getLabels4Product($product_info);\r\n\r\n			foreach ($productLabels as $labelName => $labelValue) {\r\n				$data[$labelName] = $labelValue;\r\n			}\r\n\r\n			$data[\'buy_click\'] = array();\r\n			if($this->config->get(\'theme_prostore_buy_click\')){\r\n				$data[\'buy_click\'] = $this->config->get(\'theme_prostore_buy_click\');\r\n\r\n				if ($this->customer->isLogged()) {\r\n					$this->load->model(\'account/customer\');\r\n					$data[\'customer_info\'] = $this->model_account_customer->getCustomer($this->customer->getId());\r\n				}\r\n			}\r\n\r\n			$data[\'found_cheaper_config\'] = $this->config->get(\'theme_prostore_found_cheaper\');\r\n			$data[\'found_cheaper\'] = $this->load->controller(\'extension/module/found_cheaper\',[\'product_id\' => $product_id]);\r\n			\r\n			$data[\'text_prostore_buy_click\'] = $this->language->get(\'text_prostore_buy_click\');			\r\n			$data[\'blogs_related\'] = \'\';\r\n\r\n			if ($this->config->get(\'theme_prostore_blog_product\')) {\r\n\r\n				$this->load->model(\'extension/module/prostoreblog\');\r\n				$blogs = array();		\r\n				$results = $this->model_extension_module_prostoreblog->getBlogsRelated2Prod($this->request->get[\'product_id\']);\r\n\r\n				foreach ($results as $result) {\r\n					\r\n					if ($result[\'image_preview\']) {\r\n						$image = $this->model_tool_image->resize($result[\'image_preview\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_height\'));\r\n					} elseif ($result[\'image\']) {\r\n						$image = $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_height\'));\r\n					} else {\r\n						$image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_blog_cat_height\'));\r\n					}\r\n\r\n					$blogs[] = array(\r\n						\'title\' => $result[\'title\'],\r\n						\'image\'       => $image,\r\n						\'date_added\' => $this->prostore->helper->rus_date(strtotime($result[\'date_added\'])),\r\n						\'description\' => utf8_substr(strip_tags(html_entity_decode($result[\'description\'], ENT_QUOTES, \'UTF-8\')), 0, 120) . \'...\',\r\n						\'href\'  => $this->url->link(\'extension/module/prostore_blog/getblog\', \'blog_id=\' . $result[\'blog_id\'])\r\n					);\r\n				}\r\n				$datablog[\'heading_title\'] = $this->language->get(\'text_related_blogs\');\r\n				$datablog[\'blogs\'] = $blogs;\r\n				$data[\'blogs_related\'] = $this->load->view(\'extension/module/prostore_blog_mod\', $datablog);\r\n\r\n		    }\r\n			\r\n			$data[\'image_product_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_width\');\r\n			$data[\'image_product_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_height\');\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'recurrings\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n			if (!isset($_COOKIE[\'899ProductsVieded\'])) { \r\n				$cookies = array();\r\n				$cookies[] = $product_id; \r\n				SetCookie(\"899ProductsVieded\",implode(\',\',$cookies),time()+3600*24*30*1,\"/\");\r\n			}else{\r\n				$cookies = explode(\',\',$_COOKIE[\'899ProductsVieded\']);\r\n				if (!in_array($product_id, $cookies)) { \r\n					if (count($cookies) < 50) {\r\n						$cookies[] = $product_id;\r\n					}else{\r\n						array_shift($cookies);\r\n						$cookies[] = $product_id; \r\n					}\r\n				}else{\r\n					foreach ($cookies as $key => $cookie) {\r\n						if ($cookie == $product_id) {\r\n							unset($cookies[$key]); \r\n						}\r\n					}\r\n					$cookies[] = $product_id; \r\n				}\r\n				SetCookie(\"899ProductsVieded\",implode(\',\',$cookies),time()+3600*24*30*1,\"/\");\r\n			}			\r\n			$data[\'buyclick_form\'] = $this->load->view(\'product/buyclick_form\', $data);\r\n			$data[\'buy_in_credit\'] = $this->config->get(\'theme_prostore_buy_in_credit\');\r\n			if ($data[\'buy_in_credit\'][\'status\']) {\r\n				$this->document->addScript(\'https://forma.tinkoff.ru/static/onlineScript.js\');\r\n				$tokenString = $data[\'buy_in_credit\'][\'showcase_id\'].\':\'.$data[\'buy_in_credit\'][\'password\'];\r\n				if ($data[\'buy_in_credit\'][\'demo_mode\']) {\r\n					$tokenString = \'demo-\' . $tokenString;\r\n				}\r\n				$data[\'buy_in_credit_token\'] = base64_encode($tokenString);\r\n				$data[\'buy_in_credit_price\'] =  sprintf($this->language->get(\'buy_in_credit_price_text\'), $this->currency->format($this->tax->calculate($data[\'item_price\']/($data[\'buy_in_credit\'][\'price\'] && (float)$data[\'buy_in_credit\'][\'price\'] != 0 ? (float)$data[\'buy_in_credit\'][\'price\'] : 17.89), $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']));\r\n				$data[\'buy_in_credit_help\'] = $this->config->get(\'theme_prostore_buy_in_credit_help\' . $this->config->get(\'config_language_id\'));\r\n			}\r\n\r\n			if ($this->config->get(\'theme_prostore_product_review\')) {  \r\n				$data[\'reviewsdata\'] = $this->review(1);\r\n			} else {\r\n				$data[\'reviewsdata\'] = false;\r\n			}\r\n\r\n			$data[\'faqs_content\'] = $this->load->controller(\'extension/module/prostore/prostore_theme/get_faq\');\r\n			$data[\'faqs_total\'] = $this->model_extension_module_prostore_faq->getTotalFaqsByProductId($this->request->get[\'product_id\']);\r\n\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nview(\'product/product\'\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore start\r\n			$data[\'href\'] = \'\';\r\n			$data[\'buy_click_typefrom\'] = \'product\';\r\n			if (isset($this->request->get[\'popup\'])) {\r\n				$data[\'column_left\'] = \'\';\r\n				$data[\'column_right\'] = \'\';\r\n				$data[\'content_top\'] = \'\';\r\n				$data[\'content_bottom\'] = \'\';\r\n				$data[\'footer\'] = \'\';\r\n				$data[\'header\'] = \'\';\r\n				$data[\'href\'] = $this->url->link(\'product/product\', $url . \'&product_id=\' . $this->request->get[\'product_id\']);\r\n				$data[\'buy_click_typefrom\'] = \'category-popup\';\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n				$extraImages = array();\r\n				\r\n					if ($this->config->get(\'theme_prostore_related_images_status\')) {\r\n						$images = array_slice($this->model_catalog_product->getProductImages($result[\'product_id\']), 0, (int)$this->config->get(\'theme_prostore_images_array\'));\r\n						foreach($images as $imageX){\r\n							$extraImages[] = $this->model_tool_image->resize($imageX[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_height\'));\r\n						}\r\n					}\r\n\r\n					extract($productsLabels[$result[\'product_id\']]);\r\n\r\n					if ($result[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n						$buy_btn = $result[\'stock_status\'];\r\n					} else {\r\n						$buy_btn = \'\';\r\n					}\r\n\r\n					$cartProductInfo = $this->prostore->helper->getCartInfo4Product($result);\r\n					\r\n					\r\n					if ($result[\'quantity\'] <= 0) {\r\n						$stock = $result[\'stock_status\'];\r\n					} elseif ($this->config->get(\'config_stock_display\')) {\r\n						$stock = $this->language->get(\'text_instock\') . \': \' . $result[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\');\r\n					} else {\r\n						$stock = $this->language->get(\'text_instock\');\r\n					}		\r\n					\r\n					if ($this->config->get(\'theme_prostore_manufacturer\') == 1) {\r\n						$manufacturer = $this->language->get(\'text_prostore_model\') . \' \' . $result[\'model\'];\r\n					} elseif ($this->config->get(\'theme_prostore_manufacturer\') == 2) {\r\n						$manufacturer =  $this->language->get(\'text_prostore_manufacturer\') . \' \' . $result[\'manufacturer\'];\r\n					} else {\r\n						$manufacturer = false;\r\n					}\r\n					\r\n					$wishCompareData = $this->prostore->helper->getDataWishCompare($result[\'product_id\']);\r\n\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\ngetProductRelated\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n$productsLabels = $this->prostore->labels->getLabels4Products($results); // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $tax,\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n					// prostore\r\n					\'manufacturer\'  => $manufacturer,\r\n					\'quantity\'        => $result[\'quantity\'],\r\n					\'stock\'        => $stock,\r\n					\'images\'       => $extraImages,	\r\n					\'isnewest\'       => $isnewest,\r\n					\'sales\'       => $sales,\r\n					\'discount\'       => $discount,\r\n					\'catch\'       => $catch,\r\n					\'nocatch\'       => $nocatch,\r\n					\'popular\'	  => $popular,\r\n					\'isincart\'	  => $cartProductInfo[\'isincart\'],\r\n					\'to_cart_quantity\'	  => $cartProductInfo[\'to_cart_quantity\'],\r\n					\'hit\'	 	  => $hit,\r\n					\'buy_btn\'	  => $buy_btn,\r\n					\'reward\'      => $result[\'reward\'],\r\n					\'special_date_end\'      => $special_date_end,\r\n					\'wish_compare_data\' => $wishCompareData,				\r\n					// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[public function review()]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n// prostore\r\n	public function options_info() {\r\n		$this->load->model(\'extension/module/prostore\');\r\n		$this->load->model(\'catalog/product\');\r\n		$this->load->language(\'checkout/cart\');\r\n		$product_option_value_data = array();\r\n		$error = array();\r\n		$totalOptionsPrice = 0;\r\n\r\n		if (isset($this->request->post[\'product_id\'])) {\r\n			$product_id = (int)$this->request->post[\'product_id\'];\r\n		} else {\r\n			$product_id = 0;\r\n		}\r\n		if (isset($this->request->post[\'option\'])) {\r\n			$option = array_filter($this->request->post[\'option\']);\r\n		} else {\r\n			$option = array();\r\n		}\r\n\r\n		$product_options = $this->model_catalog_product->getProductOptions($product_id);\r\n\r\n		foreach ($product_options as $product_option) {\r\n			if ($product_option[\'required\'] && empty($option[$product_option[\'product_option_id\']])) {\r\n				$optionsInfo[\'error\'][\'option\'][$product_option[\'product_option_id\']] = sprintf($this->language->get(\'error_required\'), $product_option[\'name\']);\r\n			}\r\n		}\r\n		$optionsInfo[\'discount_option\'] = false;\r\n		if (!empty($option) && empty($error)) {\r\n			foreach ($this->request->post[\'option\'] as $product_option_value_id) {\r\n				if (!$product_option_value_id) {\r\n					continue;\r\n				}\r\n				$option_value = $this->model_extension_module_prostore->getProductOptionValueData($product_option_value_id);\r\n				$price = $this->currency->format($option_value[\'price\'], $this->session->data[\'currency\'],\'\',false);\r\n				$product_option_value_data[] = array(\r\n					\'product_option_value_id\' => $option_value[\'product_option_value_id\'],\r\n					\'option_value_id\'         => $option_value[\'option_value_id\'],\r\n					\'name\'                    => $option_value[\'name\'],\r\n					\'price\'                   => $price,\r\n					\'price_prefix\'            => $option_value[\'price_prefix\']\r\n				);\r\n				if ($option_value[\'price_prefix\'] == \'+\') {\r\n					$totalOptionsPrice += $price;\r\n				}else{\r\n					$totalOptionsPrice -= $price;\r\n					/*\r\n					* if at lest one option with negative price is selected\r\n					* - provide to tinkoff summary item price only. Will be done on twig.\r\n					*/\r\n					$optionsInfo[\'discount_option\'] = true;\r\n				}			\r\n			}\r\n			\r\n		}\r\n		$optionsInfo[\'product_option_value_data\'] = $product_option_value_data;\r\n		$optionsInfo[\'total_options_price\'] = $totalOptionsPrice;\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($optionsInfo));	\r\n	}\r\n\r\n\r\n\r\n	public function show_in_popup() {\r\n		if (isset($this->request->get[\'prod_id\'])) {\r\n			$this->request->get[\'product_id\'] = $this->request->get[\'prod_id\'];\r\n			return $this->index();\r\n		}\r\n	}\r\n\r\n	public function like() {\r\n\r\n		$this->load->model(\'extension/module/prostore\');\r\n\r\n		$json = array();\r\n		$data = array();\r\n		$likes = 0;\r\n\r\n		$data[\'review_id\'] = $this->request->get[\'review_id\'];\r\n\r\n		$likesInfo = $this->model_extension_module_prostore->getLikes4review($this->request->get[\'review_id\']);\r\n\r\n		$data[\'count_good\'] = 0;\r\n		$data[\'count_bad\'] = 0;\r\n		if ($likesInfo) {\r\n			$data[\'count_good\'] = $likesInfo[\'count_good\'];\r\n			$data[\'count_bad\'] = $likesInfo[\'count_bad\'];\r\n		}\r\n\r\n		if (!isset($_COOKIE[\"likesls\"][(int)$data[\'review_id\']] )){\r\n			if ($this->request->get[\'islike\']) {\r\n				$likes = (int)$data[\'count_good\'];\r\n				$likes++;\r\n				$data[\'count_good\'] = $likes;\r\n			}else{\r\n				$likes = (int)$data[\'count_bad\'];\r\n				$likes++;\r\n				$data[\'count_bad\'] = $likes;\r\n			}\r\n\r\n			SetCookie(\"likesls[\" . $data[\'review_id\'] . \"]\",time(),time()+3600*24*30*12,\"/\");\r\n			$this->model_extension_module_prostore->setLikes4review($data);\r\n			$json[\'success\'][\'likes\'] = $likes;\r\n		}			\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n// prostore end	\r\n	/**\r\n	 * @param int|bool	$type Mark purpose. If 1 - first 10 reviews will be directly outputed on page (without AJAX).For SEO purposes.\r\n	 * 										If false - usual behaviour\r\n	 */\r\n\r\n	public function review($type = false) // prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'reviews\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		if ($type) {\r\n			$page = 1;\r\n		}		\r\n		$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n		$data[\'reviewsStats\'] = array();\r\n		if (isset($this->request->get[\'rating\'])) {\r\n			$rating = $this->request->get[\'rating\'];\r\n		}else{\r\n			$rating = 0;\r\n		}\r\n		$pagination_limit = $this->config->get(\'theme_prostore_product_review\') ? 10 : 5;\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$pagination->limit = 5;\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n$pagination->limit = $pagination_limit;//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\n$review_total = $this->model_catalog_review->getTotalReviewsByProductId($this->request->get[\'product_id\']);\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"3\"><![CDATA[\r\n		// prostore\r\n		$results = $this->model_catalog_review->getReviewsByProductIdLs($this->request->get[\'product_id\'], ($page - 1) * $pagination_limit, $pagination_limit, $rating); //prostore add this\r\n		$review_total = $this->model_catalog_review->getTotalReviewsByProductIdLs($this->request->get[\'product_id\'],$rating);\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'date_added\' => date($this->language->get(\'date_format_short\'), strtotime($result[\'date_added\']))\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n				// prostore\r\n				\'review_id\'     => (int)$result[\'review_id\'], \r\n				\'count_good\'     => (int)$result[\'count_good\'], \r\n				\'count_bad\'     => (int)$result[\'count_bad\'], \r\n				\'text_plus\'     => nl2br($result[\'text_plus\']), \r\n				\'text_minus\'     => nl2br($result[\'text_minus\']), \r\n				\'text_admin_answer\'     => nl2br($result[\'text_admin_answer\']), \r\n				\'answer_date_added\' => $this->prostore->helper->rus_date(strtotime($result[\'answer_date_added\'])),\r\n				\'date_added_schema\' => date(\'Y-m-d\', strtotime($result[\'date_added\'])), \r\n				// prostore\r\n				\'date_added\' => $this->prostore->helper->rus_date(strtotime($result[\'date_added\'])),// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$data[\'results\'] = sprintf($this->language->get(\'text_pagination\'), ($review_total) ? (($page - 1) * 5) + 1 : 0, ((($page - 1) * 5) > ($review_total - 5)) ? $review_total : ((($page - 1) * 5) + 5), $review_total, ceil($review_total / 5));\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n$data[\'results\'] = sprintf($this->language->get(\'text_pagination\'), ($review_total) ? (($page - 1) * $pagination_limit) + 1 : 0, ((($page - 1) * $pagination_limit) > ($review_total - $pagination_limit)) ? $review_total : ((($page - 1) * $pagination_limit) + $pagination_limit), $review_total, ceil($review_total / $pagination_limit));//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->response->setOutput($this->load->view(\'product/review\', $data));\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n		//prostore\r\n			if ($type) {\r\n				return $this->load->view(\'product/review\', $data);\r\n			}else{\r\n			    $this->load->language(\'extension/theme/prostore\');\r\n				$this->response->setOutput($this->load->view(\'product/review\', $data));\r\n			}			\r\n		// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getRecurringDescription()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n\r\n	public function custtabload() {\r\n		$this->load->model(\'extension/module/prostore\');\r\n\r\n		$customTabs = $this->model_extension_module_prostore->getFields4Product($this->request->get[\'product_ids\']);\r\n		$data[\'customTab\'] = $customTabs[\"popup\"][$this->request->get[\'tab\']];\r\n\r\n		$this->response->setOutput($this->load->view(\'product/custtab_popup\',$data));\r\n	}\r\n\r\n	public function autocomplete() {\r\n		$this->load->language(\'extension/theme/prostore\');\r\n		\r\n		$json = array();\r\n\r\n		if (isset($this->request->get[\'filter_name\']) || isset($this->request->get[\'filter_model\'])) {\r\n			$this->load->model(\'catalog/product\');\r\n//			$this->load->model(\'catalog/option\');\r\n			$this->load->model(\'tool/image\');\r\n\r\n			if (isset($this->request->get[\'filter_name\'])) {\r\n				$filter_name = $this->request->get[\'filter_name\'];\r\n			} else {\r\n				$filter_name = \'\';\r\n			}\r\n\r\n			if (isset($this->request->get[\'filter_model\'])) {\r\n				$filter_model = $this->request->get[\'filter_model\'];\r\n			} else {\r\n				$filter_model = \'\';\r\n			}\r\n\r\n			if (isset($this->request->get[\'limit\'])) {\r\n				$limit = $this->request->get[\'limit\'];\r\n			} else {\r\n				$limit = 6;\r\n			}\r\n\r\n			$filter_data = array(\r\n				\'filter_name\'  => $filter_name,\r\n				\'filter_tag\'   => $filter_name,\r\n				\'filter_model\' => $filter_model,\r\n				\'start\'        => 0,\r\n				\'limit\'        => $limit\r\n			);\r\n\r\n			$results = $this->model_catalog_product->getProducts($filter_data);\r\n\r\n\r\n			$href_search = \'\';\r\n			$show_all = \'\';\r\n\r\n			if (count($results) > 5) { \r\n				$results = array_slice($results, 0, 5);\r\n				$href_search = str_replace(\'&amp;\', \'&\', $this->url->link(\'product/search\', \'search=\' . $filter_name));\r\n				$show_all = $this->language->get(\'text_prostore_show_all_products\');				\r\n			}\r\n\r\n			$this->load->model(\'extension/module/prostore\');\r\n\r\n			if (isset($this->request->get[\'filter_name\'])) {\r\n				$filter_data_cat = $filter_data;\r\n				if (!$filter_name) {\r\n					$filter_data_cat[\'limit\'] = 1;\r\n				}else{\r\n					$filter_data_cat[\'limit\'] = 3;\r\n				}\r\n				$categoryResults = $this->model_extension_module_prostore->getCategoriesByName($filter_data_cat);\r\n				foreach ($categoryResults as $categoryResult) {\r\n					$json[] = array(\r\n						\'category_id\'          => $categoryResult[\'category_id\'],\r\n						\'name\'                => strip_tags(html_entity_decode($categoryResult[\'name\'], ENT_QUOTES, \'UTF-8\')),\r\n						\'href\' 				  => str_replace(\'&amp;\', \'&\', $this->url->link(\'product/category\', \'path=\' . $categoryResult[\'category_id\'])),\r\n						\'href_search\' 		 	  => $href_search,\r\n						\'text_reward\' 	      => $this->language->get(\'text_search_category\'),\r\n						\'show_all\' 		 	  => $show_all\r\n					);\r\n				}				\r\n			}\r\n\r\n			$data[\'labelsinfo\'] = $this->prostore->labels->getProductLabelsConfig();\r\n			$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n\r\n			$productsLabels = $this->prostore->labels->getLabels4Products($results);\r\n\r\n			foreach ($results as $result) {\r\n				if ($result[\'image\']) {\r\n					$image = $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'));// prostore\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'));// prostore\r\n				}\r\n				\r\n				if ($this->customer->isLogged() || !$this->config->get(\'config_customer_price\')) {\r\n					$price = $this->currency->format($this->tax->calculate($result[\'price\'], $result[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']);\r\n				} else {\r\n					$price = \'\';\r\n				}\r\n\r\n				if ((float)$result[\'special\'] && ($this->customer->isLogged() || !$this->config->get(\'config_customer_price\'))) {\r\n					$special = $this->currency->format($this->tax->calculate($result[\'special\'], $result[\'tax_class_id\'], $this->config->get(\'config_tax\')), $this->session->data[\'currency\']);\r\n				} else {\r\n					$special = \'\';\r\n				}\r\n				\r\n				if ($this->config->get(\'config_review_status\')) {\r\n					$rating = round($result[\'rating\'], 1);\r\n				} else {\r\n					$rating = false;\r\n				}\r\n\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($result[\'product_id\']);// prostore\r\n				\r\n				$extraImages = array();\r\n				\r\n					if ($this->config->get(\'theme_prostore_images_status\')) {\r\n						$images = array_slice($this->model_catalog_product->getProductImages($result[\'product_id\']), 0, (int)$this->config->get(\'theme_prostore_images_array\'));\r\n						foreach($images as $imageX){\r\n							$extraImages[] = $this->model_tool_image->resize($imageX[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_related_height\'));\r\n						}\r\n					}\r\n\r\n					extract($productsLabels[$result[\'product_id\']]);\r\n\r\n					if(isset($sales) && $sales){\r\n						$sales =$data[\'labelsinfo\'][\'sale\'][\'name\'][$this->config->get(\'config_language_id\')];				\r\n					}\r\n\r\n					if ($result[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n						$buy_btn = $result[\'stock_status\'];\r\n					} else {\r\n						$buy_btn = \'\';\r\n					}\r\n\r\n					$cartProductInfo = $this->prostore->helper->getCartInfo4Product($result);\r\n					\r\n					\r\n					if ($result[\'quantity\'] <= 0) {\r\n						$stock = $result[\'stock_status\'];\r\n					} elseif ($this->config->get(\'config_stock_display\')) {\r\n						$stock = $this->language->get(\'text_instock\') . \': \' . $result[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\');\r\n					} else {\r\n						$stock = $this->language->get(\'text_instock\');\r\n					}		\r\n					if ($this->config->get(\'theme_prostore_manufacturer\') == 1) {\r\n						$manufacturer = $this->language->get(\'text_prostore_model\') . \' \' . $result[\'model\'];\r\n					} elseif ($this->config->get(\'theme_prostore_manufacturer\') == 2) {\r\n						$manufacturer =  $this->language->get(\'text_prostore_manufacturer\') . \' \' . $result[\'manufacturer\'];\r\n					} else {\r\n						$manufacturer = false;\r\n					}\r\n\r\n\r\n				$json[] = array(\r\n					\'product_id\'          => $result[\'product_id\'],\r\n					\'name\'                => strip_tags(html_entity_decode($result[\'name\'], ENT_QUOTES, \'UTF-8\')),\r\n					\'model\'               => $result[\'model\'],\r\n					\'image\'               => $image,\r\n					\'price\'               => $price,\r\n					\'special\'             => $special,\r\n					\'manufacturer\'        => $manufacturer,\r\n					\'quantity\'            => $result[\'quantity\'],\r\n					\'stock\'       		  => $stock,\r\n					\'images\'      		  => $extraImages,	\r\n					\'isnewest\'      	  => $isnewest,\r\n					\'sales\'      		  => $sales,\r\n					\'discount\'     	  	  => $discount,\r\n					\'catch\'       		  => $catch,\r\n					\'nocatch\'     	 	  => $nocatch,\r\n					\'popular\'	 		  => $popular,\r\n					\'hit\'	 	 		  => $hit,\r\n					\'isincart\'	          => $cartProductInfo[\'isincart\'],// prostore\r\n					\'to_cart_quantity\'	  => $cartProductInfo[\'to_cart_quantity\'],// prostore\r\n					\'wish_compare_data\'   => $wishCompareData,// prostore\r\n					\'buy_btn\'	 		  => $buy_btn,\r\n					\'reward\'     		  => $result[\'reward\'],\r\n					\'minimum\'             => $result[\'minimum\'] > 0 ? $result[\'minimum\'] : 1,\r\n					\'rating\'              => $rating,\r\n					\'href\' 				  => str_replace(\'&amp;\', \'&\', $this->url->link(\'product/product\', \'product_id=\' . $result[\'product_id\'])),\r\n					\'href_search\' 		  => $href_search,\r\n					\'show_all\' 		 	  => $show_all,\r\n					\'button_to_cart\' 	  => $this->language->get(\'text_prostore_in_cart\'),\r\n					\'button_cart\' 	      => $this->language->get(\'button_cart\'),\r\n					\'text_reward\' 	      => $this->language->get(\'text_reward\'),\r\n					\'cart_link\' 		  => $this->url->link(\'checkout/cart\')\r\n				);\r\n			}\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n	public function breadList($category_id) {\r\n		$this->load->model(\'catalog/category\');\r\n		$data = array();\r\n		$categories = $this->model_catalog_category->getCategories($category_id);\r\n		foreach($categories as $category){\r\n			$data[] = array(\r\n				\'name\'		=> $category[\'name\'],\r\n				\'href\'       => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'])\r\n			);\r\n		}\r\n		return $data;\r\n	}\r\n	public function breadlistcr() {\r\n\r\n		$this->load->model(\'catalog/category\');\r\n		$category_id = $this->request->get[\'cat_id\'];\r\n		$data[\'breadLists\'] = array();\r\n		$categories = $this->model_catalog_category->getCategories($category_id);\r\n		foreach($categories as $category){\r\n			$data[\'breadLists\'][] = array(\r\n				\'name\'		=> $category[\'name\'],\r\n				\'href\'       => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'])\r\n			);\r\n		}\r\n		$this->response->setOutput($this->load->view(\'product/bread_popup\',$data));\r\n	}\r\n	public function descriptionExtra($description) {\r\n		$data[\'fulldesc\'] = $description;\r\n		$data[\'shortdesc\'] = \'\';\r\n		$tag = html_entity_decode($this->config->get(\'theme_prostore_product_short_tag\'), ENT_QUOTES, \'UTF-8\');\r\n	    if ($tag) {\r\n	      $temp = explode($tag,$description);\r\n	    }\r\n		if(isset($temp[0])){\r\n			$data[\'shortdesc\'] = $temp[0];\r\n			$data[\'fulldesc\'] = str_replace($data[\'shortdesc\'].$tag, \"\", $description);\r\n		}\r\n		return $data;\r\n	}\r\n	public function analystdataorder() {\r\n		$json = array();\r\n		\r\n		if (isset($this->request->server[\'SERVER_NAME\']) \r\n			&& strpos(HTTP_SERVER,$this->request->server[\'SERVER_NAME\']) !== False \r\n			&& isset($this->request->post[\'order_id\']) \r\n			&& $this->request->post[\'order_id\'] == $this->session->data[\'last_order_id\'])\r\n		{\r\n\r\n			$this->load->model(\'catalog/product\');\r\n			$this->load->model(\'catalog/category\');\r\n			$this->load->model(\'extension/module/prostore\');\r\n			$this->load->model(\'checkout/order\');\r\n\r\n			$json[\'transaction_id\'] = 0;\r\n\r\n			$order_id = (int)$this->request->post[\'order_id\'];\r\n			$products = $this->model_extension_module_prostore->getOrderProducts($order_id);\r\n			$order_info = $this->model_checkout_order->getOrder($order_id);\r\n			$json[\'value\'] = $order_info[\'total\'] ?? \'0\';\r\n			$json[\'transaction_id\'] = $order_id;\r\n\r\n\r\n			$cartSubTotal = $this->cart->getSubTotal();\r\n\r\n			foreach ($products as $product) {\r\n\r\n				$product_categories = $this->model_catalog_product->getCategories($product[\'product_id\']);\r\n				if($product_categories){\r\n					$category_info = $this->model_catalog_category->getCategory($product_categories[0][\'category_id\']);\r\n					$category_name = $category_info[\'name\'] ?? \"\";\r\n				}else{\r\n					$category_name = \"\";\r\n				}\r\n\r\n				$product_info = $this->model_catalog_product->getProduct($product[\'product_id\']);\r\n\r\n				$json[\'items\'][] = array(\r\n					\'id\' => $product[\'product_id\'],\r\n					\'name\'       => strip_tags(html_entity_decode($product[\'name\'], ENT_QUOTES, \'UTF-8\')),\r\n					\'price\' => $product[\'price\'],\r\n					\'quantity\' => $product[\'quantity\'],\r\n					\'category\'       => strip_tags(html_entity_decode($category_name, ENT_QUOTES, \'UTF-8\')),\r\n					\'brand\' => strip_tags(html_entity_decode($product_info[\'manufacturer\'], ENT_QUOTES, \'UTF-8\'))\r\n				);		\r\n			}\r\n		}else {\r\n			$json[\'error\'][\'warning\'] = \'Error permission\';\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}\r\n\r\n	public function analystdata() {\r\n		$json = array();\r\n	\r\n		if (isset($this->request->server[\'SERVER_NAME\']) && strpos(HTTP_SERVER,$this->request->server[\'SERVER_NAME\']) !== False) {\r\n\r\n			if (isset($this->request->post[\'product_id\'])) {\r\n				$product_id = $this->request->post[\'product_id\'];\r\n			} else {\r\n				$product_id = 0;\r\n			}\r\n\r\n			if (isset($this->request->post[\'qty\'])) {\r\n				$quantity = $this->request->post[\'qty\'];\r\n			} else {\r\n				$quantity = 1;\r\n			}\r\n\r\n\r\n\r\n			$this->load->model(\'catalog/product\');\r\n			$this->load->model(\'catalog/category\');\r\n\r\n			$product_info = $this->model_catalog_product->getProduct($product_id);\r\n\r\n					if ($this->customer->isLogged() || !$this->config->get(\'config_customer_price\')) {\r\n						$price = $this->tax->calculate($product_info[\'price\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'));\r\n					} else {\r\n						$price = false;\r\n					}\r\n\r\n					if ((float)$product_info[\'special\']) {\r\n						$price = $this->tax->calculate($product_info[\'special\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'));\r\n					}\r\n\r\n			$product_categories = $this->model_catalog_product->getCategories($product_id);\r\n			if($product_categories){\r\n				$category_info = $this->model_catalog_category->getCategory($product_categories[0][\'category_id\']);\r\n				$category_name = $category_info[\'name\'] ?? \"\";\r\n			}else{\r\n				$category_name = \"\";\r\n			}\r\n					$json[\'currency\'] = $this->session->data[\'currency\'];\r\n					$json[\'items\'][] = array(\r\n						\'id\' => $product_info[\'product_id\'],\r\n						\'name\'       => strip_tags(html_entity_decode($product_info[\'name\'], ENT_QUOTES, \'UTF-8\')),\r\n						\'price\' => $price,\r\n						\'quantity\' => $quantity,\r\n						\'category\'       => strip_tags(html_entity_decode($category_name, ENT_QUOTES, \'UTF-8\')),\r\n						\'brand\' => strip_tags(html_entity_decode($product_info[\'manufacturer\'], ENT_QUOTES, \'UTF-8\'))\r\n					);\r\n		}else {\r\n			$json[\'error\'][\'warning\'] = \'Error permission\';\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n\r\n	}\r\n\r\n	public function doOptionColumns($options){\r\n		$optionColumns = array();\r\n		$column = $this->config->get(\'theme_prostore_product_opt_select\');\r\n		if (!$column) {\r\n			$column = 2;\r\n		}\r\n\r\n\r\n//		if ($column == 2) {\r\n			$qtyPerColumn = (int)(count($options)/$column);\r\n            $i = 0;\r\n            $k = 0;\r\n \r\n			foreach ($options as $key => $option) {\r\n				$optionColumns[$k][$i] = $option;\r\n	            $i++;\r\n	            if ($i == $column) {  \r\n	               $i = 0;\r\n	               $k++;\r\n	            }     				\r\n			}\r\n\r\n//		}else{\r\n//			$optionColumns[] = $options;\r\n//		}\r\n\r\n		return $optionColumns;\r\n	}\r\n	\r\n	public function correctForm($number, $suffix) {\r\n		$keys = array(2, 0, 1, 1, 1, 2);\r\n		$mod = $number % 100;\r\n		$suffix_key = ($mod > 7 && $mod < 20) ? 2: $keys[min($mod % 10, 5)];\r\n		return $suffix[$suffix_key];\r\n	}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$this->url->link(\'product/search\', \'tag=\' . trim($tag))]]></search>\r\n			<add position=\"replace\"><![CDATA[str_replace(\'&\', \'&\', $this->url->link(\'product/search\', \'tag=\' . trim($tag)))// prostore]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/special.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'text_compare\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$data[\'heading_title\'] = $this->language->get(\'heading_title\');\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/{category,manufacturer,search,special}.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'text_compare\'] = sprintf\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			// prostore\r\n			$this->load->language(\'extension/theme/prostore\');\r\n			$data[\'schema\'] = $this->config->get(\'theme_prostore_schema\');\r\n			$data[\'product_detail\'] = $this->config->get(\'theme_prostore_product_detail\');\r\n			$data[\'category_time\'] = $this->config->get(\'theme_prostore_category_time\');\r\n			$data[\'category_sorts\'] = $this->config->get(\'theme_prostore_category_sorts\');\r\n			$data[\'category_limits\'] = $this->config->get(\'theme_prostore_category_limits\');\r\n			$data[\'category_categories\'] = $this->config->get(\'theme_prostore_category_categories\');\r\n			\r\n			$data[\'button_fastorder_sendorder\'] = $this->language->get(\'button_prostore_sendorder\');\r\n			$data[\'text_prostore_buy_click\'] = $this->language->get(\'text_prostore_buy_click\');\r\n			$data[\'text_product_view_btn\'] = $this->language->get(\'text_product_view_btn\');\r\n			$data[\'time_text_1\'] = $this->language->get(\'text_time_text_1\');\r\n			$data[\'time_text_2\'] = $this->language->get(\'text_time_text_2\');\r\n			$data[\'text_attributes\'] = $this->language->get(\'text_attributes\');\r\n			$data[\'text_description\'] = $this->language->get(\'text_description\');\r\n			$data[\'image_product_width\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\');\r\n			$data[\'image_product_height\'] = $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\');\r\n\r\n			$data[\'pc_view\'] = $this->config->get(\'theme_prostore_pc_view\');\r\n			$data[\'mobile_view\'] = $this->config->get(\'theme_prostore_mobile_view\');\r\n			$data[\'cart_link\'] = $this->url->link(\'checkout/cart\');\r\n			if ($this->config->get(\'theme_prostore_buy_click_pdata\')) {\r\n				$this->load->model(\'catalog/information\');\r\n\r\n				$information_info = $this->model_catalog_information->getInformation($this->config->get(\'theme_prostore_buy_click_pdata\'));\r\n\r\n				if ($information_info) {\r\n					$data[\'text_prostore_pdata\'] = sprintf($this->language->get(\'text_prostore_pdata\'), $this->language->get(\'button_prostore_sendorder\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'theme_prostore_buy_click_pdata\'), true), $information_info[\'title\'], $information_info[\'title\']);\r\n				} else {\r\n					$data[\'text_prostore_pdata\'] = \'\';\r\n				}\r\n			} else {\r\n				$data[\'text_prostore_pdata\'] = \'\';\r\n			}\r\n			\r\n			$data[\'buy_click\'] = array();\r\n			if($this->config->get(\'theme_prostore_buy_click\')){\r\n				$data[\'buy_click\'] = $this->config->get(\'theme_prostore_buy_click\');\r\n				if ($this->customer->isLogged()) {\r\n					$this->load->model(\'account/customer\');\r\n					$data[\'customer_info\'] = $this->model_account_customer->getCustomer($this->customer->getId());\r\n				}\r\n			}			\r\n			$this->load->language(\'checkout/checkout\');\r\n			$data[\'entry_firstname\'] = $this->language->get(\'entry_firstname\');\r\n			$data[\'entry_lastname\'] = $this->language->get(\'entry_lastname\');\r\n			$data[\'entry_email\'] = $this->language->get(\'entry_email\');\r\n			$data[\'entry_telephone\'] = $this->language->get(\'entry_telephone\');\r\n			$data[\'entry_comment\'] = $this->language->get(\'entry_comment\');\r\n			$data[\'lazyload\'] = $this->config->get(\'theme_prostore_lazyload\');\r\n			$data[\'button_to_cart\'] = $this->language->get(\'text_to_cart\');\r\n			$data[\'descriptions\'] = $this->config->get(\'theme_prostore_descriptions\');\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$image = $this->model_tool_image->resize($result[\'image\'], $this\r\n			]]></search>\r\n			<add position=\"before\" offset=\"2\"><![CDATA[\r\n			// prostore\r\n\r\n			$this->load->model(\'extension/module/prostore\');\r\n\r\n			$data[\'language_id\'] = $this->config->get(\'config_language_id\');\r\n\r\n			$data[\'labelsinfo\'] = $this->prostore->labels->getProductLabelsConfig();\r\n\r\n			$productsLabels = $this->prostore->labels->getLabels4Products($results);\r\n\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'][] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				// prostore\r\n				$extraImages = array();\r\n				if ($this->config->get(\'theme_prostore_images_status\')) {\r\n					$images = array_slice($this->model_catalog_product->getProductImages($result[\'product_id\']), 0, (int)$this->config->get(\'theme_prostore_images_array\'));\r\n					foreach($images as $imageX){\r\n						$extraImages[] = $this->model_tool_image->resize($imageX[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_product_height\'));\r\n					}\r\n				}\r\n				\r\n				extract($productsLabels[$result[\'product_id\']]);\r\n\r\n				$cartProductInfo = $this->prostore->helper->getCartInfo4Product($result);\r\n								\r\n				if ($result[\'quantity\'] <= 0) {\r\n					$stock = $result[\'stock_status\'];\r\n				} elseif ($this->config->get(\'config_stock_display\')) {\r\n					$stock = $this->language->get(\'text_instock\') . \': \' . $result[\'quantity\'] . \' \' . $this->language->get(\'text_prostore_cart_quantity\');\r\n				} else {\r\n					$stock = $this->language->get(\'text_instock\');\r\n				}	\r\n				\r\n				if ($result[\'quantity\'] <= 0 && !$this->config->get(\'config_stock_checkout\')) {\r\n					$buy_btn = $result[\'stock_status\'];\r\n				} else {\r\n					$buy_btn = \'\';\r\n				}\r\n				\r\n				if ($this->config->get(\'theme_prostore_manufacturer\') == 1) {\r\n					$manufacturer = $this->language->get(\'text_prostore_model\') . \' \' . $result[\'model\'];\r\n				} elseif ($this->config->get(\'theme_prostore_manufacturer\') == 2) {\r\n					$manufacturer =  $this->language->get(\'text_prostore_manufacturer\') . \' \' . $result[\'manufacturer\'];\r\n				} else {\r\n					$manufacturer = false;\r\n				}\r\n\r\n				$wishCompareData = $this->prostore->helper->getDataWishCompare($result[\'product_id\']);\r\n\r\n				$attribute_groups = $this->model_catalog_product->getProductAttributes($result[\'product_id\']);\r\n\r\n				// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $tax,\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n					// prostore\r\n					\'manufacturer\'  => $manufacturer,\r\n					\'quantity\'        => $result[\'quantity\'],\r\n					\'stock\'        => $stock,\r\n					\'images\'       => $extraImages,	\r\n					\'isnewest\'       => $isnewest,\r\n					\'sales\'       => $sales,\r\n					\'discount\'       => $discount,\r\n					\'catch\'       => $catch,\r\n					\'nocatch\'       => $nocatch,\r\n					\'popular\'	  => $popular,\r\n					\'hit\'	 	  => $hit,\r\n					\'isincart\'	  => $cartProductInfo[\'isincart\'],\r\n					\'to_cart_quantity\'	  => $cartProductInfo[\'to_cart_quantity\'],\r\n					\'attribute_groups\'	 	  => $attribute_groups,\r\n					\'buy_btn\'	  => $buy_btn,\r\n					\'reward\'      => $result[\'reward\'],\r\n					\'special_date_end\'      => $special_date_end,\r\n					\'wish_compare_data\' => $wishCompareData,\r\n					// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'limit\'] = $limit;\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n			$data[\'sort_title\'] = $this->language->get(\'text_default\');\r\n			foreach ($data[\'sorts\'] as $value) {\r\n				if ($value[\'value\'] == $sort . \'-\' . $order) {\r\n					$data[\'sort_title\'] = $value[\'text\'];\r\n				}\r\n			}\r\n\r\n			if ($this->config->get($this->config->get(\'theme_prostore_config_captcha_fo\') . \'_status\')) {\r\n				$data[\'captcha_fo\'] = $this->load->controller(\'extension/captcha/\' . $this->config->get(\'theme_prostore_config_captcha_fo\'));\r\n			} else {\r\n				$data[\'captcha_fo\'] = \'\';\r\n			}\r\n			$data[\'viewSub\'] = \'3\';	\r\n			if ($this->config->get(\'theme_prostore_pc_view\')) {\r\n				$viewSub = explode(\'-\',$this->config->get(\'theme_prostore_pc_view\'));          	\r\n				if(isset($viewSub[1])){\r\n					$viewSub = $viewSub[1];\r\n					$data[\'viewSub\'] = $viewSub; \r\n				}\r\n			}\r\n\r\n			if (isset($this->request->post[\'view\'])) {\r\n				$view = $this->request->post[\'view\'];\r\n				$this->session->data[\'view\'] = $view;\r\n			}elseif(isset($this->session->data[\'view\'])){\r\n				$view = $this->session->data[\'view\'];\r\n			} else {\r\n				if ($this->ismobile()) {\r\n					$view = $this->config->get(\'theme_prostore_mobile_view\');\r\n				}else{\r\n					$view = $this->config->get(\'theme_prostore_pc_view\');\r\n				}\r\n				$this->session->data[\'view\'] = $view;\r\n			}\r\n\r\n			$data[\'viewLayer\'] = $view;\r\n			$data[\'viewLayerM\'] = $view;\r\n			$data[\'view\'] = $view;\r\n\r\n			if(strpos($data[\'view\'],\'grid\') !== false){	\r\n				$viewSub = explode(\'-\',$view);\r\n				$data[\'view\'] = \'grid\';		          	\r\n				if(isset($viewSub[1])){\r\n					$viewSub = $viewSub[1];\r\n					$data[\'viewSub\'] = $viewSub; \r\n				}\r\n			}\r\n\r\n			if (isset($this->request->post[\'view\'])) {\r\n				$this->response->setOutput($this->load->view(\'product/category_\'.$data[\'view\'], $data));\r\n				return ;\r\n			}elseif(isset($this->request->get[\'popupdetail\'])){\r\n				$this->response->setOutput($this->load->view(\'product/category_popup\', $data));\r\n				return ;			\r\n			}\r\n			$data[\'buyclick_form\'] = $this->load->view(\'product/buyclick_form\', $data);\r\n			$data[\'productsview\'] = $this->load->view(\'product/category_\'.$data[\'view\'], $data);\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function index()\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n	public function isMobile() {\r\n		$user_agent = \'\';\r\n\r\n		if (isset($this->request->server[\'HTTP_USER_AGENT\'])) {\r\n			$user_agent = $this->request->server[\'HTTP_USER_AGENT\'];\r\n		}\r\n	    return preg_match(\"/(android|avantgo|blackberry|bolt|boost|cricket|docomo|fone|hiptop|mini|mobi|palm|phone|pie|tablet|up\\.browser|up\\.link|webos|wos)/i\", $user_agent);\r\n	}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[ $result[\'rating\'],]]></search>\r\n			<add position=\"replace\"><![CDATA[ $result[\'rating\'] > 0 ? number_format($result[\'rating\'], 1) : 0,]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/manufacturer.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\ngetManufacturers();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n$this->load->model(\'tool/image\'); // prostore, oc 3.0.3.7 fix\r\n$data[\'brands_img\'] = $this->config->get(\'theme_prostore_brands_img\');\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n[$key][\'manufacturer\']\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n				if ($result[\'image\']) {\r\n					$image = $this->model_tool_image->resize($result[\'image\'], $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_height\'));\r\n				} else {\r\n					$image = $this->model_tool_image->resize(\'placeholder.png\', $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_width\'), $this->config->get(\'theme_\' . $this->config->get(\'config_theme\') . \'_image_manufacturer_height\'));\r\n				}\r\n// prostore end							\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\ngetManufacturer($manufacturer_id)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		$data[\'language_id\'] = $this->config->get(\'config_language_id\'); //prostore added this		\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'name\' => $result[\'name\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'thumb\'	   => $image,// prostore			\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$data[\'column_left\'] = $this->load->controller(\'common/column_left\');\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n$data[\'column_left\']  = $this->load->controller(\'common/column_left\');\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'products\'] = array();\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			$data[\'manufacturer_id\'] = $manufacturer_id;				\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nnew Pagination\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore stop			\r\n			$data[\'nextPageUrl\'] = \'\';\r\n			$num_pages = ceil($product_total / $limit);\r\n			if ($page < $num_pages) {\r\n				$data[\'nextPageUrl\'] = $this->url->link(\'product/manufacturer/info\', \'manufacturer_id=\' . $this->request->get[\'manufacturer_id\'] .  $url . \'&page=\'.($page+1) );\r\n			}\r\n//prostore stop	\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/controller/product/search.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$data[\'limit\'] = $limit;\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			if (!isset($data[\'sorts\'])) {\r\n				$data[\'sorts\'] = array();\r\n			}\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"catalog/controller/startup/startup.php|admin/controller/startup/startup.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\nnew Encryption\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n        // Prostore theme\r\n        $this->registry->set(\'prostore\', new  Themes899\\Container($this->registry));		\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"catalog/controller/startup/seo_url.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n					if ($url[0] == \'manufacturer_id\') {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n					if ($url[0] == \'prostorecatblog_id\') { \r\n						$this->request->get[\'lbpath\'] = $url[1];\r\n					}\r\n\r\n					if ($url[0] == \'news_id\') {\r\n						$this->request->get[\'news_id\'] = $url[1];\r\n					}\r\n\r\n					if ($url[0] == \'blog_id\') {\r\n						$this->request->get[\'blog_id\'] = $url[1];\r\n					}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n					} elseif (sizeof($this->request->get) > 1) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			//prostore add this. For RS\r\n			} elseif ($this->request->get[\'route\'] == \'extension/module/prostore_blog/getblog\' && isset($this->request->get[\'blog_id\'])) {\r\n				$route = \'blog_id=\' . (int)$this->request->get[\'blog_id\'];\r\n			} elseif ($this->request->get[\'route\'] == \'extension/module/prostorecat_blog/getcat\' && isset($this->request->get[\'lbpath\'])) {\r\n				$route = \'prostorecatblog_id=\' . (int)$this->request->get[\'lbpath\'];				\r\n			//prostore add this. For RS\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[if ($query->row[\'query\'] && $url[0] != \'information_id\']]></search>\r\n			<add position=\"replace\"><![CDATA[if ($query->row[\'query\'] && $url[0] != \'information_id\' && $url[0] != \'blog_id\' && $url[0] != \'news_id\' && $url[0] != \'prostorecatblog_id\']]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n					$this->request->get[\'route\'] = \'information/information\';\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				} elseif (isset($this->request->get[\'news_id\'])) {//prostore\r\n					$this->request->get[\'route\'] = \'extension/module/prostore_news/getnews\';//prostore\r\n				} elseif (isset($this->request->get[\'blog_id\'])) {//prostore\r\n					unset($this->request->get[\'lbpath\']);\r\n					$this->request->get[\'route\'] = \'extension/module/prostore_blog/getblog\';//prostore\r\n				} elseif (isset($this->request->get[\'lbpath\'])) {//prostore\r\n\r\n					$this->request->get[\'route\'] = \'extension/module/prostorecat_blog/getcat\';//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[($data[\'route\'] == \'product/product\' && $key == \'product_id\') ||]]></search>\r\n			<add position=\"replace\"><![CDATA[($data[\'route\'] == \'product/product\' && $key == \'product_id\') || ($data[\'route\'] == \'extension/module/prostore_news/getnews\' && $key == \'news_id\') ||]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n				} elseif ($key == \'path\') {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n				} elseif ($data[\'route\'] == \'extension/module/prostore_blog/getblog\' && $key == \'blog_id\') {\r\n					if ($this->config->get(\'config_seo_pro\') === null) {  // Check - This section for Russian build OCStore only\r\n\r\n						if ($this->config->get(\'theme_prostore_blog_path\') ) { \r\n							$catlessblog = false;\r\n							$categories = $this->getPathByBlog($value); \r\n							if (!$categories) $catlessblog = true;\r\n							if ($catlessblog) {\r\n								$categories = 0;\r\n							}\r\n							$categories = explode(\'_\', $categories);\r\n							if ($categories[0]) {\r\n								array_unshift($categories, \"0\");\r\n							}\r\n\r\n							foreach ($categories as $category) {\r\n								$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE `query` = \'prostorecatblog_id=\" . (int)$category . \"\'\");\r\n\r\n								if ($query->num_rows && $query->row[\'keyword\']) {\r\n									$url .= \'/\' . $query->row[\'keyword\'];\r\n								} else {\r\n									$url = null;\r\n\r\n									break;\r\n								}\r\n							}\r\n\r\n						}\r\n					}\r\n					$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE `query` = \'\" . $this->db->escape($key . \'=\' . (int)$value) . \"\' AND store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\");\r\n\r\n					if ($query->num_rows && $query->row[\'keyword\']) {\r\n						$url .= \'/\' . $query->row[\'keyword\'];\r\n\r\n						unset($data[$key]);\r\n					}\r\n\r\n				} elseif ($key == \'lbpath\') {\r\n\r\n\r\n					$categories = explode(\'_\', $value);\r\n					if ($categories[0]) {\r\n						array_unshift($categories, \"0\");\r\n					}\r\n\r\n					foreach ($categories as $category) {\r\n						$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE `query` = \'prostorecatblog_id=\" . (int)$category . \"\'\");\r\n\r\n						if ($query->num_rows && $query->row[\'keyword\']) {\r\n							$url .= \'/\' . $query->row[\'keyword\'];\r\n						} else {\r\n							$url = null;\r\n\r\n							break;\r\n						}\r\n					}\r\n\r\n					unset($data[$key]);	\r\n				}elseif (($data[\'route\'] == \'extension/module/prostore_news/getnewslist\')) {	\r\n					$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"seo_url WHERE `query` = \'\" . $this->db->escape($value) . \"\'\");\r\n\r\n					if ($query->num_rows && $query->row[\'keyword\'] && (strpos(urldecode($url), $query->row[\'keyword\']) === false)) {\r\n						//&& (strpos($url, $query->row[\'keyword\']) === false) - uses for new version SEO-PRO to avoid doubling\r\n						$url .= \'/\' . $query->row[\'keyword\'];\r\n\r\n						unset($data[$key]);\r\n					}				\r\n\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function rewrite($link)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n	public function getPathByBlog($blog_id) {\r\n		$blog_id = (int)$blog_id;\r\n		if ($blog_id < 1) return false;\r\n\r\n		static $path = null;\r\n		$query = $this->db->query(\"SELECT category_id FROM \" . DB_PREFIX . \"prostore_blog_to_category WHERE blog_id = \'\" . (int)$blog_id . \"\' ORDER BY main_category DESC LIMIT 1\");\r\n\r\n		$path[$blog_id] = $this->getPathByCategoryLb($query->num_rows ? (int)$query->row[\'category_id\'] : 0);\r\n\r\n		return $path[$blog_id];\r\n	}\r\n\r\n	private function getPathByCategoryLb($category_id) {\r\n		$category_id = (int)$category_id;\r\n		if ($category_id < 1) return false;\r\n\r\n		static $path = null;\r\n\r\n			$max_level = 10;\r\n\r\n			$sql = \"SELECT CONCAT_WS(\'_\'\";\r\n			for ($i = $max_level-1; $i >= 0; --$i) {\r\n				$sql .= \",t$i.category_id\";\r\n			}\r\n			$sql .= \") AS path FROM \" . DB_PREFIX . \"prostorecat_blog t0\";\r\n			for ($i = 1; $i < $max_level; ++$i) {\r\n				$sql .= \" LEFT JOIN \" . DB_PREFIX . \"prostorecat_blog t$i ON (t$i.category_id = t\" . ($i-1) . \".parent_id)\";\r\n			}\r\n			$sql .= \" WHERE t0.category_id = \'\" . (int)$category_id . \"\'\";\r\n\r\n			$query = $this->db->query($sql);\r\n\r\n			$path[$category_id] = $query->num_rows ? $query->row[\'path\'] : false;\r\n\r\n		return $path[$category_id];\r\n	}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"catalog/language/ru-ru/ru-ru.php\">\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[<i class=\"fa fa-home\"></i>]]></search>\r\n			<add position=\"replace\"><![CDATA[Главная]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[\r\n$_[\'text_home\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n$_[\'entry_comment\']		 = \'Комментарий\';\r\n$_[\'error_comment\']		 = \'Введите комментарий!\';\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/language/en-gb/en-gb.php\">\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[<i class=\"fa fa-home\"></i>]]></search>\r\n			<add position=\"replace\"><![CDATA[Home]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[\r\n$_[\'text_home\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n$_[\'entry_comment\']		 = \'Entry comment\';\r\n$_[\'error_comment\']		 = \'Error comment!\';\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/language/uk-ua/uk-ua.php\">\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[<i class=\"fa fa-home\"></i>]]></search>\r\n			<add position=\"replace\"><![CDATA[Головна]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search trim=\"true\"><![CDATA[\r\n$_[\'text_home\']\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n$_[\'entry_comment\']		 = \'Коментар\';\r\n$_[\'error_comment\']		 = \'Введіть коментар!\';\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/account/order.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getTotalOrders\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore\r\n	public function getOrders899($start = 0, $limit = 20) {\r\n		if ($start < 0) {\r\n			$start = 0;\r\n		}\r\n\r\n		if ($limit < 1) {\r\n			$limit = 1;\r\n		}\r\n\r\n		$query = $this->db->query(\"SELECT o.order_id, o.firstname, o.lastname, os.name as status, o.order_status_id, o.date_added, o.total, o.currency_code, o.currency_value FROM `\" . DB_PREFIX . \"order` o LEFT JOIN \" . DB_PREFIX . \"order_status os ON (o.order_status_id = os.order_status_id) WHERE o.customer_id = \'\" . (int)$this->customer->getId() . \"\' AND o.order_status_id > \'0\' AND o.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' AND os.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY o.order_id DESC LIMIT \" . (int)$start . \",\" . (int)$limit);\r\n\r\n		return $query->rows;\r\n	}	\r\n	public function getOrderStatusId($order_status) {\r\n		$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"order_status  WHERE name = \'\" . $this->db->escape($order_status) . \"\' AND language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\");\r\n\r\n		return $query->row[\'order_status_id\'];\r\n	}\r\n//prostore\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/account/wishlist.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getTotalWishlist\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n\r\n	public function getWishlistLb() {\r\n		if ($this->customer->isLogged()) {\r\n       		 $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"customer_wishlist WHERE customer_id = \'\" . (int)$this->customer->getId() . \"\'\");\r\n			return $query->rows;\r\n		}else{\r\n				$results = array();\r\n				if(isset($_COOKIE[\"productsWish\"])){\r\n					foreach($_COOKIE[\"productsWish\"] as $product_id => $val){\r\n						$cookies[$val] = $product_id;\r\n					}\r\n					krsort($cookies);\r\n					\r\n					foreach($cookies as $product_id){\r\n						$results[]  = array(\r\n							\'customer_id\' => 0,\r\n							\'product_id\' => $product_id, \r\n							\'date_added\' => \'\'\r\n						);\r\n					}\r\n				}\r\n				return 	$results ;		\r\n		}\r\n	}\r\n\r\n	public function addWishlistLb($product_id) {\r\n		if ($this->customer->isLogged()) {\r\n			$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"customer_wishlist WHERE customer_id = \'\" . (int)$this->customer->getId() . \"\' AND product_id = \'\" . (int)$product_id . \"\'\");\r\n\r\n			$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"customer_wishlist SET customer_id = \'\" . (int)$this->customer->getId() . \"\', product_id = \'\" . (int)$product_id . \"\', date_added = NOW()\");\r\n		}else{\r\n			if (!isset($_COOKIE[\"productsWish[\" . $product_id . \"]\"])){\r\n				$_COOKIE[\"productsWish\"][$product_id] = \'0\';\r\n				SetCookie(\"productsWish[\" . $product_id . \"]\",time(),time()+3600*24*30*12,\"/\");\r\n			}		\r\n		}	\r\n	}\r\n\r\n	public function getTotalWishlistLb() {\r\n		if ($this->customer->isLogged()) {\r\n			$query = $this->db->query(\"SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"customer_wishlist WHERE customer_id = \'\" . (int)$this->customer->getId() . \"\'\");\r\n\r\n			return $query->row[\'total\'];\r\n		}else{\r\n				$results = 0;\r\n				if(isset($_COOKIE[\"productsWish\"])){\r\n					$results = count($_COOKIE[\"productsWish\"]);\r\n				}\r\n				return 	$results ;			\r\n		}\r\n	}\r\n\r\n	public function deleteWishlistLb($product_id) {\r\n		if ($this->customer->isLogged()) {\r\n			$this->db->query(\"DELETE FROM \" . DB_PREFIX . \"customer_wishlist WHERE customer_id = \'\" . (int)$this->customer->getId() . \"\' AND product_id = \'\" . (int)$product_id . \"\'\");\r\n		}else{\r\n			SetCookie(\"productsWish[\" . $product_id . \"]\",time(),time()-3600, \'/\');\r\n			unset($_COOKIE[\"productsWish\"][$product_id]);\r\n		}\r\n		return $this->getTotalWishlistLb();\r\n	}\r\n\r\n	public function getTotalWishlistByProduct($product_id) {\r\n		$query = $this->db->query(\"SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"customer_wishlist WHERE product_id = \'\" . (int)$product_id . \"\'\");\r\n		$result = $query->row[\'total\'];\r\n\r\n		if(isset($_COOKIE[\"productsWish\"][$product_id])){\r\n			$result++;\r\n		}\r\n		return 	$result;\r\n\r\n	}\r\n\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/catalog/category.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getTotalCategoriesByCategoryId\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n	// prostore\r\n	public function getTopCategories899() {\r\n		$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"category c LEFT JOIN \" . DB_PREFIX . \"category_description cd ON (c.category_id = cd.category_id) LEFT JOIN \" . DB_PREFIX . \"category_to_store c2s ON (c.category_id = c2s.category_id) WHERE ( top = 1 OR c.parent_id = 0 ) AND cd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' AND c2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'  ORDER BY c.parent_id, c.sort_order, cd.name\");\r\n		return $query->rows;	\r\n	}\r\n	public function getCategoriesChildrenNextLevel($parent_id = 0) {\r\n		$categoriesData = array();\r\n		$sql = \"SELECT * FROM \" . DB_PREFIX . \"category c LEFT JOIN \" . DB_PREFIX . \"category_description cd ON (c.category_id = cd.category_id) \";\r\n		$sql .= \"LEFT JOIN \" . DB_PREFIX . \"category_to_store c2s ON (c.category_id = c2s.category_id) \";\r\n		$sql .=  \" WHERE c.parent_id = \'\" . (int)$parent_id . \"\' AND cd.language_id = \'\" . (int)$this->config->get(\'config_language_id\')  . \"\' AND c.status = \'1\'\";\r\n		$sql .=  \" AND c2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\'  ORDER BY c.parent_id, c.sort_order, cd.name LIMIT 20\";\r\n		$query = $this->db->query($sql);\r\n		foreach ($query->rows as $category) {\r\n			$categoriesData[] = array(\r\n				\'category_id\'	=> $category[\'category_id\'],\r\n				\'name\'			=> $category[\'name\'],\r\n				\'href\'          => $this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'])\r\n			);\r\n		}\r\n		\r\n		return $categoriesData;\r\n	}	\r\n\r\n	// prostore end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/catalog/review.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$this->db->getLastId();\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		//prostore\r\n		$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"review_extls SET review_id = \'\" . (int)$review_id . \"\', text_plus  = \'\" . $this->db->escape($data[\'text_plus\']) . \"\', text_minus = \'\" . $this->db->escape($data[\'text_minus\']) . \"\'\");\r\n		// prostore end			\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\ngetTotalReviewsByProductId($product_id)\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n\r\n	public function getTotalReviewsByProductIdLs($product_id, $rating = 0) {\r\n\r\n		$sql = \"SELECT COUNT(*) AS total FROM \" . DB_PREFIX . \"review r LEFT JOIN \" . DB_PREFIX . \"product p ON (r.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) WHERE p.product_id = \'\" . (int)$product_id . \"\' AND p.date_available <= NOW() AND p.status = \'1\' AND r.status = \'1\' AND pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\r\n\r\n		if ($rating) {\r\n			$sql .= \" AND r.rating = \'\" . (int)$rating . \"\'\";\r\n		}\r\n\r\n		$query = $this->db->query($sql);\r\n\r\n		return $query->row[\'total\'];\r\n	}\r\n\r\n	public function getReviewsByProductIdLs($product_id, $start = 0, $limit = 20, $rating = 0) {\r\n		if ($start < 0) {\r\n			$start = 0;\r\n		}\r\n\r\n		if ($limit < 1) {\r\n			$limit = 20;\r\n		}\r\n\r\n		$sql = \"SELECT r.review_id, r.author, r.rating, r.text, p.product_id, pd.name, p.price, p.image, r.date_added, re.text_plus, re.text_minus, re.text_admin_answer,re.answer_date_added, re.count_bad, re.count_good FROM \" . DB_PREFIX . \"review r LEFT JOIN \" . DB_PREFIX . \"product p ON (r.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) LEFT JOIN \" . DB_PREFIX . \"review_extls re ON (r.review_id = re.review_id) WHERE p.product_id = \'\" . (int)$product_id . \"\' AND p.date_available <= NOW() AND p.status = \'1\' AND r.status = \'1\' AND pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\r\n\r\n		if ($rating) {\r\n			$sql .= \" AND r.rating = \'\" . (int)$rating . \"\'\";\r\n		}\r\n\r\n		$sql .= \" ORDER BY r.date_added DESC LIMIT \" . (int)$start . \",\" . (int)$limit;\r\n\r\n		$query = $this->db->query($sql);\r\n\r\n		return $query->rows;\r\n	}\r\n\r\n\r\n\r\n	public function getReviewsStatsByProductId($product_id) {\r\n		$query = $this->db->query(\"SELECT rating, COUNT(review_id) AS totall FROM \" . DB_PREFIX . \"review WHERE product_id = \'\" . (int)$product_id . \"\' AND status =\'1\'   GROUP By rating ORDER BY rating DESC\");\r\n\r\n		return $query->rows;\r\n	}\r\n\r\n	public function getReviews($data) {\r\n		if ($data[\'start\'] < 0) {\r\n			$start = 0;\r\n		}else{\r\n			$start = $data[\'start\'];\r\n		}\r\n\r\n		if ($data[\'limit\'] < 1) {\r\n			$limit = 20;\r\n		}else{\r\n			$limit = $data[\'limit\'];\r\n		}\r\n\r\n		$reviews_data = $this->cache->get(\'899.reviews.\' . (int)$data[\'filter_category_id\'] . \'.\' . (int)$data[\'filter_sub_category\'] . \'.\'. (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . (int)$limit);\r\n\r\n		if (!$reviews_data) {\r\n\r\n\r\n			$sql = \"SELECT DISTINCT r.review_id, r.author, r.rating, r.text, p.product_id, pd.name, p.price, p.image, r.date_added, re.text_plus, re.text_minus, re.count_bad, re.count_good FROM \" . DB_PREFIX . \"review r LEFT JOIN \" . DB_PREFIX . \"product p ON (r.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) LEFT JOIN \" . DB_PREFIX . \"review_extls re ON (r.review_id = re.review_id) \";\r\n\r\n			if ($data[\'filter_category_id\']) {\r\n				if ($data[\'filter_sub_category\']) {\r\n					$sql .= \"  LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (p.product_id = p2c.product_id) LEFT JOIN \" . DB_PREFIX . \"category_path cp ON (p2c.category_id = cp.category_id)\";\r\n				} else {\r\n					$sql .= \" LEFT JOIN  \" . DB_PREFIX . \"product_to_category p2c ON (p.product_id = p2c.product_id)\";\r\n				}\r\n			}\r\n\r\n			$sql .= \" WHERE p.date_available <= NOW() AND p.status = \'1\' AND r.status = \'1\' AND pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\'\";\r\n\r\n			if ($data[\'filter_category_id\']) {\r\n				if ($data[\'filter_sub_category\']) {\r\n					$sql .= \" AND cp.path_id = \'\" . (int)$data[\'filter_category_id\'] . \"\'\";\r\n				} else {\r\n					$sql .= \" AND p2c.category_id = \'\" . (int)$data[\'filter_category_id\'] . \"\'\";\r\n				}\r\n			}\r\n\r\n			$sql .= \" ORDER BY r.date_added DESC LIMIT \" . (int)$start . \",\" . (int)$limit;\r\n\r\n$query = $this->db->query($sql);\r\n			$reviews_data = $query->rows;\r\n\r\n		    $this->cache->set(\'899.reviews.\' . (int)$data[\'filter_category_id\'] . \'.\' . (int)$data[\'filter_sub_category\'] . \'.\'. (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . (int)$limit, $reviews_data);\r\n\r\n		}\r\n\r\n		return $reviews_data;\r\n	}\r\n\r\n\r\n// prostore end			\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/catalog/product.php\">\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n		if ($query->num_rows) {\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore start\r\n			if ($this->config->get(\'theme_prostore_product_cod\')) {\r\n				$query->row[\'model\'] = $query->row[$this->config->get(\'theme_prostore_product_cod\')];\r\n			}\r\n			$discount_date_end = false;\r\n			if ($query->row[\'discount\']) {\r\n				$query2 = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"product_discount WHERE product_id = \'\" . (int)$product_id . \"\' AND quantity = \'1\'\");\r\n				$discount_date_end = $query2->row[\'date_end\'];\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $query->row[\'special\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n				\'discount_date_end\' => $discount_date_end,  //prostore\r\n				\'shipping\' => $query->row[\'shipping\'],  //prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$query->row[\'rating\'])]]></search>\r\n			<add position=\"replace\"><![CDATA[$query->row[\'rating\'], 1)]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n	public function getProducts($data = array()) {\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n// prostore start\r\n	private function getCustomerGroup() {\r\n		if($this->customer->isLogged()) {\r\n			$customer_group_id = $this->customer->getGroupId();\r\n			return $customer_group_id;\r\n		} else {\r\n			$customer_group_id = $this->config->get(\'config_customer_group_id\');\r\n			return $customer_group_id;\r\n		}\r\n	}\r\n// prostore end\r\n	public function getProducts($data = array()) {\r\n// prostore start\r\n		$customer_group_id = $this->getCustomerGroup();\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$sql = \"SELECT p.product_id, (SELECT AVG(rating)]]></search>\r\n			<add position=\"replace\"><![CDATA[$sql = \"SELECT p.product_id, p.price, (SELECT AVG(rating)]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[ON (pf.product_id = p.product_id)]]></search>\r\n			<add position=\"replace\"><![CDATA[ON (pf.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"filter f ON (pf.filter_id = f.filter_id)]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n			$sql .= \" FROM \" . DB_PREFIX . \"product p\";\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			// prostore\r\n			if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n				$sql .= \" LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (p2c.product_id = p.product_id)\";\r\n			}\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\nif (!empty($data[\'filter_category_id\'])) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n			$categories = implode(\",\",$data[\'filter_category_ids\']);\r\n			$sql .= \" AND p2c.category_id IN (\" . $categories . \")\";\r\n		}	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$sql .= \" AND pf.filter_id IN (\" . implode(\',\', $implode) . \")\";\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore\r\n				if(!(int)$this->config->get(\'module_filter_filter_grouptype\')){\r\n					$query1 = $this->db->query(\"SELECT COUNT(DISTINCT f.filter_group_id) as total FROM \" . DB_PREFIX . \"filter_group fg LEFT JOIN \" . DB_PREFIX . \"filter f ON (fg.filter_group_id = f.filter_group_id) where f.filter_id IN(\" . implode(\',\', $implode) . \")\");\r\n					if($query1->num_rows){\r\n						$filtersCount = $query1->row[\'total\'];\r\n					}					\r\n				}\r\n// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$sort_data = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n		// prostore\r\n		if(isset($data[\'min_price\']) && $data[\'min_price\'] >= 0) {\r\n			$tempMinPrice = (float)$data[\'min_price\'];\r\n			if (!$this->config->get(\'decimal_place\')) {\r\n				$tempMinPrice = (float)$data[\'min_price\'] -0.5 ;\r\n			}\r\n		    if ($this->config->get(\'config_tax\') && isset($data[\'filter_tax_class_id\'])) {\r\n		        $tempMinPrice = $tempMinPrice - $this->tax->clearTax( $tempMinPrice, $data[\'filter_tax_class_id\'] );\r\n		    }\r\n\r\n			$sql .= \" HAVING Coalesce(discount, special, price) >=\" . $this->currency->convert($tempMinPrice,$this->session->data[\'currency\'], $this->config->get(\'config_currency\'));\r\n		\r\n			if(isset($filtersCount) && !(int)$this->config->get(\'module_filter_filter_grouptype\')){\r\n				$sql .= \" AND  COUNT(DISTINCT f.filter_group_id) = \" . (int)$filtersCount ;	\r\n			}			\r\n		}\r\n		if(isset($data[\'max_price\']) && $data[\'min_price\'] != \"\" && $data[\'max_price\'] > 0) {\r\n			$tempMaxPrice = (float)$data[\'max_price\'];\r\n			if (!$this->config->get(\'decimal_place\')) {\r\n				$tempMaxPrice = (float)$data[\'max_price\'] + 0.5 ;\r\n			}\r\n\r\n		    if ($this->config->get(\'config_tax\') && isset($data[\'filter_tax_class_id\'])) {\r\n		        $tempMaxPrice = $tempMaxPrice - $this->tax->clearTax( $tempMaxPrice, $data[\'filter_tax_class_id\'] );\r\n		    }\r\n		\r\n			$sql .= \" AND Coalesce(discount, special, price) <=\" . $this->currency->convert($tempMaxPrice,$this->session->data[\'currency\'], $this->config->get(\'config_currency\'));		\r\n			\r\n		}\r\n\r\n		// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'p.quantity\',\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n			\'p.viewed\',// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'p.date_added\'\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n			\'p.date_added\',\r\n			\'discount\'// prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$sql .= \" ORDER BY LCASE(\" . $data[\'sort\'] . \")\";\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\nif ($this->config->get(\'theme_prostore_category_products\')) {\r\n	$sql .= \" ORDER BY (p.quantity>0) DESC, LCASE(\" . $data[\'sort\'] . \")\";// prostore\r\n}else{\r\n	$sql .= \" ORDER BY LCASE(\" . $data[\'sort\'] . \")\";\r\n}	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$sql .= \" ORDER BY (CASE WHEN\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\nif ($this->config->get(\'theme_prostore_category_products\')) {\r\n	$sql .= \" ORDER BY (p.quantity>0) DESC,(CASE WHEN special IS NOT NULL THEN special WHEN discount IS NOT NULL THEN discount ELSE p.price END)\";\r\n}else{\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$sql .= \" ORDER BY (CASE WHEN\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n	}\r\n} elseif ($data[\'sort\'] == \'discount\') {// prostore\r\n	if ($this->config->get(\'theme_prostore_category_products\')) {\r\n		$sql .= \" ORDER BY (p.quantity>0) DESC,(CASE WHEN special IS NOT NULL THEN (p.price - special)  END)\";	// prostore 		\r\n	}else{\r\n		$sql .= \" ORDER BY (CASE WHEN special IS NOT NULL THEN (p.price - special)  END)\";\r\n	}\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$sql .= \" ORDER BY \" . $data[\'sort\'];\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\nif ($this->config->get(\'theme_prostore_category_products\')) {\r\n	$sql .= \" ORDER BY (p.quantity>0) DESC, \" . $data[\'sort\'];// prostore\r\n}else{\r\n	$sql .= \" ORDER BY \" . $data[\'sort\'];\r\n}\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\n$sql .= \" ORDER BY \" . $data[\'sort\'];\r\n			]]></search>\r\n			<add position=\"after\" offset=\"3\"><![CDATA[\r\n// prostore start\r\n		}elseif(isset($data[\'sort\']) && $data[\'sort\'] == \'random\'){  \r\n				$sql .= \" ORDER BY rand() \";\r\n// prostore end		\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$sql .= \" ORDER BY p.sort_order\";\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\nif ($this->config->get(\'theme_prostore_category_products\')) {\r\n	$sql .= \" ORDER BY (p.quantity>0) DESC, p.sort_order\";// prostore\r\n}else{\r\n	$sql .= \" ORDER BY p.sort_order\";// prostore\r\n}	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getProductSpecials\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore start\r\n		$categories = 0;\r\n		if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n		  $categories = implode(\",\",$data[\'filter_category_ids\']);\r\n		}\r\n// prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id)]]></search>\r\n			<add position=\"replace\"><![CDATA[) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (p.product_id = p2c.product_id)]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[store_id\') . \"\' AND]]></search>\r\n			<add position=\"replace\"><![CDATA[store_id\') . \"\'\";\r\n// prostore start\r\n		if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n		  $sql .= \" AND p2c.category_id IN (\" . $categories . \")\";\r\n		}\r\n// prostore end\r\n		$sql .= \" AND]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getTotalProducts(\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore start\r\n		$customer_group_id = $this->getCustomerGroup();\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nAS total\"\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		// prostore start\r\n		if(isset($data[\'max_price\']) && $data[\'max_price\'] > 0) {\r\n			$sql = \"SELECT coalesce((SELECT price FROM \" . DB_PREFIX . \"product_discount pd2 WHERE pd2.product_id = p.product_id AND pd2.customer_group_id = \'\" . (int)$customer_group_id . \"\' AND pd2.quantity = \'1\' AND ((pd2.date_start = \'0000-00-00\' OR pd2.date_start < NOW()) AND (pd2.date_end = \'0000-00-00\' OR pd2.date_end > NOW())) ORDER BY pd2.priority ASC, pd2.price ASC LIMIT 1), \" .\r\n					\"(SELECT price FROM \" . DB_PREFIX . \"product_special ps WHERE ps.product_id = p.product_id AND ps.customer_group_id = \'\" . (int)$customer_group_id . \"\' AND ((ps.date_start = \'0000-00-00\' OR ps.date_start < NOW()) AND (ps.date_end = \'0000-00-00\' OR ps.date_end > NOW())) ORDER BY ps.priority ASC, ps.price ASC LIMIT 1), \" .\r\n					\"p.price) as realprice \";\r\n		}\r\n		// prostore end	\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\n				$sql .= \" AND pf.filter_id IN (\" . implode(\',\', $implode) . \")\";\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n// prostore\r\n				if(!(int)$this->config->get(\'module_filter_filter_grouptype\')){\r\n					$query1 = $this->db->query(\"SELECT COUNT(DISTINCT f.filter_group_id) as total FROM \" . DB_PREFIX . \"filter_group fg LEFT JOIN \" . DB_PREFIX . \"filter f ON (fg.filter_group_id = f.filter_group_id) where f.filter_id IN(\" . implode(\',\', $implode) . \")\");\r\n					if($query1->num_rows){\r\n						$filtersCount = $query1->row[\'total\'];\r\n					}					\r\n				}\r\n// prostore\r\n	]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"1\"><![CDATA[\r\n$sql .= \" AND p.manufacturer_id = \'\" . (int)$data[\'filter_manufacturer_id\'] . \"\'\";\r\n			]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[\r\n		// prostore\r\n		$sql .= \" GROUP BY p.product_id\";\r\n		$cond = \' HAVING \';\r\n		if(isset($data[\'max_price\']) && $data[\'max_price\'] > 0) {\r\n			$cond = \' AND \';\r\n\r\n			$tempMinPrice = (float)$data[\'min_price\'];\r\n			if (!$this->config->get(\'decimal_place\')) {\r\n				$tempMinPrice = (float)$data[\'min_price\'] -0.5 ;\r\n			}\r\n\r\n	        if ($this->config->get(\'config_tax\') && isset($data[\'filter_tax_class_id\'])) {\r\n	            $tempMinPrice = $tempMinPrice - $this->tax->clearTax( $data[\'min_price\'], $data[\'filter_tax_class_id\'] );\r\n	        }\r\n\r\n			$sql .= \" HAVING realprice >=\" . $this->currency->convert($tempMinPrice,$this->session->data[\'currency\'], $this->config->get(\'config_currency\'));\r\n			\r\n			if(isset($filtersCount) && !(int)$this->config->get(\'module_filter_filter_grouptype\')){\r\n				$sql .= $cond . \" COUNT(DISTINCT f.filter_group_id) = \" . (int)$filtersCount ;	\r\n			}\r\n		}\r\n		if(isset($data[\'max_price\']) && $data[\'max_price\'] > 0) {\r\n			$cond = \' AND \';\r\n\r\n			$tempMaxPrice = (float)$data[\'max_price\'];\r\n			if (!$this->config->get(\'decimal_place\')) {\r\n				$tempMaxPrice = (float)$data[\'max_price\'] + 0.5 ;\r\n			}\r\n\r\n	        if ($this->config->get(\'config_tax\') && isset($data[\'filter_tax_class_id\'])) {\r\n	            $tempMaxPrice = $tempMaxPrice - $this->tax->clearTax( $data[\'max_price\'], $data[\'filter_tax_class_id\'] );\r\n	        }\r\n\r\n			$sql .= \" AND realprice <=\" . $this->currency->convert($tempMaxPrice,$this->session->data[\'currency\'], $this->config->get(\'config_currency\'));\r\n		}\r\n\r\n\r\n		// prostore\r\n	]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search index=\"0\"><![CDATA[\r\nreturn $query->row[\'total\'];\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\n//		return $query->row[\'total\'];\r\n		return $query->num_rows;\r\n	]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getTotalProductSpecials(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n			// prostore	\r\n	public function getNewestProducts($period) {\r\n		$product_data = $this->cache->get(\'product.newest.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . $this->config->get(\'config_customer_group_id\') . \'.\' . $period . \'.\' . date(\"Ymd\"));\r\n\r\n		if (!$product_data) { \r\n			$query = $this->db->query(\"SELECT p.product_id FROM \" . DB_PREFIX . \"product p LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.status = \'1\' AND p.date_available <= NOW() AND p.date_added <= NOW() AND p.date_added > DATE_SUB(CURDATE(), INTERVAL \" . (int)$period . \" DAY) AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' ORDER BY p.date_added DESC\");\r\n			foreach ($query->rows as $result) {\r\n				$product_data[$result[\'product_id\']] = $result[\'product_id\'];\r\n			}\r\n\r\n			$this->cache->set(\'product.newest.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . $this->config->get(\'config_customer_group_id\') . \'.\' . $period . \'.\' . date(\"Ymd\"), $product_data);\r\n		}\r\n		\r\n		if(!$product_data){\r\n			$product_data = array();//Если нет товаров - возвращаем пустой массив.					\r\n		}			\r\n\r\n		return $product_data;\r\n	}\r\n\r\n	public function getAlsoOrderedProducts($products_id,$sortorder,$limit=8) { \r\n		$products_id = implode(\',\', $products_id);\r\n		$data = array();\r\n		$sql = 	\"SELECT * FROM \" . DB_PREFIX . \"order_product WHERE order_id IN(SELECT order_id FROM \" . DB_PREFIX . \"order_product where `product_id` IN (\'\" . $this->db->escape($products_id) . \"\')) AND `product_id` NOT IN  (\'\" . $this->db->escape($products_id) . \"\') GROUP BY `product_id` \";\r\n		if ($sortorder == \'random\') {\r\n			$sql .= \"ORDER BY RAND()\";\r\n		}else{\r\n			$sql .= \"ORDER BY order_id DESC\";\r\n		}\r\n		$sql .= \" LIMIT \" . (int)$limit;\r\n		\r\n		$query = $this->db->query($sql);\r\n		if ($query->num_rows) {\r\n			foreach ($query->rows as  $value) {\r\n				$productInfo = $this->getProduct($value[\'product_id\']);\r\n				if (!$productInfo) {\r\n					continue;\r\n				}\r\n				$data[$value[\'product_id\']] = $productInfo;\r\n			}\r\n		}\r\n		return 	$data ;\r\n	}\r\n	\r\n	public function getBestSellerProductsLS($data) {\r\n		$categories = 0;\r\n		if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n			$categories = implode(\",\",$data[\'filter_category_ids\']);\r\n		}	\r\n		\r\n		$product_data = $this->cache->get(\'product.bestseller.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . $this->config->get(\'config_customer_group_id\') . \'.\' . (int)$data[\'limit\'] . \'.\' . $categories );\r\n\r\n		if (!$product_data) {\r\n			$product_data = array();\r\n\r\n			$sql = \"SELECT op.product_id, SUM(op.quantity) AS total FROM \" . DB_PREFIX . \"order_product op LEFT JOIN `\" . DB_PREFIX . \"order` o ON (op.order_id = o.order_id) LEFT JOIN `\" . DB_PREFIX . \"product` p ON (op.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"product_to_store p2s ON (p.product_id = p2s.product_id) LEFT JOIN \" . DB_PREFIX . \"product_to_category p2c ON (p.product_id = p2c.product_id) WHERE o.order_status_id > \'0\'\";\r\n\r\n\r\n			if (isset($data[\'filter_category_ids\']) && $data[\'filter_category_ids\']) {\r\n				$sql .= \" AND p2c.category_id IN (\" . $categories . \")\";\r\n			}	\r\n			\r\n			$sql .= \" AND p.status = \'1\' AND p.date_available <= NOW() AND p2s.store_id = \'\" . (int)$this->config->get(\'config_store_id\') . \"\' GROUP BY op.product_id ORDER BY total DESC LIMIT \" . (int)$data[\'limit\'];\r\n\r\n			$query = $this->db->query($sql);\r\n\r\n			foreach ($query->rows as $result) {\r\n				$product_data[$result[\'product_id\']] = $this->getProduct($result[\'product_id\']);\r\n			}\r\n\r\n			$this->cache->set(\'product.bestseller.\' . (int)$this->config->get(\'config_language_id\') . \'.\' . (int)$this->config->get(\'config_store_id\') . \'.\' . $this->config->get(\'config_customer_group_id\') . \'.\' . (int)$data[\'limit\'] . \'.\' . $categories , $product_data);\r\n		}\r\n\r\n		return $product_data;\r\n	}\r\n\r\n	public function getProductActions($product_id) {\r\n		$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"product_special WHERE product_id = \'\" . (int)$product_id . \"\' AND ((date_start = \'0000-00-00\' OR date_start < NOW()) AND (date_end = \'0000-00-00\' OR date_end > NOW())) ORDER BY date_end DESC\");\r\n\r\n		return $query->row;\r\n	}\r\n\r\n			// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nif (!empty($data[\'filter_sub_category\'])) {\r\n			]]></search>\r\n			<add position=\"replace\"><![CDATA[\r\nif (!empty($data[\'filter_sub_category\']) && $this->config->get(\'config_seo_pro\')) {\r\n	]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"catalog/model/tool/image.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$image_old = $filename;\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n	// prostore\r\n		if($extension == \'svg\') {\r\n            if ($this->request->server[\'HTTPS\']) {\r\n                return HTTPS_SERVER . \'image/\' . $filename;\r\n            } else {\r\n                return HTTP_SERVER . \'image/\' . $filename;\r\n            }\r\n    	}\r\n	// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n\'cache/\'\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n//WebP Images, author agatha65 agatha65.com, link www.opencart.com/index.php?route=marketplace/extension/info&extension_id=38025\r\n//\"This extension is based on a similar one with another library by my colleague from stick-design.ru\"\r\n//\"All credits goes to V. Bulgakov\"\r\n//WebP Images start\r\n$image_new_webp = \'cachewebp/\' . utf8_substr($filename, 0, utf8_strrpos($filename, \'.\')) . \'-\' . (int)$width . \'x\' . (int)$height . \'.webp\';\r\n//WebP Images end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n$image_new = str_replace(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//WebP Images start\r\n		$gd = gd_info();\r\n		if ($gd[\'WebP Support\']) {\r\n			if (!is_file(DIR_IMAGE . $image_new_webp) || (filectime(DIR_IMAGE . $image_new) > filectime(DIR_IMAGE . $image_new_webp))) {\r\n									\r\n				$path = \'\';\r\n\r\n				$directories = explode(\'/\', dirname($image_new_webp));\r\n\r\n				foreach ($directories as $directory) {\r\n					$path = $path . \'/\' . $directory;\r\n\r\n					if (!is_dir(DIR_IMAGE . $path)) {\r\n						@mkdir(DIR_IMAGE . $path, 0777);\r\n					}\r\n				}\r\n				\r\n				$image_webp = new Image(DIR_IMAGE . $image_old);\r\n				$image_webp->resize($width, $height);\r\n				$image_webp->save_webp(DIR_IMAGE . $image_new_webp);\r\n			}\r\n		}\r\n//WebP Images end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"system/library/image.php\">\r\n		<operation>\r\n			<search><![CDATA[public function save]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//WebP Images, author agatha65 agatha65.com, link www.opencart.com/index.php?route=marketplace/extension/info&extension_id=38025\r\n//\"This extension is based on a similar one with another library by my colleague from stick-design.ru\"\r\n//\"All credits goes to V. Bulgakov\"\r\n//WebP Images start\r\n			public function save_webp($file, $quality = 90) {\r\n				if (is_object($this->image) || is_resource($this->image)) {\r\n					imagewebp($this->image, $file, $quality);\r\n					imagedestroy($this->image);\r\n				}\r\n			}\r\n//WebP Images end\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"system/library/response.php\">\r\n		<operation>\r\n			<search><![CDATA[public function output]]></search>\r\n			<add position=\"before\" ><![CDATA[ 	\r\n//WebP Images, author agatha65 agatha65.com, link www.opencart.com/index.php?route=marketplace/extension/info&extension_id=38025\r\n//\"This extension is based on a similar one with another library by my colleague from stick-design.ru\"\r\n//\"All credits goes to V. Bulgakov\"\r\n//WebP Images start\r\n	public function webpAdd() {\r\n		$gd = gd_info();\r\n		if ($gd[\'WebP Support\']) {\r\n			$uri = \'\';\r\n\r\n			if (isset($_SERVER[\'REQUEST_URI\'])) {\r\n				$uri = $_SERVER[\'REQUEST_URI\'];\r\n			}\r\n\r\n			if (stripos($uri, \'admin\') === false) {\r\n				if (isset($_SERVER[\'HTTP_ACCEPT\']) && isset($_SERVER[\'HTTP_USER_AGENT\'])) {\r\n					if( strpos( $_SERVER[\'HTTP_ACCEPT\'], \'image/webp\' ) !== false ) {\r\n						$re = \'/(\\/cache)(.*)(\\.jpg|\\.png|.jpeg)(?!-)/Ui\';\r\n						$subst = \'$1webp$2.webp\';\r\n						$this->output = preg_replace($re, $subst, $this->output);\r\n					}\r\n				}\r\n			}\r\n		}\r\n	}\r\n//WebP Images end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[$output = $this]]></search>\r\n			<add position=\"before\" ><![CDATA[\r\n//WebP Images start\r\n$this->webpAdd();\r\n//WebP Images end]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"system/library/seopro.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n					} elseif (count($url) > 1) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n					} elseif ($url[0] == \'prostorecatblog_id\') { \r\n						if (!isset($this->request->get[\'lbpath\'])) {\r\n\r\n							$this->request->get[\'lbpath\'] = $url[1];\r\n						} else {\r\n							$this->request->get[\'lbpath\'] = $url[1];\r\n//							$this->request->get[\'lbpath\'] .= \'_\' . $url[1];\r\n						}\r\n\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n			$this->request->get[\'route\'] = \'information/information\';\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n		} elseif (isset($this->request->get[\'news_id\'])) {//prostore\r\n			$this->request->get[\'route\'] = \'extension/module/prostore_news/getnews\';//prostore\r\n		} elseif (isset($this->request->get[\'blog_id\'])) {//prostore\r\n			if(!isset($this->request->get[\'lbpath\'])){$this->request->get[\'lbpath\'] = \'0\';}\r\n\r\n			$this->request->get[\'route\'] = \'extension/module/prostore_blog/getblog\';//prostore\r\n\r\n		} elseif (isset($this->request->get[\'lbpath\'])) {//prostore\r\n\r\n				$this->request->get[\'route\'] = \'extension/module/prostorecat_blog/getcat\';//prostore\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n				case \'product/category\': \r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n				case \'extension/module/prostore_blog/getblog\':\r\n					if (isset($data[\'blog_id\'])) {	\r\n						$tmp = $data;\r\n						$catlessblog = false;\r\n						$data = array();\r\n						if ($this->config->get(\'theme_prostore_blog_path\')) { \r\n							if (isset($tmp[\'lbpath\']) && $tmp[\'lbpath\'] == \'0\') {\r\n								$catlessblog = true; \r\n							}\r\n							$data[\'lbpath\'] = $this->getPathByBlog($tmp[\'blog_id\']);\r\n//							if (!$data[\'lbpath\'] && !$catlessblog) return [$url, $data, $postfix] ;\r\n							if ($catlessblog) {\r\n								$data[\'lbpath\'] = 0;\r\n							}\r\n						}\r\n						$data[\'blog_id\'] = $tmp[\'blog_id\'];\r\n						$seo_pro_utm = preg_replace(\'~\\r?\\n~\', \"\\n\", $this->config->get(\'config_seo_pro_utm\'));\r\n						$allowed_parameters = explode(\"\\n\", $seo_pro_utm);\r\n						foreach($allowed_parameters as $ap) {\r\n							if (isset($tmp[trim($ap)])) {\r\n								$data[trim($ap)] = $tmp[trim($ap)];\r\n							}\r\n						}\r\n					}\r\n					break;\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n				case \'category_id\':\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n				case \'news_id\'://prostore\r\n				case \'blog_id\'://prostore\r\n					$queries[] = $key . \'=\' . (int)$value;\r\n					unset($data[$key]);\r\n					$postfix = true;\r\n					break;			\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\n$queries[] = \'category_id=\' . (int)$category_id;\r\n			]]></search>\r\n			<add position=\"after\" offset=\"3\"><![CDATA[\r\n//prostore start\r\n				case \'lbpath\':\r\n					if ($value) {\r\n						$lbcategories = explode(\'_\', $value);\r\n						if ($lbcategories[0]) {\r\n							array_unshift($lbcategories, \"0\"); //Add blog\'s root in the url\r\n						}\r\n					}else{ //If it is a catless article\r\n						$lbcategories[0] = 0;\r\n					}\r\n		 \r\n					foreach ($lbcategories as $lbcategory) {\r\n						$queries[] = \'prostorecatblog_id=\' . $lbcategory;\r\n					}				\r\n\r\n\r\n					unset($data[$key]);\r\n					break;\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nprivate function getPathByCategory($category_id) {\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n//prostore start\r\n	public function getPathByBlog($blog_id) {\r\n		$blog_id = (int)$blog_id;\r\n		if ($blog_id < 1) return false;\r\n\r\n		static $path = null;\r\n		$query = $this->db->query(\"SELECT category_id FROM \" . DB_PREFIX . \"prostore_blog_to_category WHERE blog_id = \'\" . (int)$blog_id . \"\' ORDER BY main_category DESC LIMIT 1\");\r\n\r\n		$path[$blog_id] = $this->getPathByCategoryLb($query->num_rows ? (int)$query->row[\'category_id\'] : 0);\r\n\r\n		return $path[$blog_id];\r\n	}\r\n\r\n	private function getPathByCategoryLb($category_id) {\r\n		$category_id = (int)$category_id;\r\n		if ($category_id < 1) return false;\r\n\r\n		static $path = null;\r\n\r\n			$max_level = 10;\r\n\r\n			$sql = \"SELECT CONCAT_WS(\'_\'\";\r\n			for ($i = $max_level-1; $i >= 0; --$i) {\r\n				$sql .= \",t$i.category_id\";\r\n			}\r\n			$sql .= \") AS path FROM \" . DB_PREFIX . \"prostorecat_blog t0\";\r\n			for ($i = 1; $i < $max_level; ++$i) {\r\n				$sql .= \" LEFT JOIN \" . DB_PREFIX . \"prostorecat_blog t$i ON (t$i.category_id = t\" . ($i-1) . \".parent_id)\";\r\n			}\r\n			$sql .= \" WHERE t0.category_id = \'\" . (int)$category_id . \"\'\";\r\n\r\n			$query = $this->db->query($sql);\r\n\r\n			$path[$category_id] = $query->num_rows ? $query->row[\'path\'] : false;\r\n\r\n		return $path[$category_id];\r\n	}\r\n//prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\nextension/feed/yandex_feed\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n,\'product/category/popupdetail\'//prostore			\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n	<file path=\"system/library/cart/cart.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n$product_data[] = array(\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore start\r\n			if ($this->config->get(\'theme_prostore_product_cod\')) {\r\n				$product_query->row[\'model\'] = $product_query->row[$this->config->get(\'theme_prostore_product_cod\')];\r\n			}\r\n// prostore end\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\n=> $cart[\'quantity\'],\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\n\'quantity_stock\'		=> $product_query->row[\'quantity\'],// prostore added this\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"system/library/document.php\">\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[\r\npublic function setOgImage($image) {\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"6\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation error=\"skip\">\r\n			<search><![CDATA[private $og_image;]]></search>\r\n			<add position=\"replace\"><![CDATA[]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\nprivate $scripts\r\n			]]></search>\r\n			<add position=\"after\"><![CDATA[\r\nprivate $og_image; // add Open Graph by ocStore\r\n			]]></add>\r\n		</operation>\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getScripts\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// add Open Graph by ocStore\r\npublic function setOgImage($image) {\r\n	$this->og_image = $image;\r\n}\r\n\r\npublic function getOgImage() {\r\n	return $this->og_image;\r\n}\r\n// add Open Graph by ocStore\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"system/library/cart/tax.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\npublic function getRates\r\n			]]></search>\r\n			<add position=\"before\"><![CDATA[\r\n// prostore	\r\n	public function clearTax($value, $tax_class_id) {\r\n		$amount = 0;\r\n\r\n		$tax_rates = $this->getClearRates($value, $tax_class_id);\r\n\r\n		foreach ($tax_rates as $tax_rate) {\r\n			$amount += $tax_rate[\'amount\'];\r\n		}\r\n\r\n		return $amount;\r\n	}\r\n\r\n	public function getClearRates($value, $tax_class_id) {\r\n		$tax_rate_data = array();\r\n\r\n		if (isset($this->tax_rates[$tax_class_id])) {\r\n			foreach ($this->tax_rates[$tax_class_id] as $tax_rate) {\r\n				if (isset($tax_rate_data[$tax_rate[\'tax_rate_id\']])) {\r\n					$amount = $tax_rate_data[$tax_rate[\'tax_rate_id\']][\'amount\'];\r\n				} else {\r\n					$amount = 0;\r\n				}\r\n\r\n				if ($tax_rate[\'type\'] == \'F\') {\r\n					$amount += $tax_rate[\'rate\'];\r\n				} elseif ($tax_rate[\'type\'] == \'P\') {\r\n					$amount += ($value - $value / (1+$tax_rate[\'rate\']/100));\r\n				}\r\n\r\n				$tax_rate_data[$tax_rate[\'tax_rate_id\']] = array(\r\n					\'tax_rate_id\' => $tax_rate[\'tax_rate_id\'],\r\n					\'name\'		=> $tax_rate[\'name\'],\r\n					\'rate\'		=> $tax_rate[\'rate\'],\r\n					\'type\'		=> $tax_rate[\'type\'],\r\n					\'amount\'	  => $amount\r\n				);\r\n			}\r\n		}\r\n\r\n		return $tax_rate_data;\r\n	}\r\n// prostore	\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n	<file path=\"system/config/catalog.php\">\r\n		<operation>\r\n			<search><![CDATA[\r\n	\'controller/*/after\'  => array(\r\n			]]></search>\r\n			<add position=\"replace\" offset=\"2\"><![CDATA[\r\n			]]></add>\r\n		</operation>\r\n	</file> \r\n\r\n</modification>', '1', '2025-11-11 14:47:37');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('11', '12', 'Export/Import Tool (V4.17.9) for OpenCart 3.x', 'Export/Import Tool (V4.17.9) for OpenCart 3.x', 'mhccorp.com', '3.x-4.17', 'https://www.mhccorp.com', '<modification>\n	<name>Export/Import Tool (V4.17.9) for OpenCart 3.x</name>\n	<code>Export/Import Tool (V4.17.9) for OpenCart 3.x</code>\n	<version>3.x-4.17</version>\n	<author>mhccorp.com</author>\n	<link>https://www.mhccorp.com</link>\n	<file path=\"admin/controller/common/column_left.php\">\n		<operation>\n			<search><![CDATA[if ($this->user->hasPermission(\'access\', \'tool/upload\')) {]]></search>\n			<add position=\"before\"><![CDATA[\n			if ($this->user->hasPermission(\'access\', \'extension/export_import\')) {\n				$maintenance[] = array(\n					\'name\'     => $this->language->get(\'text_export_import\'),\n					\'href\'     => $this->url->link(\'extension/export_import\', \'user_token=\' . $this->session->data[\'user_token\'], true),\n					\'children\' => array()\n				);\n			}\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/language/*/common/column_left.php\">\n		<operation>\n			<search><![CDATA[$_[\'text_backup\']]]></search>\n			<add position=\"after\"><![CDATA[\n$_[\'text_export_import\']             = \'Export / Import\';\n			]]></add>\n		</operation>\n	</file>\n</modification>\n', '1', '2025-11-29 07:12:38');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('13', '17', 'DEV-OPENCART.COM - Автогенерация артикула (модели)', 'dev_opencart_com_auto_article_model', 'DEV-OPENCART.COM', '1', 'https://dev-opencart.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>DEV-OPENCART.COM - Автогенерация артикула (модели)</name>\n	<version>1</version>\n	<link>https://dev-opencart.com</link>\n	<author>DEV-OPENCART.COM</author>\n	<code>dev_opencart_com_auto_article_model</code>\n\n	<file path=\"admin/model/catalog/product.php\">\n		<operation>\n			<search><![CDATA[\n				$product_id = $this->db->getLastId();\n			]]></search>\n			<add position=\"after\"><![CDATA[\n				if (isset($data[\'model\'])) {\n					$this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET model = CONCAT (LPAD(manufacturer_id,2,\'00\'), LPAD(product_id,4,\'0000\')) WHERE product_id = \' \" . (int)$product_id . \" \' \" );\n				}\n			]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[\n				$this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET model = \'\" . $this->db->escape($data[\'model\']) . \"\', model = \'\" . $this->db->escape($data[\'model\']) . \"\', upc = \'\" . $this->db->escape($data[\'upc\']) . \"\', ean = \'\" . $this->db->escape($data[\'ean\']) . \"\', jan = \'\" . $this->db->escape($data[\'jan\']) . \"\', isbn = \'\" . $this->db->escape($data[\'isbn\']) . \"\', mpn = \'\" . $this->db->escape($data[\'mpn\']) . \"\', location = \'\" . $this->db->escape($data[\'location\']) . \"\', quantity = \'\" . (int)$data[\'quantity\'] . \"\', minimum = \'\" . (int)$data[\'minimum\'] . \"\', subtract = \'\" . (int)$data[\'subtract\'] . \"\', stock_status_id = \'\" . (int)$data[\'stock_status_id\'] . \"\', date_available = \'\" . $this->db->escape($data[\'date_available\']) . \"\', manufacturer_id = \'\" . (int)$data[\'manufacturer_id\'] . \"\', shipping = \'\" . (int)$data[\'shipping\'] . \"\', price = \'\" . (float)$data[\'price\'] . \"\', points = \'\" . (int)$data[\'points\'] . \"\', weight = \'\" . (float)$data[\'weight\'] . \"\', weight_class_id = \'\" . (int)$data[\'weight_class_id\'] . \"\', length = \'\" . (float)$data[\'length\'] . \"\', width = \'\" . (float)$data[\'width\'] . \"\', height = \'\" . (float)$data[\'height\'] . \"\', length_class_id = \'\" . (int)$data[\'length_class_id\'] . \"\', status = \'\" . (int)$data[\'status\'] . \"\', tax_class_id = \'\" . (int)$data[\'tax_class_id\'] . \"\', sort_order = \'\" . (int)$data[\'sort_order\'] . \"\', date_modified = NOW() WHERE product_id = \'\" . (int)$product_id . \"\'\");\n			]]></search>\n			<add position=\"after\"><![CDATA[\n				if (isset($data[\'model\'])) {\n					$this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET model = CONCAT (LPAD(manufacturer_id,2,\'00\'), LPAD(product_id,4,\'0000\')) WHERE product_id = \' \" . (int)$product_id . \" \' \" );\n				}\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/catalog/product.php\">\n			<operation>\n				<search position=\"replace\"><![CDATA[\n				$this->error[\'model\'] = $this->language->get(\'error_model\');\n				]]></search>\n				<add><![CDATA[\n				 //$this->error[\'model\'] = $this->language->get(\'error_model\');\n				]]></add>\n			</operation>\n	</file>\n</modification>', '1', '2025-12-15 14:20:50');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('20', '24', 'Fast product price editor', 'fast-product-price-editor', 'RoBDeV', '1.0', 'https://www.linkedin.com/in/robert-palandzhian-a11098126/', '﻿<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r<modification>\r	<name>Fast product price editor</name>\r	<code>fast-product-price-editor</code>\r	<version>1.0</version>\r	<author>RoBDeV</author>\r	<link>https://www.linkedin.com/in/robert-palandzhian-a11098126/</link>\r\r	<file path=\"admin/view/template/common/header.twig\">\r		<operation>\r			<search><![CDATA[{% for script in scripts %}]]></search>\r			<add position=\"before\">\r				<![CDATA[\r			<script src=\"view/javascript/price_editor.js\"></script>\r			]]>\r			</add>\r		</operation>\r		<operation>\r			<search><![CDATA[{% for style in styles %}]]></search>\r			<add position=\"before\">\r				<![CDATA[\r			<link href=\"view/stylesheet/price_editor.css\" rel=\"stylesheet\" media=\"screen\" />\r			]]>\r			</add>\r		</operation>\r	</file>\r\r	<file path=\"admin/view/template/catalog/product_list.twig\">\r		<operation>\r			<search><![CDATA[<td class=\"text-right\">{% if product.special %}]]></search>\r			<add position=\"replace\">\r				<![CDATA[<td class=\"text-right price_column relative\" data-price-type=\"price\" data-user-token=\"{{ user_token }}\" data-price-val=\"{{ product.price_val }}\">{% if product.special %}]]>\r			</add>\r		</operation>\r		<operation>\r			<search><![CDATA[{{ product.price }}]]></search>\r			<add position=\"replace\">\r				<![CDATA[<div class=\"pricing\">{{ product.price }}</div>]]>\r			</add>\r		</operation>\r	</file>\r\r	<file path=\"admin/controller/catalog/product.php\">\r		<operation>\r			<search><![CDATA[$this->currency->format($result[\'price\'], $this->config->get(\'config_currency\')),]]></search>\r			<add position=\"after\">\r				<![CDATA[\'price_val\' => $result[\'price\'],]]>\r			</add>\r		</operation>\r		<operation>\r			<search><![CDATA[public function autocomplete()]]></search>\r			<add position=\"before\">\r				<![CDATA[\r			  public function changePrice(){\r				  $json = array();\r				  $this->load->model(\'catalog/product\');\r\r				  if(!isset($this->request->post[\'product_id\']) || !isset($this->request->post[\'new_price\']) || !isset($this->request->post[\'price_type\'])){\r					  $json[\'error\'] = \'Not enough data!\';\r				  }\r\r				  if(!isset($json[\'error\'])){\r					  $data = $this->request->post;\r					  $this->model_catalog_product->changePrice($data[\'product_id\'], $data[\'new_price\'], $data[\'price_type\']);\r\r					  $json[\'new_price_val\'] = $data[\'new_price\'];\r					  $json[\'new_price\'] = $this->currency->format($data[\'new_price\'], $this->config->get(\'config_currency\'));\r					  $json[\'success\'] = true;\r				  }\r\r				  $this->response->addHeader(\'Content-Type: application/json\');\r				  $this->response->setOutput(json_encode($json));\r			  }\r			]]>\r			</add>\r		</operation>\r	</file>\r\r	<file path=\"admin/model/catalog/product.php\">\r		<operation>\r			<search><![CDATA[public function addProduct]]></search>\r			<add position=\"before\">\r				<![CDATA[\r			  public function changePrice($product_id, $new_price, $price_type){\r				  $this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET \" . $price_type . \" = \" . $new_price . \" WHERE product_id = \" . (int)$product_id);\r			  }\r\r			]]>\r			</add>\r		</operation>\r	</file>\r</modification>', '1', '2026-01-09 15:23:30');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('37', '50', 'Опции товаров по умолчанию for Смарт Точка', 'defaultselectedoptions', 'Gimka2281', '1.0.0', '', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>Опции товаров по умолчанию for Смарт Точка</name>\n    <version>1.0.0</version>\n    <code>defaultselectedoptions</code>\n    <author>Gimka2281</author>\n	<link></link>\n\n    <file path=\"admin/model/catalog/product.php\">\n        <operation>\n            <search><![CDATA[\'weight_prefix\'           => $product_option_value[\'weight_prefix\']]]></search>\n            <add position=\"after\"><![CDATA[\'is_default\'               => $product_option_value[\'is_default\'],]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[weight_prefix = \'\" . $this->db->escape($product_option_value[\'weight_prefix\']) . \"\',]]></search>\n            <add position=\"replace\"><![CDATA[weight_prefix = \'\" . $this->db->escape($product_option_value[\'weight_prefix\']) . \"\', is_default = \'\" . $this->db->escape(isset($product_option_value[\'is_default\']) ? $product_option_value[\'is_default\'] : 0) . \"\',]]></add>\n        </operation>\n    </file>\n\n    <file path=\"admin/controller/catalog/product.php\">\n        <operation>\n            <search><![CDATA[\'weight_prefix\'           => $product_option_value[\'weight_prefix\'],]]></search>\n            <add position=\"after\"><![CDATA[\'is_default\'               => $product_option_value[\'is_default\'],]]></add>\n        </operation>\n    </file>\n\n    <file path=\"admin/view/template/catalog/product_form.twig\">\n\n        <operation>\n            <search index=\"0\"><![CDATA[<td class=\"text-right\">{{ entry_weight }}</td>]]></search>\n            <add position=\"after\"><![CDATA[<td class=\"text-right\">Default</td>]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[html += \'        <td class=\"text-right\">{{ entry_weight }}</td>\';]]></search>\n            <add position=\"after\"><![CDATA[\n                html += \'        <td class=\"text-right\">Default</td>\';\n            ]]></add>\n        </operation>\n\n        <operation>\n			<search><![CDATA[<td class=\"text-right\"><button type=\"button\" onclick=\"$(this).tooltip(\'destroy\');$(\'#option-value-row{{ option_value_row }}\').remove();\" data-toggle=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>]]></search>\n            <add position=\"before\"><![CDATA[\n\n            <td class=\"text-center\">\n                <div class=\"checkbox\">\n                    <label style=\"display: block\">\n                        <input type=\"checkbox\" name=\"product_option[{{ option_row }}][product_option_value][{{ option_value_row }}][is_default]\" value=\"1\" {{ \'1\' == product_option_value.is_default ? \'checked=\"checked\"\' : \'\' }} onclick=\"SetSel(this);\" />\n                    </label>\n                </div>\n            </td>\n\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[html += \'  <td class=\"text-left\"><button type=\"button\" onclick=\"$(this).tooltip(\\\'destroy\\\');$(\\\'#option-value-row\' + option_value_row + \'\\\').remove();\" data-toggle=\"tooltip\" rel=\"tooltip\" title=\"{{ button_remove }}\" class=\"btn btn-danger\"><i class=\"fa fa-minus-circle\"></i></button></td>\';]]></search>\n\n            <add position=\"before\"><![CDATA[\n\n            html += \'<td class=\"text-center\">\';\n                html += \'<div class=\"checkbox\">\';\n                    html += \'<label>\';\n                        html += \'<input type=\"checkbox\" name=\"product_option[\' + option_row + \'][product_option_value][\' + option_value_row + \'][is_default]\" value=\"1\" value=\"1\" onclick=\"SetSel(this);\" />\';\n                    html += \'</label>\';\n                html += \'</div>\';\n            html += \'</td>\';\n\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[<td colspan=\"7\"></td>]]></search>\n            <add position=\"replace\"><![CDATA[<td colspan=\"8\"></td>]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[<script type=\"text/javascript\"><!--]]></search>\n            <add position=\"after\"><![CDATA[\n\n            function SetSel(elem)\n            {\n                var tbody           = elem.parentNode.parentNode.parentNode.parentNode.parentNode;\n                var elems           = tbody.getElementsByTagName(\"input\");\n                var currentState    = elem.checked;\n                var elemsLength     = elems.length;\n\n                for(i=0; i<elemsLength; i++)\n                {\n                    if(elems[i].type === \"checkbox\")\n                    {\n                       elems[i].checked = false;\n                    }\n                }\n\n                elem.checked = currentState;\n            }\n\n\n            ]]></add>\n        </operation>\n    </file>\n\n\n    <file path=\"catalog/model/catalog/product.php\">\n        <operation>\n            <search><![CDATA[\'weight_prefix\'           => $product_option_value[\'weight_prefix\'],]]></search>\n            <add position=\"after\"><![CDATA[\'is_default\'           => $product_option_value[\'is_default\'],]]></add>\n        </operation>\n    </file>\n\n    <file path=\"catalog/controller/product/product.php\">\n        <operation>\n            <search><![CDATA[\'price_prefix\'            => $option_value[\'price_prefix\'],]]></search>\n            <add position=\"after\"><![CDATA[\'is_default\'            => $option_value[\'is_default\'],]]></add>\n        </operation>\n    </file>\n\n    <file path=\"catalog/view/theme/prostore/template/product/product.twig\">\n        <operation>\n            <search><![CDATA[<option value=\"{{ option_value.product_option_value_id }}\">{{ option_value.name }}]]></search>\n            <add position=\"replace\"><![CDATA[<option value=\"{{ option_value.product_option_value_id }}\" {{ \'1\' == option_value.is_default ? \'selected\' : \'\' }}>{{ option_value.name }}]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[<input class=\"ui-check__input\" type=\"radio\" name=\"option[{{ option.product_option_id }}]\" value=\"{{ option_value.product_option_value_id }}\">]]></search>\n            <add position=\"replace\"><![CDATA[<input class=\"ui-check__input\" type=\"radio\" name=\"option[{{ option.product_option_id }}]\" value=\"{{ option_value.product_option_value_id }}\" {{ \'1\' == option_value.is_default ? \'checked=\"checked\"\' : \'\' }} />]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[<input class=\"ui-check__input\" type=\"checkbox\" name=\"option[{{ option.product_option_id }}][]\" value=\"{{ option_value.product_option_value_id }}\">]]></search>\n            <add position=\"replace\"><![CDATA[<input class=\"ui-check__input\" type=\"checkbox\" name=\"option[{{ option.product_option_id }}][]\" value=\"{{ option_value.product_option_value_id }}\" {{ \'1\' == option_value.is_default ? \'checked=\"checked\"\' : \'\' }} />]]></add>\n        </operation>\n    </file>\n\n    <file path=\"catalog/controller/checkout/cart.php\">\n        <operation>\n            <search><![CDATA[foreach ($product_options as $product_option) {]]></search>\n            <add position=\"before\"><![CDATA[\n            $default_options = [];\n            ]]>\n            </add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[$json[\'error\'][\'option\'][$product_option[\'product_option_id\']] = sprintf($this->language->get(\'error_required\'), $product_option[\'name\']);]]></search>\n            <add position=\"replace\"><![CDATA[\n\n                    foreach($product_option[\'product_option_value\'] as $row => $val)\n                    {\n                        if(1 == $val[\'is_default\'])\n                        {\n                            if(\'checkbox\' == $product_option[\'type\'])\n                            {\n                                $_default_val = [$val[\'product_option_value_id\']];\n                            }\n                            else\n                            {\n                                $_default_val = (int)$val[\'product_option_value_id\'];\n                            }\n\n                            $default_options[$product_option[\'product_option_id\']] = $_default_val;\n                        }\n                    }\n\n                    if(0 === count($default_options))\n                    {\n                        $json[\'error\'][\'option\'][$product_option[\'product_option_id\']] = sprintf($this->language->get(\'error_required\'), $product_option[\'name\']);\n                    }\n\n            ]]></add>\n        </operation>\n\n        <operation>\n            <search><![CDATA[if (isset($this->request->post[\'recurring_id\'])) {]]></search>\n            <add position=\"before\"><![CDATA[\n\n            if(count($default_options) > 0)\n            {\n                $filtered_default_options   = array_filter($default_options);\n                $new_option                 = array_merge($option, $filtered_default_options);\n                //$option                   = array_filter($new_option);\n                $option                     = $default_options;\n            }\n\n            ]]></add>\n        </operation>\n\n    </file>\n\n</modification>', '1', '2026-01-11 21:24:23');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('38', '52', 'Localcopy OCMOD Install Fix', 'localcopy-3', 'https://ocmod.net', '1.0', 'https://ocmod.net', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n  <name>Localcopy OCMOD Install Fix</name>\n  <code>localcopy-3</code>\n  <version>1.0</version>\n  <author>https://ocmod.net</author>\n  <link>https://ocmod.net</link>\n\n  <file path=\"admin/controller/marketplace/install.php\">\n	<operation>\n      <search>\n        <![CDATA[if ($safe) {]]>\n      </search>\n      <add position=\"before\">\n        <![CDATA[		\n		    $safe = true;\n		    ]]>\n      </add>\n    </operation>\n    <operation>\n      <search>\n        <![CDATA[if (is_dir($file) && !is_dir($path)) {]]>\n      </search>\n      <add position=\"before\">\n        <![CDATA[		\n			  if ($path == \'\') {\n  				$app_root = explode(\'/\',DIR_APPLICATION);\n  				unset($app_root[count($app_root)-2]);\n  				$app_root = implode(\'/\',$app_root);\n  				$path = $app_root . $destination;\n			  }\n		    ]]>\n      </add>\n    </operation>\n  </file> \n</modification>\n', '1', '2026-01-31 12:17:08');
INSERT INTO `oc_modification` (`modification_id`, `extension_install_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES ('45', '60', 'Adding support for install.php, install.sql when installing exte', 'EIE001', 'Nik Chankov', '1.0', 'http://nik.chankov.net/opencart', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <code>EIE001</code>\n    <name>Adding support for install.php, install.sql when installing extensions</name>\n    <version>1.0</version>\n    <email>opencart@chankov.net</email>\n	<link>http://nik.chankov.net/opencart</link>\n    <author>Nik Chankov</author>\n	\n	<file path=\"admin/controller/marketplace/install.php\">\n        <operation>\n            <search trim=\"true\" index=\"0\"><![CDATA[\n        		$json[\'next\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'marketplace/install/remove\', \'user_token=\' . $this->session->data[\'user_token\'], true));\n            ]]></search>\n            <add position=\"after\" trim=\"false\" offset=\"0\"><![CDATA[\n		  		$json[\'text\'] = $this->language->get(\'text_sql\');\n		  		$json[\'next\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'marketplace/install/sql\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&extension_install_id=\' . $extension_install_id, true));\n            ]]></add>\n        </operation>\n		<operation>\n            <search trim=\"true\" index=\"0\"><![CDATA[\n          		public function remove() {\n            ]]></search>\n            <add position=\"before\" trim=\"false\" offset=\"0\"><![CDATA[\n				public function php() {\n					$this->load->language(\'marketplace/install\');\n					$json = array();\n					if (isset($this->request->get[\'extension_install_id\'])) {\n						$extension_install_id = $this->request->get[\'extension_install_id\'];\n					} else {\n						$extension_install_id = 0;\n					}\n					if (!$this->user->hasPermission(\'modify\', \'marketplace/install\')) {\n						$json[\'error\'] = $this->language->get(\'error_permission\');\n					}\n					if (!isset($this->session->data[\'install\'])) {\n						$json[\'error\'] = $this->language->get(\'error_directory\');\n					} elseif (!is_dir(DIR_UPLOAD . \'tmp-\' . $this->session->data[\'install\'] . \'/\')) {\n						$json[\'error\'] = $this->language->get(\'error_directory\');\n					}\n					if (!$json) {\n						$file = DIR_UPLOAD . \'tmp-\' . $this->session->data[\'install\'] . \'/install.php\';\n						if (is_file($file)) {\n							try {\n								include($file);\n							} catch(Exception $exception) {\n								$json[\'error\'] = sprintf($this->language->get(\'error_exception\'), $exception->getCode(), $exception->getMessage(), $exception->getFile(), $exception->getLine());\n							}\n						}\n					}\n					if (!$json) {\n						$json[\'text\'] = $this->language->get(\'text_remove\');\n						$json[\'next\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'marketplace/install/remove\', \'user_token=\' . $this->session->data[\'user_token\'], true));\n					}\n					$this->response->addHeader(\'Content-Type: application/json\');\n					$this->response->setOutput(json_encode($json));\n				}\n\n				public function sql() {\n					$this->load->language(\'marketplace/install\');\n					$json = array();\n					if (isset($this->request->get[\'extension_install_id\'])) {\n						$extension_install_id = $this->request->get[\'extension_install_id\'];\n					} else {\n						$extension_install_id = 0;\n					}\n					if (!$this->user->hasPermission(\'modify\', \'marketplace/install\')) {\n						$json[\'error\'] = $this->language->get(\'error_permission\');\n					}\n					if (!isset($this->session->data[\'install\'])) {\n						$json[\'error\'] = $this->language->get(\'error_directory\');\n					} elseif (!is_dir(DIR_UPLOAD . \'tmp-\' . $this->session->data[\'install\'] . \'/\')) {\n						$json[\'error\'] = $this->language->get(\'error_directory\');\n					}\n\n					if (!$json) {\n						$file = DIR_UPLOAD . \'tmp-\' . $this->session->data[\'install\'] . \'/install.sql\';\n						if (is_file($file)) {\n							$lines = file($file);\n							if ($lines) {\n								try {\n									$sql = \'\';\n									foreach ($lines as $line) {\n										if ($line && (substr($line, 0, 2) != \'--\') && (substr($line, 0, 1) != \'#\')) {\n											$sql .= $line;\n											if (preg_match(\'/;\\s*$/\', $line)) {\n												$sql = str_replace(\" `oc_\", \" `\" . DB_PREFIX, $sql);\n												$this->db->query($sql);\n												$sql = \'\';\n											}\n										}\n									}\n								} catch(Exception $exception) {\n									$json[\'error\'] = sprintf($this->language->get(\'error_exception\'), $exception->getCode(), $exception->getMessage(), $exception->getFile(), $exception->getLine());\n								}\n							}					\n						}\n					}\n\n					if (!$json) {\n						$json[\'text\'] = $this->language->get(\'text_php\');\n						$json[\'next\'] = str_replace(\'&amp;\', \'&\', $this->url->link(\'marketplace/install/php\', \'user_token=\' . $this->session->data[\'user_token\'] . \'&extension_install_id=\' . $extension_install_id, true));\n					}\n\n					$this->response->addHeader(\'Content-Type: application/json\');\n					$this->response->setOutput(json_encode($json));\n				}\n            ]]></add>\n        </operation>\n    </file>\n	\n	<file path=\"admin/language/en-gb/marketplace/install.php\">\n        <operation>\n            <search trim=\"true\" index=\"0\"><![CDATA[\n          		$_[\'text_remove\']      = \'Removing temporary files!\';\n            ]]></search>\n            <add position=\"after\" trim=\"false\" offset=\"0\"><![CDATA[\n		  		$_[\'text_sql\']             = \'Running SQL!\';\n		  		$_[\'text_php\']             = \'Running PHP!\';\n            ]]></add>\n        </operation>\n	</file>\n</modification>', '1', '2026-02-09 15:07:50');
INSERT INTO `oc_module` (`module_id`, `name`, `code`, `setting`) VALUES ('36', 'Главный слайдер', 'prostore_main_slider', '{\"name\":\"\\u0413\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 \\u0441\\u043b\\u0430\\u0439\\u0434\\u0435\\u0440\",\"autoplay\":\"0\",\"speed\":\"2\",\"slide_width\":\"full\",\"slide_fade\":\"0\",\"img_link\":\"1\",\"resizable\":\"1\",\"status\":\"1\",\"slider_image\":[{\"language\":{\"1\":{\"image\":\"catalog\\/MainBanner\\/smarttochka.png\",\"width_pc\":\"940\",\"height_pc\":\"370\",\"image2\":\"catalog\\/MainBanner\\/Frame407.png\",\"width_mobile\":\"720\",\"height_mobile\":\"720\",\"title\":\"\",\"slider_text\":\"\",\"btn_text\":\"\",\"text_color\":\"2\",\"link\":\"https:\\/\\/smtochka.ru\\/smartfony\\/iphone\\/iphone-17-pro-max\\/iphone-17-pro-max-256-gb-kosmicheskij-oranzhevyj-simesim\",\"sort_order\":\"1\",\"position\":\"1\",\"full\":\"1\"}}},{\"language\":{\"1\":{\"image\":\"catalog\\/MainBanner\\/MainBanner2-1.png\",\"width_pc\":\"940\",\"height_pc\":\"370\",\"image2\":\"catalog\\/MainBanner\\/MainBannerMini-2.png\",\"width_mobile\":\"720\",\"height_mobile\":\"720\",\"title\":\"\",\"slider_text\":\"\",\"btn_text\":\"\",\"text_color\":\"2\",\"link\":\"https:\\/\\/t.me\\/SmartTochka_Lipetsk\",\"sort_order\":\"2\",\"position\":\"1\",\"full\":\"1\"}}},{\"language\":{\"1\":{\"image\":\"catalog\\/MainBanner\\/MainBanner2-2.png\",\"width_pc\":\"940\",\"height_pc\":\"370\",\"image2\":\"catalog\\/MainBanner\\/MainBannerMini-3.png\",\"width_mobile\":\"720\",\"height_mobile\":\"720\",\"title\":\"\",\"slider_text\":\"\",\"btn_text\":\"\",\"text_color\":\"2\",\"link\":\"https:\\/\\/t.me\\/SmartTochka_Lipetsk\",\"sort_order\":\"3\",\"position\":\"1\",\"full\":\"1\"}}},{\"language\":{\"1\":{\"image\":\"catalog\\/MainBanner\\/Frame_403_1.svg\",\"width_pc\":\"940\",\"height_pc\":\"370\",\"image2\":\"catalog\\/MainBanner\\/Frame392(4).svg\",\"width_mobile\":\"940\",\"height_mobile\":\"370\",\"title\":\"\",\"slider_text\":\"\",\"btn_text\":\"\",\"text_colo