INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '50', '1', 'Широкоугольный \nСверхширокоугольный \nТелефото');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '53', '1', 'Настраиваемый объектив по умолчанию (Fusion Main) \nКрышка объектива из сапфирового стекла \nАдаптивная вспышка True Tone \nDeep Fusion \nSmart HDR 5 \nПортреты нового поколения с фокусировкой и контролем глубины \nПортретное освещение с шестью эффектами \nНочной режим \nПанорама (до 63 МП) \nФотографические стили последнего поколения \nПространственные фотографии \n48-мегапиксельная макросъемка \nProRAW \nШирокий цветовой охват для фотографий и живых фотографий \nКоррекция объектива (Fusion Ultra Wide) \nРасширенная коррекция эффекта красных глаз \nГеотеггинг фотографий');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '56', '1', '4K Dolby Vision с частотой 24, 25, 30, 60, 100 или 120 кадров/﻿с \n1080p Dolby Vision с частотой 25, 30, 60 или 120 кадров/﻿с \n720p Dolby Vision с частотой 30 кадров/﻿с \nКинематографический режим 4K Dolby Vision до 30 кадров/﻿с \nРежим Action 2,8K Dolby Vision до 60 кадров/﻿с \nПространственное видео 1080p с частотой 30 кадров/﻿с');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '57', '1', 'HD-видео 1080р c частотой 120 кадров/﻿с или 240 кадров/﻿с');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '58', '1', 'Цифровой 15х');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '59', '1', 'ProRes RAW \nСистема кодирования цвета Академии \nApple Log 2 \nПоддержка генлока \nМакровидеозапись, включая замедленную и покадровую съемку \nДвойной захват до 4K Dolby Vision со скоростью 30 кадров в секунду \nПокадровая видеосъемка со стабилизацией \nНочной режим покадровой съемки \nQuickTake видео до 4K Dolby Vision со скоростью 60 кадров в секунду \nОптическая стабилизация изображения со сдвигом матрицы второго поколения для видео (Fusion Main) \nОптическая стабилизация изображения со сдвигом 3D-сенсора и автофокусировка для видео (Fusion Telephoto) \nАудио зум \nTrue Tone вспышка \nКинематографическая стабилизация видео (4K, 1080p и 720p) \nНепрерывное видео с автофокусом \nДелайте фотографии с разрешением 8 МП и одновременно записывайте видео 4K \nМасштабирование воспроизведения \nПространственная аудио- и стереозапись \nЧетыре микрофона студийного качества \nСнижение шума ветра \nАудио микс');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '71', '1', '18 Мп');
INSERT INTO `oc_product_attribute` (`product_id`, `attribute_id`, `language_id`, `text`) VALUES ('57', '72', '1', 'ƒ/1.9');
