INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('1', '171', '0', 'test', '', 'czxdvdxvfxbvnbnbnm,klklklklklklkkklkl', '2022-03-10 19:14:38', '0000-00-00 00:00:00', '1', '0', '', '0000-00-00');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('2', '169', '0', 'Илья', '', 'Сколько слоев материала?', '2022-03-30 14:25:27', '0000-00-00 00:00:00', '1', '0', 'Здравствуйте, Илья. По бортам два слоя ПВХ. Верх и низ - один усиленный слой армированного ПВХ.', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('3', '196', '0', 'Илья', '', 'Какую лучше брать длину ? На что она влияет ?', '2022-04-08 14:53:37', '0000-00-00 00:00:00', '1', '0', 'Чем длиннее доска, тем она устойчивее. Например, в условиях волнения в море лучше использовать размер 11,6. Для спокойных пресноводных водоемов отлично подойдет размер 10,6. На доске короче 10,3 футов передвигаться стоя взрослому человеку уже затруднительно.', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('4', '172', '0', 'Алексей Васильевич', '', 'Нет ПС5, зато есть геймпад. Это определённо лучшее вложение в будущее?', '2022-04-27 16:31:27', '0000-00-00 00:00:00', '1', '0', 'Мы рады, что вы довольны своим выбором!', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('5', '172', '0', 'Александр Иванов', '', 'Для использования полного функционала советую программу DS4Windows?', '2022-04-27 16:31:55', '0000-00-00 00:00:00', '1', '0', 'Спасибо что уделили время и оставили отзыв! Благодарим, что выбрали Apple!', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('6', '172', '0', 'Маргарита', '', 'Ну дуал сенс есть дуал сенс, задний корпус все равно придется чистить раз в неделю влажными салфетками, как бы руки вы не мыли.', '2022-04-27 16:32:16', '0000-00-00 00:00:00', '1', '0', 'Получил космик ред, цвет более похож на малиновый.', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('7', '197', '0', 'Елена', '', 'Воздержно ли на данную доску крепит парус?', '2022-04-27 19:44:02', '0000-00-00 00:00:00', '1', '0', 'Здравствуйте, Елена. В продаже встречаются специальные паруса для сап-досок, которые можно с помощью ремней установить на любом надувном сапе, в том числе и на данной модели.', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('8', '197', '0', 'Павел', '', 'Где размеры доски?', '2022-04-27 19:48:58', '0000-00-00 00:00:00', '1', '0', 'Здравствуйте, размеры доски: 320*82*15см.', '2022-04-27');
INSERT INTO `oc_prostore_faq` (`faq_id`, `product_id`, `customer_id`, `author`, `email`, `text`, `date_added`, `date_modified`, `status`, `store_id`, `text_admin_answer`, `answer_date_added`) VALUES ('9', '195', '0', 'Светлана', '', 'Подскажите пожалуйста какое крепление у плавника?', '2022-04-27 19:49:35', '0000-00-00 00:00:00', '1', '0', 'Здравствуйте, крепление Slide.', '2022-04-27');
