INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('1', '0', 'Сергей', '', 'Это определённо лучшее вложение в будущее. За 5 месяцев он не начал скрипеть, не появились какие-либо проблемы с кнопками, стиками, к моему ноутбуку и другим устройствам подключается стабильно. Для использования полного функционала советую программу DS4Windows.', '4', '5', '4', '5', '5', '1', '0', '2022-03-13 18:59:37', '0000-00-00 00:00:00', 'Получил космик ред, цвет более похож на малиновый. ', '2022-04-27');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('2', '0', 'Елена Михайловна', '', 'Получил космик ред, цвет более похож на малиновый. Ну дуал сенс есть дуал сенс, задний корпус всеравно придется чистить раз в неделю влажными салфетками, как бы руки вы не мыли.', '3', '5', '2', '3', '5', '1', '0', '2022-03-13 19:13:20', '2022-04-27 11:16:38', '', '0000-00-00');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('3', '0', 'Петр', 'mail@mail.ru', 'Для использования полного функционала советую программу DS4Windows. Ну дуал сенс есть дуал сенс, задний корпус всеравно придется чистить раз в неделю влажными салфетками, как бы руки вы не мыли.', '5', '4', '5', '4', '5', '1', '0', '2022-03-15 11:20:29', '2022-03-15 11:28:28', ' Это определённо лучшее вложение в будущее.', '2022-04-27');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('4', '0', 'Alex', 'mail@mail.ru', 'Доставлено на 2 дня раньше, хорошо упаковано, все на уровне, спасибо!', '5', '4', '3', '5', '5', '1', '0', '2022-03-26 10:53:24', '2022-04-27 11:17:36', '', '0000-00-00');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('5', '0', 'Елена Михайловна ', '', 'Пользуемся 4 дня. Покупала сыну на замену Мейзу нот 8. Пока все хорошо, ребёнок доволен, доставка быстрая, чехол в подарок. Дальше посмотрим как будет себя вести данная модель', '4', '5', '4', '5', '5', '1', '0', '2022-04-27 11:08:39', '2022-04-27 11:12:42', '', '0000-00-00');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('6', '0', 'Оксана', '', 'Курьер вез 2 заказа, но почему-то про второй вспомнил только после моего вопроса и долго соображал, что его тоже нужно отдать мне, хотя других адресов и заказов у него не было', '3', '5', '5', '5', '5', '1', '0', '2022-04-27 11:09:50', '2022-04-27 11:12:42', '', '0000-00-00');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('7', '0', 'Алексей Владимирович', '', ' Все отлично, только в заказе были 3 маркера, которые засохли и не писали . После спирта вроде пишут, но не так , как остальные) Все отлично, только в заказе были 3 маркера, которые засохли и не писали . После спирта вроде пишут, но не так , как остальные)', '5', '5', '5', '5', '5', '1', '0', '2022-04-27 11:10:30', '0000-00-00 00:00:00', 'Ну дуал сенс есть дуал сенс, задний корпус всеравно придется чистить раз в неделю влажными салфетками, как бы руки вы не мыли.', '2022-04-27');
INSERT INTO `oc_prostore_review_shop` (`review_id`, `customer_id`, `author`, `email`, `text`, `r1`, `r2`, `r3`, `r4`, `r5`, `status`, `store_id`, `date_added`, `date_modified`, `text_admin_answer`, `answer_date_added`) VALUES ('8', '0', 'Дима', '', 'Нет ПС5, зато есть геймпад. Это определённо лучшее вложение в будущее. За 5 месяцев он не начал скрипеть, не появились какие-либо проблемы с кнопками, стиками, к моему ноутбуку и другим устройствам подключается стабильно. Для использования полного функционала советую программу DS4Windows.', '5', '4', '5', '5', '5', '1', '0', '2022-04-27 11:10:45', '0000-00-00 00:00:00', 'Получил космик ред, цвет более похож на малиновый. Ну дуал сенс есть дуал сенс, задний корпус всеравно придется чистить раз в неделю влажными салфетками, как бы руки вы не мыли.', '2022-04-27');
