INSERT INTO `oc_setting` (`setting_id`, `store_id`, `code`, `key`, `value`, `serialized`) VALUES ('65174', '0', 'theme_prostore', 'theme_prostore_custom_ol', '{\"1\":{\"o0\":\"\\u0410\\u043a\\u043a\\u0430\\u0443\\u043d\\u0442\",\"o1\":\"\\u041a\\u0430\\u0440\\u0442\\u0430 \\u0441\\u0430\\u0439\\u0442\\u0430\",\"o2\":\"\\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\\u044b\",\"o3\":\"\\u041f\\u0430\\u0440\\u0442\\u043d\\u0435\\u0440\\u0441\\u043a\\u0430\\u044f \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c\\u0430\",\"o4\":\"\\u041f\\u043e\\u0438\\u0441\\u043a\",\"o5\":\"\\u041f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u0442\\u0435\\u043b\\u0438\",\"o6\":\"\\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435\",\"o7\":\"\\u0418\\u0437\\u0431\\u0440\\u0430\\u043d\\u043d\\u043e\\u0435\",\"o8\":\"\\u041a\\u043e\\u0440\\u0437\\u0438\\u043d\\u0430\",\"o9\":\"\\u041e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0437\\u0430\\u043a\\u0430\\u0437\\u0430\",\"o10\":\"\\u0412\\u043e\\u0437\\u0432\\u0440\\u0430\\u0442\\u044b\",\"o11\":\"\\u041f\\u043e\\u0434\\u0430\\u0440\\u043e\\u0447\\u043d\\u044b\\u0435 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0438\\u043a\\u0430\\u0442\\u044b\",\"o12\":\"\\u0410\\u043a\\u0446\\u0438\\u0438\",\"o13\":\"\\u041d\\u043e\\u0432\\u043e\\u0441\\u0442\\u0438\",\"o14\":\"\\u0411\\u043b\\u043e\\u0433\",\"o15\":\"\\u041e\\u0442\\u0437\\u044b\\u0432\\u044b \\u043e \\u043c\\u0430\\u0433\\u0430\\u0437\\u0438\\u043d\\u0435\",\"o16\":\"\\u0411\\u043b\\u043e\\u0433.\\u041a\\u0430\\u0442\\u0435\\u0433\\u043e\\u0440\\u0438\\u0438\"}}', '1');
INSERT INTO `oc_setting` (`setting_id`, `store_id`, `code`, `key`, `value`, `serialized`) VALUES ('65175', '0', 'theme_prostore', 'theme_prostore_css', '.header__desktop {\r\n     .header__logo  {\r\n       flex: 0 0 16rem;\r\n       img {\r\n         max-height: none;\r\n       }\r\n    }\r\n}\r\n.header__desktop {\r\n.header__logo img {\r\n  max-height: none;\r\n}\r\n}\r\n\r\n.header__group {\r\n  .header__action {\r\n    [aria-label=&quot;Сравнение&quot;] {\r\n      display: none;\r\n    }\r\n    span.header__action-line {\r\n      display: none;\r\n    }\r\n  }\r\n  .header__cart {\r\n    .header__cart-btn {\r\n      span.header__cart-total {\r\n        \r\n      }\r\n      span.header__cart-total {\r\n        #cart-total {\r\n          .cart-total-text {\r\n            display: none;\r\n          }\r\n          \r\n          .cart-total-counter {\r\n          }\r\n          \r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n@media (min-device-width: 1199px) {\r\n    .header__cart-btn svg {\r\n        margin: 0 0 0 0;\r\n        display: block;\r\n    }\r\n}\r\n\r\n.header__desktop {\r\n    .header__cart-btn {\r\n         padding: 0.8rem 0rem 0.8rem 1.65rem;\r\n\r\n    }\r\n}\r\n\r\n@media (min-device-width: 1199px) {\r\n    .header__cart-total mark {\r\n        position: relative;\r\n        top: 1rem;\r\n        right: 1rem;\r\n        width: 1.7rem;\r\n        height: 1.7rem;\r\n        border-radius: 50%;\r\n        font-size: 1.1rem;\r\n        text-align: center;\r\n        color: #fff;\r\n        background: #4e1cb5;\r\n        line-height: 1.7rem;\r\n        font-weight: 400;\r\n        display: block;\r\n    }\r\n}\r\n\r\n@media (min-device-width: 1199px) {\r\n    .header__cart-total mark {\r\n        opacity: 1;\r\n    }\r\n}\r\n\r\n.header__nav-offcanvas {\r\n  .header__nav-acc {\r\n    .header__nav-acc-btn {\r\n      width: 6.925rem;\r\n    }\r\n  }\r\n  .header__nav-action {\r\n      width: 6.925rem;\r\n    .header__nav-action-line {\r\n      display: none;\r\n    }\r\n    .header__nav-action-btn:has(.icon-compare) {\r\n      display: none;\r\n    }\r\n  }\r\n  .header__nav-cart {\r\n    .header__nav-cart-btn {\r\n      padding: 0.5rem 0rem 0.5rem 2rem;\r\n      .header__nav-cart-total mark {\r\n        position: relative;\r\n        top: 1rem;\r\n        right: 2rem;\r\n        opacity: 1;\r\n        width: 1.7rem;\r\n        height: 1.7rem;\r\n        border-radius: 50%;\r\n        font-size: 1.1rem;\r\n        text-align: center;\r\n        color: #fff;\r\n        background: #4e1cb5;\r\n        line-height: 1.7rem;\r\n        font-weight: 400;\r\n        display: block;\r\n    }\r\n      .header__nav-cart-total {\r\n             .cart-total-text {\r\n          display: none;\r\n        }\r\n      }  \r\n}       \r\n    }\r\n  }\r\n\r\n@media (min-device-width: 1199px) {\r\n    .header__action-btn {\r\n        width: 5.35rem;\r\n    }\r\n}\r\n\r\n@media (min-device-width: 1199px) {\r\n    .header__acc-btn {\r\n        width: 5.55rem;\r\n    }\r\n}\r\n\r\n.header__mobile {\r\n  .header__cart {\r\n    .header__cart-counter mark {\r\n        line-height: unset;\r\n        font-size: 1.2rem;\r\n        margin-top: 100%;\r\n        background: #4e1cb5;\r\n        font-weight: 500;\r\n    }\r\n  }\r\n}\r\n\r\n.cart-total-text {\r\n    display: none;\r\n  }\r\n\r\n.header__action {\r\n  .header__action-line {\r\n    display: none;\r\n  }\r\n}\r\n\r\n.header__nav-action-btn mark {\r\n   margin-top: 35%;\r\n}\r\n\r\n.header__action-btn mark {\r\n   margin-top: 30%;\r\n}\r\n\r\n.categories {\r\n  .swiper-slide {\r\n    .categories__item-link {\r\n      background: rgba(0, 0, 0, 0.6);\r\n    }\r\n    .categories__item-link:hover {\r\n      background: #fff;\r\n    }\r\n  }\r\n}\r\n\r\n.brands-featured__all {\r\n  .ui-link {\r\n    display: none;\r\n  }\r\n}\r\n\r\n.row {\r\n  .benefits__item-image img {\r\n    max-width: 120%;\r\n  }\r\n}\r\n\r\n.intro__swiper {\r\n   transition: all 0.3s ease;\r\n}\r\n\r\n.intro__swiper:hover {\r\n  box-shadow: 0 0 2vw rgba(255,255,255,.7),\r\n              0 0 1.2vw #5401ff;\r\n}\r\n.sku__credit-action {\r\n  .buy_in_credit {\r\n    background: #5f21dd !important;\r\n    color: white !important;\r\n  }\r\n}\r\n\r\n.ui-group {\r\n  .ui-checklist {\r\n    \r\n     .ui-check__option {\r\n       border-radius: 6px !important;\r\n     }\r\n    \r\n     .ui-check__option img {\r\n      margin: 0 !important;\r\n       height: 2.8rem;\r\n       width: 4rem;\r\n    }\r\n  }\r\n}\r\n\r\n.ui-btn--compare {\r\n  display: none !important;\r\n}\r\n\r\n.products__item-in {\r\n  .products__item-price {\r\n    justify-content: center;\r\n  }\r\n  .ui-add-to-cart {\r\n    justify-content: center;\r\n  }\r\n}\r\n.header__call-btn mark {\r\n  opacity: 1;\r\n}\r\n\r\n.checkout__step-body {\r\n  #collapse-checkout-confirm h2 {\r\n    display: none;\r\n  }\r\n    #collapse-checkout-confirm {\r\n      .well {\r\n        display: none;\r\n      }\r\n  }\r\n}\r\n\r\n.benefits__item-title:hover {\r\n  color: #5401ff;\r\n}\r\n\r\n.benefits__item:hover {\r\n  .benefits__item-title {\r\n    color: #5401ff;\r\n  }\r\n}\r\n\r\n.seo__wrapper {\r\n  .ui-link {\r\n    color: #5401ff !important;\r\n  }\r\n}\r\n\r\n.categories {\r\n  .categories__item-image img {\r\n    max-width: none;\r\n  }\r\n}\r\n\r\n.ui-badge--orange {\r\n  background: #5610e5 !important;\r\n}\r\n\r\n.ui-badge--purple {\r\n  background: #333333 !important;\r\n}\r\n\r\n.sku__credit-help {\r\n  display: none !important;\r\n}', '0');
